-- ============================================================================
-- 006 — 006_wallet_ledger_corrections.sql
-- keeps wallet debits out of the revenue total
-- ============================================================================

-- Migration: 006_wallet_ledger_corrections.sql
--
-- Corrects two things about the functions added in 005, and adds one more.
--
-- 1. DEBITS MUST NOT COUNT AS REVENUE
--
--    processed_payments is summed as revenue:
--
--      src/app/actions/global-aggregation.ts
--        db.collection(PROCESSED_PAYMENTS)
--          .where("status", "==", "completed")
--          .select("amount")
--
--    `status` is not a native column on processed_payments, so that filter
--    reads raw_data->>'status'. 005's debit_wallet_once wrote 'completed'
--    there, which would have counted every marketplace wallet checkout as
--    revenue — on top of the Paystack payment that funded the wallet in the
--    first place. The same money, banked twice.
--
--    The original checkout code never wrote to processed_payments at all, so
--    this was introduced by 005 rather than inherited. Debits now write
--    status 'wallet_debit', which the revenue query does not match.
--
-- 2. CREDITS NEED A STATUS THAT IS NOT ALWAYS 'completed'
--
--    A refund returning money to a wallet is not revenue either. credit_wallet_once
--    now takes p_status so callers can distinguish 'completed' (a real payment
--    in) from 'refund' (money going back).
--
-- 3. NOT EVERY DEBIT HAS AN IDEMPOTENCY KEY
--
--    A withdrawal request is a fresh intent each time — there is no stable
--    reference to claim, and two genuine requests should both succeed. What it
--    still needs is the row lock, so two concurrent requests cannot both pass
--    the sufficiency check and overdraw. debit_wallet_locked does the locking
--    without claiming a reference or writing a payment row.
--
-- SAFE TO APPLY
--   Replaces two functions and adds a third. No table, column or row is
--   touched. Inert until code calls it. If 005 was never applied, this file
--   still works — every function here is CREATE OR REPLACE.

BEGIN;

-- ============================================================================
-- credit_wallet_once — now with an explicit payment status.
-- ============================================================================

CREATE OR REPLACE FUNCTION credit_wallet_once(
    p_reference    TEXT,
    p_user_id      TEXT,
    p_amount       NUMERIC,
    p_payment_type TEXT DEFAULT NULL,
    p_source       TEXT DEFAULT NULL,
    p_raw_data     JSONB DEFAULT '{}'::jsonb,
    p_status       TEXT DEFAULT 'completed'
)
RETURNS TABLE (claimed BOOLEAN, balance NUMERIC)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_rows    INT;
    v_balance NUMERIC;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'credit_wallet_once: amount must be positive, got %', p_amount;
    END IF;

    INSERT INTO processed_payments (id, user_id, amount, reference, raw_data)
    VALUES (
        p_reference,
        p_user_id,
        p_amount,
        p_reference,
        COALESCE(p_raw_data, '{}'::jsonb)
            || jsonb_build_object(
                'reference',   p_reference,
                'userId',      p_user_id,
                'amount',      p_amount,
                'type',        p_payment_type,
                'source',      p_source,
                'status',      COALESCE(p_status, 'completed'),
                'processedAt', to_char(NOW() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
            )
    )
    ON CONFLICT (id) DO NOTHING;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        SELECT w.balance INTO v_balance FROM wallets w WHERE w.id = p_user_id;
        RETURN QUERY SELECT FALSE, COALESCE(v_balance, 0::NUMERIC);
        RETURN;
    END IF;

    INSERT INTO wallets (id, balance)
    VALUES (p_user_id, p_amount)
    ON CONFLICT (id) DO UPDATE
        SET balance    = wallets.balance + EXCLUDED.balance,
            updated_at = NOW()
    RETURNING wallets.balance INTO v_balance;

    RETURN QUERY SELECT TRUE, v_balance;
END;
$$;

-- ============================================================================
-- debit_wallet_once — records status 'wallet_debit' so revenue excludes it.
-- ============================================================================

CREATE OR REPLACE FUNCTION debit_wallet_once(
    p_reference TEXT,
    p_user_id   TEXT,
    p_amount    NUMERIC,
    p_purpose   TEXT DEFAULT NULL,
    p_raw_data  JSONB DEFAULT '{}'::jsonb
)
RETURNS TABLE (ok BOOLEAN, balance NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_rows    INT;
    v_balance NUMERIC;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'debit_wallet_once: amount must be positive, got %', p_amount;
    END IF;

    SELECT w.balance INTO v_balance
      FROM wallets w
     WHERE w.id = p_user_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, 'no_wallet'::TEXT;
        RETURN;
    END IF;

    IF v_balance < p_amount THEN
        RETURN QUERY SELECT FALSE, v_balance, 'insufficient_funds'::TEXT;
        RETURN;
    END IF;

    INSERT INTO processed_payments (id, user_id, amount, reference, raw_data)
    VALUES (
        p_reference,
        p_user_id,
        p_amount,
        p_reference,
        COALESCE(p_raw_data, '{}'::jsonb)
            || jsonb_build_object(
                'reference',   p_reference,
                'userId',      p_user_id,
                'amount',      p_amount,
                'type',        'wallet_debit',
                'purpose',     p_purpose,
                -- NOT 'completed': global-aggregation sums those as revenue.
                'status',      'wallet_debit',
                'processedAt', to_char(NOW() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
            )
    )
    ON CONFLICT (id) DO NOTHING;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RETURN QUERY SELECT FALSE, v_balance, 'already_processed'::TEXT;
        RETURN;
    END IF;

    UPDATE wallets
       SET balance    = wallets.balance - p_amount,
           updated_at = NOW()
     WHERE wallets.id = p_user_id
    RETURNING wallets.balance INTO v_balance;

    RETURN QUERY SELECT TRUE, v_balance, NULL::TEXT;
END;
$$;

-- ============================================================================
-- debit_wallet_locked — atomic debit with no idempotency claim.
--
-- For debits that have no stable reference, such as a withdrawal request.
-- Locks the wallet row before the sufficiency check so concurrent debits
-- serialise; writes no payment row.
-- ============================================================================

CREATE OR REPLACE FUNCTION debit_wallet_locked(
    p_user_id TEXT,
    p_amount  NUMERIC
)
RETURNS TABLE (ok BOOLEAN, balance NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_balance NUMERIC;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'debit_wallet_locked: amount must be positive, got %', p_amount;
    END IF;

    SELECT w.balance INTO v_balance
      FROM wallets w
     WHERE w.id = p_user_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, 'no_wallet'::TEXT;
        RETURN;
    END IF;

    IF v_balance < p_amount THEN
        RETURN QUERY SELECT FALSE, v_balance, 'insufficient_funds'::TEXT;
        RETURN;
    END IF;

    UPDATE wallets
       SET balance    = wallets.balance - p_amount,
           updated_at = NOW()
     WHERE wallets.id = p_user_id
    RETURNING wallets.balance INTO v_balance;

    RETURN QUERY SELECT TRUE, v_balance, NULL::TEXT;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION
-- ============================================================================
--
--   SELECT proname FROM pg_proc
--    WHERE proname IN ('credit_wallet_once', 'debit_wallet_once', 'debit_wallet_locked');
--
-- Confirm a debit is not counted as revenue:
--
--   SELECT raw_data->>'status' FROM processed_payments WHERE id = '<a debit reference>';
--   -- expect 'wallet_debit', never 'completed'

-- ============================================================================
-- ROLLBACK
-- ============================================================================
--
-- DROP FUNCTION IF EXISTS debit_wallet_locked(TEXT, NUMERIC);
-- -- and re-apply 005 to restore the previous two definitions.


-- ============================================================================
-- 007 — 007_status_transition_cas.sql
-- compare-and-swap for status transitions
-- ============================================================================

-- Migration: 007_status_transition_cas.sql
--
-- A compare-and-swap for document status, so a state machine cannot be
-- advanced twice.
--
-- WHY THIS EXISTS
-- ---------------
-- Withdrawal approval moves a record pending → payout_initiated → completed,
-- and each step was a check-then-write inside runTransaction:
--
--     const fresh = await t.get(txnRef);
--     if (fresh.data()?.status !== "pending") throw ...;
--     t.update(txnRef, { status: "payout_initiated" });
--
-- runTransaction takes no lock, so two admins approving the same withdrawal at
-- once both read "pending", both write "payout_initiated", and both continue to
-- the Paystack transfer call. The user is paid twice, out of the business's
-- money, and nothing errors.
--
-- No balance is involved — the wallet was already debited when the withdrawal
-- was requested — so the wallet functions in 005/006 do not cover this. What is
-- needed is a conditional update: change the status ONLY IF it is still the
-- value we expect, and report whether we were the one who changed it.
--
--     UPDATE ... WHERE raw_data->>'status' = p_from
--
-- A single UPDATE takes a row lock for its duration and re-reads under it, so
-- exactly one of two concurrent callers matches the WHERE clause. The loser
-- gets 0 rows and knows to stop.
--
-- GENERAL, DELIBERATELY
-- ---------------------
-- Written against document_collections rather than withdrawals specifically,
-- because the same check-then-write shape appears throughout this codebase
-- (order fulfilment, escrow release, loan approval). Reuse it rather than
-- writing another one.
--
-- SAFE TO APPLY
--   Adds one function. No table, column or row is touched. Inert until called.

BEGIN;

-- ============================================================================
-- claim_status_transition
--
-- Advances a document_collections row from one status to another, but only if
-- it currently holds the expected status.
--
-- Arguments:
--   p_collection  collection_name, e.g. 'wallet_transactions'
--   p_id          document id
--   p_from        the status the caller believes the row is in
--   p_to          the status to move it to
--   p_patch       additional raw_data fields to merge in (optional)
--
-- Returns:
--   claimed  TRUE  when this call performed the transition
--            FALSE when the row was missing, or was not in p_from — meaning
--                  somebody else already moved it
--   status   the row's status after the call, or NULL when the row is missing.
--            Use it to tell "already advanced" from "never existed".
-- ============================================================================

CREATE OR REPLACE FUNCTION claim_status_transition(
    p_collection TEXT,
    p_id         TEXT,
    p_from       TEXT,
    p_to         TEXT,
    p_patch      JSONB DEFAULT '{}'::jsonb
)
RETURNS TABLE (claimed BOOLEAN, status TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_rows    INT;
    v_current TEXT;
BEGIN
    IF p_from IS NULL OR p_to IS NULL THEN
        RAISE EXCEPTION 'claim_status_transition: from and to are required';
    END IF;

    -- The whole mechanism. Two concurrent callers cannot both match this
    -- WHERE clause: the UPDATE locks the row and re-evaluates under the lock.
    UPDATE document_collections
       SET raw_data   = raw_data
                        || COALESCE(p_patch, '{}'::jsonb)
                        || jsonb_build_object(
                             'status',    p_to,
                             'updatedAt', to_char(NOW() AT TIME ZONE 'UTC',
                                                  'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
                           ),
           updated_at = NOW()
     WHERE id              = p_id
       AND collection_name = p_collection
       AND raw_data->>'status' = p_from;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows > 0 THEN
        RETURN QUERY SELECT TRUE, p_to;
        RETURN;
    END IF;

    -- We lost, or the row is not there. Report which.
    SELECT d.raw_data->>'status' INTO v_current
      FROM document_collections d
     WHERE d.id = p_id
       AND d.collection_name = p_collection;

    RETURN QUERY SELECT FALSE, v_current;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging after applying.
