--   -- expect: t, completed
--
--   SELECT * FROM claim_payment_once('t-claim-1', 't-user', 500, 'marketplace_order');
--   -- expect: f, completed   <-- the duplicate webhook that used to fulfil twice
--
--   DELETE FROM processed_payments WHERE id = 't-claim-1';
--
-- Revenue check — a claim marked completed IS counted as revenue by
-- global-aggregation, which is correct for an inbound payment. Pass a
-- different p_status for anything that is not money in.

-- ============================================================================
-- ROLLBACK
-- ============================================================================
--
-- DROP FUNCTION IF EXISTS claim_payment_once(TEXT, TEXT, NUMERIC, TEXT, TEXT, JSONB, TEXT);


-- ============================================================================
-- 010 — 010_atomic_increments.sql
-- atomic FieldValue.increment — MUST ship with the code that guards it
-- ============================================================================

-- Migration: 010_atomic_increments.sql
--
-- Makes FieldValue.increment actually atomic.
--
-- WHY THIS EXISTS
-- ---------------
-- FieldValue.increment is the idiom you reach for SPECIFICALLY to avoid
-- read-modify-write. In this codebase it was one. SupabaseDocumentReference.update
-- read the document, resolved the sentinel in JavaScript against the value it had
-- just read, and wrote the result:
--
--     const snap = await this.get();
--     const existing = snap.data() ?? {};
--     ...
--     case 'FieldValue.increment':
--         return (typeof existing === 'number' ? existing : 0) + (fvObj._operand || 0);
--
-- Two concurrent increments read the same value, computed the same result, and
-- the second write overwrote the first. One increment was silently lost.
--
-- 142 call sites across 37 files went through that path, including seller wallet
-- credits on escrow release, dispute resolution credits, loan disbursement and
-- repayment, savings and locked balances, and WAVE earnings.
--
-- This function performs the addition inside the database, in one statement, so
-- concurrent increments sum instead of overwriting.
--
-- TWO KINDS OF TARGET
-- -------------------
-- Values live in two places and both must work:
--
--   native columns  wallets.balance, cooperative_loans.amount and so on — real
--                   typed SQL columns, listed in NATIVE_COLUMNS in supabase-db.ts
--
--   raw_data paths  everything else, inside the JSONB blob, including dotted
--                   paths like serviceRegistrations.wave.waveEarningsBalance
--
-- The caller decides which is which — supabase-db.ts already holds that mapping —
-- and passes them separately. Column names are quoted with quote_ident and the
-- table name is checked against a fixed allowlist, so a caller cannot reach
-- outside the schema.
--
-- A NATIVE COLUMN MUST BE WRITTEN IN BOTH PLACES
-- ----------------------------------------------
-- This is the part that is easy to get wrong, and it is not symmetric.
--
-- buildDedicatedRow writes the WHOLE document into raw_data and additionally
-- copies mapped fields into their native columns, so `balance` exists twice:
-- wallets.balance and wallets.raw_data->>'balance'.
--
-- Reads prefer raw_data. SupabaseDocumentReference.get() hydrates from raw_data
-- and never consults wallets.balance at all; SupabaseQuery.get() falls back to
-- the native column only when raw_data has no such key. Since every document
-- written through the adapter has the key, the native column is effectively
-- invisible to the application.
--
-- So updating only the native column produces a change nobody can see. Both are
-- written here, and both are derived from the raw_data value, which converges
-- the two if they have already drifted apart.
--
-- SAFE TO APPLY
--   Adds one function. No table, column or row is touched. Inert until called.

BEGIN;

CREATE OR REPLACE FUNCTION apply_increments(
    p_table      TEXT,
    p_id         TEXT,
    p_collection TEXT DEFAULT NULL,        -- set for document_collections only
    p_native     JSONB DEFAULT '{}'::jsonb, -- {"balance": 500}
    p_json       JSONB DEFAULT '{}'::jsonb  -- {"stats.count": 1, "a.b.c": -2}
)
RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_key      TEXT;
    v_val      NUMERIC;
    v_sets     TEXT[] := ARRAY[]::TEXT[];
    v_raw      TEXT := 'raw_data';
    v_path     TEXT[];
    v_sql      TEXT;
    v_allowed  TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'apply_increments: table % is not allowed', p_table;
    END IF;

    IF p_id IS NULL OR TRIM(p_id) = '' THEN
        RAISE EXCEPTION 'apply_increments: id is required';
    END IF;

    -- Native typed columns.
    --
    -- Written in BOTH places, and both derived from the raw_data value, because
    -- reads prefer raw_data and the native column is only a fallback. Updating
    -- the column alone would be invisible to the application.
    FOR v_key, v_val IN
        SELECT k, (v #>> '{}')::numeric FROM jsonb_each(COALESCE(p_native, '{}'::jsonb)) AS t(k, v)
    LOOP
        v_sets := v_sets || format(
            '%1$I = COALESCE((raw_data ->> %2$L)::numeric, %1$I, 0) + %3$L::numeric',
            v_key, v_key, v_val
        );

        v_raw := format(
            'jsonb_set(%1$s, ARRAY[%2$L], to_jsonb(COALESCE((%1$s ->> %2$L)::numeric, %3$I, 0) + %4$L::numeric), true)',
            v_raw, v_key, v_key, v_val
        );
    END LOOP;

    -- raw_data paths, applied left to right so several can land in one statement.
    -- jsonb_set with create_missing = true means a counter that does not exist
    -- yet starts from zero rather than failing.
    FOR v_key, v_val IN
        SELECT k, (v #>> '{}')::numeric FROM jsonb_each(COALESCE(p_json, '{}'::jsonb)) AS t(k, v)
    LOOP
        v_path := string_to_array(v_key, '.');
        v_raw := format(
            'jsonb_set_deep(%1$s, %2$L::text[], to_jsonb(COALESCE((%1$s #>> %2$L::text[])::numeric, 0) + %3$L::numeric))',
            v_raw, v_path, v_val
        );
    END LOOP;

    IF v_raw <> 'raw_data' THEN
        v_sets := v_sets || format('raw_data = %s', v_raw);
    END IF;

    IF array_length(v_sets, 1) IS NULL THEN
        RETURN; -- nothing to do
    END IF;

    -- Cast required. An untyped literal makes Postgres resolve || as
    -- array-concat-array and try to parse the string as TEXT[], which fails
    -- with "malformed array literal". The format() appends above are typed
    -- TEXT and so were unaffected, which is why this went unnoticed: the
    -- function errored only once it had something to write.
    v_sets := v_sets || 'updated_at = NOW()'::TEXT;

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'UPDATE document_collections SET %s WHERE id = %L AND collection_name = %L',
            array_to_string(v_sets, ', '), p_id, p_collection
        );
    ELSE
        v_sql := format(
            'UPDATE %I SET %s WHERE id = %L',
            p_table, array_to_string(v_sets, ', '), p_id
        );
    END IF;

    EXECUTE v_sql;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging.
-- ============================================================================
--
-- Native column:
--
--   INSERT INTO wallets (id, balance) VALUES ('t-inc-1', 100)
--     ON CONFLICT (id) DO UPDATE SET balance = 100;
--   SELECT apply_increments('wallets', 't-inc-1', NULL, '{"balance": 50}'::jsonb, '{}'::jsonb);
--   SELECT balance FROM wallets WHERE id = 't-inc-1';   -- expect 150
--
-- raw_data path, including one that does not exist yet:
--
--   INSERT INTO document_collections (id, collection_name, raw_data)
--   VALUES ('t-inc-2', 'test_counters', '{"seen": 5}'::jsonb)
--     ON CONFLICT (id, collection_name) DO UPDATE SET raw_data = '{"seen": 5}'::jsonb;
--   SELECT apply_increments('document_collections', 't-inc-2', 'test_counters',
--                           '{}'::jsonb, '{"seen": 3, "fresh": 7, "a.b": 2}'::jsonb);
--   SELECT raw_data FROM document_collections
--    WHERE id = 't-inc-2' AND collection_name = 'test_counters';
--   -- expect seen = 8, fresh = 7, a = {"b": 2}
--
-- THE CONCURRENCY TEST — two SQL Editor tabs. This is the point of the whole
-- migration, and the thing the old JavaScript path failed.
--
--   Tab A:  BEGIN;
--           SELECT apply_increments('wallets', 't-inc-1', NULL, '{"balance": 10}'::jsonb, '{}'::jsonb);
--           -- do not commit yet
--
--   Tab B:  SELECT apply_increments('wallets', 't-inc-1', NULL, '{"balance": 10}'::jsonb, '{}'::jsonb);
--           -- EXPECT: Tab B blocks on the row lock
--
--   Tab A:  COMMIT;
--
--   Then:   SELECT balance FROM wallets WHERE id = 't-inc-1';
--           -- expect 170 (150 + 10 + 10). BOTH increments applied.
--
--   Under the old JavaScript path this landed on 160: both read 150, both wrote
--   160, and one increment vanished.
--
-- Clean up:
--
--   DELETE FROM wallets WHERE id = 't-inc-1';
--   DELETE FROM document_collections WHERE id = 't-inc-2';

-- ============================================================================
-- ROLLBACK
-- ============================================================================
--
-- DROP FUNCTION IF EXISTS apply_increments(TEXT, TEXT, TEXT, JSONB, JSONB);
--
-- The adapter falls back to the previous JavaScript behaviour when the RPC is
-- unavailable, so dropping this restores the old semantics rather than breaking
-- writes.


-- ============================================================================
-- 011 — 011_wallet_balance_raw_data_sync.sql
-- corrects 005/006 to write the value the app actually reads
-- ============================================================================

-- Migration: 011_wallet_balance_raw_data_sync.sql
--
-- Corrects the wallet functions from 005/006, which updated a column the
-- application does not read.
--
-- WHAT WENT WRONG
-- ---------------
-- credit_wallet_once, debit_wallet_once and debit_wallet_locked all move money
-- by updating wallets.balance — the native SQL column. That is the obvious
-- thing to do, and it is wrong here.
--
-- buildDedicatedRow in supabase-db.ts writes the WHOLE document into raw_data
-- and additionally copies mapped fields into native columns, so a wallet
-- carries its balance twice: wallets.balance and wallets.raw_data->>'balance'.
--
-- Reads prefer raw_data:
--
--   SupabaseDocumentReference.get()  hydrates from raw_data and never consults
--                                    wallets.balance at all
--   SupabaseQuery.get()              falls back to the native column ONLY when
--                                    raw_data has no such key
--
-- Every wallet created through the adapter has raw_data.balance, so the native
-- column is effectively invisible to the application. A credit applied to it
-- alone changes nothing the user or the app can see.
--
-- HOW THIS WAS MISSED
-- -------------------
-- 005/006 were verified on staging with SELECT balance FROM wallets and by
-- reading the functions' own return values — both the native column. Neither
-- check went through the application's read path, so both agreed with each
-- other and with nothing else.
--
-- THE FIX
-- -------
-- Every balance write updates both places, and both are derived from the
-- raw_data value. Deriving from raw_data rather than the column means a wallet
-- whose two copies have already drifted converges on the value the application
-- has been showing the user, rather than silently adopting the other one.
--
-- SAFE TO APPLY
--   Replaces three functions. No table, column or row is touched. If 005/006
--   were applied and any balance moved through them, see the reconciliation
--   query at the bottom before running this.

BEGIN;

-- ============================================================================
-- credit_wallet_once — writes raw_data.balance and wallets.balance together.
-- ============================================================================

CREATE OR REPLACE FUNCTION credit_wallet_once(
    p_reference    TEXT,
    p_user_id      TEXT,
    p_amount       NUMERIC,
    p_payment_type TEXT DEFAULT NULL,
    p_source       TEXT DEFAULT NULL,
    p_raw_data     JSONB DEFAULT '{}'::jsonb,
    p_status       TEXT DEFAULT 'completed'
)
RETURNS TABLE (claimed BOOLEAN, balance NUMERIC)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_rows    INT;
    v_balance NUMERIC;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'credit_wallet_once: amount must be positive, got %', p_amount;
    END IF;

    INSERT INTO processed_payments (id, user_id, amount, reference, raw_data)
    VALUES (
        p_reference, p_user_id, p_amount, p_reference,
        COALESCE(p_raw_data, '{}'::jsonb)
            || jsonb_build_object(
                'reference', p_reference, 'userId', p_user_id, 'amount', p_amount,
                'type', p_payment_type, 'source', p_source,
                'status', COALESCE(p_status, 'completed'),
                'processedAt', to_char(NOW() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
            )
    )
    ON CONFLICT (id) DO NOTHING;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        SELECT COALESCE((w.raw_data ->> 'balance')::numeric, w.balance, 0)
          INTO v_balance FROM wallets w WHERE w.id = p_user_id;
        RETURN QUERY SELECT FALSE, COALESCE(v_balance, 0::NUMERIC);
        RETURN;
    END IF;

    INSERT INTO wallets (id, balance, raw_data)
    VALUES (
        p_user_id,
        p_amount,
        jsonb_build_object('id', p_user_id, 'userId', p_user_id,
                           'balance', p_amount, 'currency', 'NGN')
    )
    ON CONFLICT (id) DO UPDATE
        SET balance    = COALESCE((wallets.raw_data ->> 'balance')::numeric, wallets.balance, 0) + p_amount,
            raw_data   = jsonb_set(
                             COALESCE(wallets.raw_data, '{}'::jsonb),
                             ARRAY['balance'],
                             to_jsonb(COALESCE((wallets.raw_data ->> 'balance')::numeric, wallets.balance, 0) + p_amount),
                             true
                         ),
            updated_at = NOW()
    RETURNING COALESCE((wallets.raw_data ->> 'balance')::numeric, wallets.balance, 0) INTO v_balance;

    RETURN QUERY SELECT TRUE, v_balance;
END;
$$;

-- ============================================================================
-- debit_wallet_once
-- ============================================================================

CREATE OR REPLACE FUNCTION debit_wallet_once(
    p_reference TEXT,
    p_user_id   TEXT,
    p_amount    NUMERIC,
    p_purpose   TEXT DEFAULT NULL,
    p_raw_data  JSONB DEFAULT '{}'::jsonb
)
RETURNS TABLE (ok BOOLEAN, balance NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_rows    INT;
    v_balance NUMERIC;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'debit_wallet_once: amount must be positive, got %', p_amount;
    END IF;

    SELECT COALESCE((w.raw_data ->> 'balance')::numeric, w.balance, 0)
      INTO v_balance
      FROM wallets w
     WHERE w.id = p_user_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, 'no_wallet'::TEXT;
        RETURN;
    END IF;

    IF v_balance < p_amount THEN
        RETURN QUERY SELECT FALSE, v_balance, 'insufficient_funds'::TEXT;
        RETURN;
    END IF;

    INSERT INTO processed_payments (id, user_id, amount, reference, raw_data)
    VALUES (
        p_reference, p_user_id, p_amount, p_reference,
        COALESCE(p_raw_data, '{}'::jsonb)
            || jsonb_build_object(
                'reference', p_reference, 'userId', p_user_id, 'amount', p_amount,
                'type', 'wallet_debit', 'purpose', p_purpose,
                -- NOT 'completed': global-aggregation sums those as revenue.
                'status', 'wallet_debit',
                'processedAt', to_char(NOW() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
            )
    )
    ON CONFLICT (id) DO NOTHING;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RETURN QUERY SELECT FALSE, v_balance, 'already_processed'::TEXT;
        RETURN;
    END IF;

    UPDATE wallets
       SET balance    = v_balance - p_amount,
           raw_data   = jsonb_set(COALESCE(raw_data, '{}'::jsonb), ARRAY['balance'],
                                  to_jsonb(v_balance - p_amount), true),
           updated_at = NOW()
     WHERE wallets.id = p_user_id;

    RETURN QUERY SELECT TRUE, v_balance - p_amount, NULL::TEXT;
END;
$$;

-- ============================================================================
-- debit_wallet_locked
-- ============================================================================

CREATE OR REPLACE FUNCTION debit_wallet_locked(
    p_user_id TEXT,
    p_amount  NUMERIC
)
RETURNS TABLE (ok BOOLEAN, balance NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_balance NUMERIC;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'debit_wallet_locked: amount must be positive, got %', p_amount;
    END IF;

    SELECT COALESCE((w.raw_data ->> 'balance')::numeric, w.balance, 0)
      INTO v_balance
      FROM wallets w
     WHERE w.id = p_user_id
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, 'no_wallet'::TEXT;
        RETURN;
    END IF;

    IF v_balance < p_amount THEN
        RETURN QUERY SELECT FALSE, v_balance, 'insufficient_funds'::TEXT;
        RETURN;
    END IF;

    UPDATE wallets
       SET balance    = v_balance - p_amount,
           raw_data   = jsonb_set(COALESCE(raw_data, '{}'::jsonb), ARRAY['balance'],
                                  to_jsonb(v_balance - p_amount), true),
           updated_at = NOW()
     WHERE wallets.id = p_user_id;

    RETURN QUERY SELECT TRUE, v_balance - p_amount, NULL::TEXT;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — the check that 005/006 should have had.
-- ============================================================================
--
-- Set up a wallet the way the ADAPTER writes one, with the balance in both
-- places. This is the shape that exposed the bug; a wallet created with only
-- the native column would have hidden it.
--
--   INSERT INTO wallets (id, balance, raw_data)
--   VALUES ('t-sync-1', 100, '{"id":"t-sync-1","balance":100,"currency":"NGN"}'::jsonb)
--   ON CONFLICT (id) DO UPDATE
--     SET balance = 100, raw_data = '{"id":"t-sync-1","balance":100,"currency":"NGN"}'::jsonb;
--
--   SELECT * FROM credit_wallet_once('t-sync-ref-1', 't-sync-1', 50);
--   -- expect: t, 150
--
-- BOTH copies must now read 150. Before this migration the second was 100.
--
--   SELECT balance AS native_col,
--          (raw_data ->> 'balance')::numeric AS raw_data_value
--     FROM wallets WHERE id = 't-sync-1';
--   -- expect: 150, 150
--
-- raw_data_value is what the application actually shows the user. If it says
-- 100, the credit is invisible in the app no matter what the column says.
--
--   DELETE FROM processed_payments WHERE id LIKE 't-sync-%';
--   DELETE FROM wallets WHERE id = 't-sync-1';

-- ============================================================================
-- RECONCILIATION — only if 005/006 were applied and money moved through them.
-- ============================================================================
--
-- Wallets whose two copies disagree, worst first. raw_data is what the user has
-- been shown, so the difference is what the column gained invisibly:
--
--   SELECT id,
--          (raw_data ->> 'balance')::numeric AS shown_to_user,
--          balance                            AS native_column,
--          balance - (raw_data ->> 'balance')::numeric AS drift
--     FROM wallets
--    WHERE raw_data ? 'balance'
--      AND balance IS DISTINCT FROM (raw_data ->> 'balance')::numeric
--    ORDER BY abs(balance - (raw_data ->> 'balance')::numeric) DESC;
--
-- Decide deliberately which copy is right before correcting anything. Do not
-- assume: a credit that never reached the user is a different problem from a
-- debit that never did.

-- ============================================================================
-- ROLLBACK — re-apply 005 then 006 to restore the previous definitions.
-- ============================================================================


-- ============================================================================
-- 012 — 012_platform_metrics.sql
-- platform revenue totals
-- ============================================================================

-- Migration: 012_platform_metrics.sql
--
-- Totals computed in the database instead of by fetching rows.
--
-- WHY THIS EXISTS
-- ---------------
-- getPlatformMetricsAction computed total revenue like this:
--
--     const snap = await db.collection(PROCESSED_PAYMENTS)
--         .where("status", "==", "completed")
--         .select("amount")
--         .get();
--     snap.docs.forEach(d => { totalRevenue += Number(d.data().amount) || 0 });
--     totalTransactions = snap.docs.length;
--
-- Three problems in six lines:
--
-- 1. The query has no .limit(), so it inherited the 5,000-row default cap.
--    Total revenue was the sum of at most 5,000 payments regardless of how many
--    exist. A table cannot be totalled by fetching its rows.
--
-- 2. A .count() query on the same table ran alongside it and its result was
--    never used — totalTransactions came from the truncated docs.length.
--
-- 3. Promise.allSettled meant a rejected query left the totals at 0 while the
--    function still returned success: true, error: null. A failure displayed as
--    ₦0 revenue, indistinguishable from a genuinely quiet day.
--
-- WHICH AMOUNT IS AUTHORITATIVE
-- -----------------------------
-- `amount` exists twice on processed_payments: the native column and
-- raw_data->>'amount'. The adapter's reads prefer raw_data, so that is what the
-- application has been showing. This sums COALESCE(raw_data, column, 0) to match
-- what users see rather than what the column happens to hold — the same
-- distinction that made migrations 005/006 update a value nobody read.
--
-- `status` is not a native column, so it is filtered from raw_data. Note that
-- wallet debits record status 'wallet_debit' (migration 006) precisely so they
-- are not counted here as income.
--
-- SAFE TO APPLY
--   Adds one read-only function. No table, column or row is touched.

BEGIN;

-- ============================================================================
-- platform_revenue_totals
--
-- Returns:
--   total_revenue      sum of completed payment amounts
--   transaction_count  number of completed payments
--
-- Both computed over the whole table, in one statement.
-- ============================================================================

CREATE OR REPLACE FUNCTION platform_revenue_totals()
RETURNS TABLE (total_revenue NUMERIC, transaction_count BIGINT)
LANGUAGE sql STABLE SECURITY DEFINER
AS $$
    SELECT
        COALESCE(SUM(COALESCE((p.raw_data ->> 'amount')::numeric, p.amount, 0)), 0)::numeric,
        COUNT(*)::bigint
      FROM processed_payments p
     WHERE p.raw_data ->> 'status' = 'completed';
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging.
-- ============================================================================
--
--   SELECT * FROM platform_revenue_totals();
--
-- Cross-check against the old, truncated approach. If the table holds more than
-- 5,000 completed payments these will differ, and the difference is exactly
-- what the dashboard was failing to report:
--
--   SELECT COUNT(*) AS completed_payments
--     FROM processed_payments
--    WHERE raw_data ->> 'status' = 'completed';
--
--   SELECT SUM(COALESCE((raw_data ->> 'amount')::numeric, amount, 0)) AS first_5000
--     FROM (SELECT raw_data, amount FROM processed_payments
--            WHERE raw_data ->> 'status' = 'completed' LIMIT 5000) t;
--
-- Confirm debits are excluded — they should never count as income:
--
--   SELECT raw_data ->> 'status' AS status, COUNT(*)
--     FROM processed_payments GROUP BY 1 ORDER BY 2 DESC;
--   -- 'wallet_debit' rows must not appear in the revenue total above

-- ============================================================================
-- ROLLBACK
-- ============================================================================
--
-- DROP FUNCTION IF EXISTS platform_revenue_totals();


-- ============================================================================
-- 013 — 013_debit_jsonb_balance.sql
-- locked debit for raw_data balances
-- ============================================================================

-- Migration: 013_debit_jsonb_balance.sql
--
-- A locked, checked debit for balances that live inside raw_data.
--
-- WHY THIS EXISTS
-- ---------------
-- 005/006/011 gave wallets an atomic debit, but they are specific to the
-- `wallets` table and its native `balance` column. Cooperative savings are not
-- there: `cooperative_members.savingsBalance` lives in the raw_data JSONB blob,
-- and two paths debit it with the same read-check-write that wallets used to
-- have:
--
--     const currentBalance = membershipDoc.data()?.savingsBalance || 0;
--     if (amount > currentBalance) throw new Error("Insufficient savings balance");
--     transaction.update(ref, { savingsBalance: FieldValue.increment(-amount) });
--
-- The check takes no lock, so two withdrawals submitted at once both read the
-- same balance, both pass, and both debit. A member's savings goes negative.
--
-- Migration 010 made the increment itself atomic, which means both debits now
-- definitely land — before, one was likely lost, accidentally masking the
-- overdraft. Same interaction as the escrow cron: making increments correct
-- makes an unguarded check worse, not better.
--
-- WHAT THIS DOES
-- --------------
-- Locks the row with FOR UPDATE, re-reads the balance under that lock, refuses
-- if funds are short, and decrements — all in one statement inside one
-- transaction. Two concurrent callers serialise; the second sees the first's
-- result and is refused.
--
-- Deliberately generic over table and field: the same shape appears on
-- cooperative savings, locked balances and WAVE earnings. One primitive rather
-- than one per balance.
--
-- SAFE TO APPLY
--   Adds one function. No table, column or row is touched. Inert until called.

BEGIN;

CREATE OR REPLACE FUNCTION debit_jsonb_balance(
    p_table      TEXT,
    p_id         TEXT,
    p_field      TEXT,
    p_amount     NUMERIC,
    p_collection TEXT DEFAULT NULL   -- required for document_collections
)
RETURNS TABLE (ok BOOLEAN, balance NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_balance NUMERIC;
    v_sql     TEXT;
    v_allowed TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'debit_jsonb_balance: table % is not allowed', p_table;
    END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'debit_jsonb_balance: amount must be positive, got %', p_amount;
    END IF;

    -- Lock the row and read the balance under the lock. This is the whole
    -- mechanism: the check and the write cannot be separated by another caller.
    IF p_table = 'document_collections' THEN
        v_sql := format(
            'SELECT COALESCE((raw_data ->> %L)::numeric, 0) FROM document_collections '
            'WHERE id = %L AND collection_name = %L FOR UPDATE',
            p_field, p_id, p_collection
        );
    ELSE
        v_sql := format(
            'SELECT COALESCE((raw_data ->> %L)::numeric, 0) FROM %I WHERE id = %L FOR UPDATE',
            p_field, p_table, p_id
        );
    END IF;

    EXECUTE v_sql INTO v_balance;

    IF v_balance IS NULL THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, 'not_found'::TEXT;
        RETURN;
    END IF;

    IF v_balance < p_amount THEN
        RETURN QUERY SELECT FALSE, v_balance, 'insufficient_funds'::TEXT;
        RETURN;
    END IF;

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'UPDATE document_collections SET raw_data = jsonb_set(raw_data, ARRAY[%L], to_jsonb(%L::numeric), true), '
            'updated_at = NOW() WHERE id = %L AND collection_name = %L',
            p_field, v_balance - p_amount, p_id, p_collection
        );
    ELSE
        v_sql := format(
            'UPDATE %I SET raw_data = jsonb_set(raw_data, ARRAY[%L], to_jsonb(%L::numeric), true), '
            'updated_at = NOW() WHERE id = %L',
            p_table, p_field, v_balance - p_amount, p_id
        );
    END IF;

    EXECUTE v_sql;

    RETURN QUERY SELECT TRUE, v_balance - p_amount, NULL::TEXT;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging.
-- ============================================================================
--
--   INSERT INTO cooperative_members (id, user_id, status, raw_data)
--   VALUES ('t-deb-1', 't-user', 'active', '{"savingsBalance": 1000}'::jsonb)
--   ON CONFLICT (id) DO UPDATE SET raw_data = '{"savingsBalance": 1000}'::jsonb;
--
--   SELECT * FROM debit_jsonb_balance('cooperative_members', 't-deb-1', 'savingsBalance', 400);
--   -- expect: t, 600, NULL
--
--   SELECT * FROM debit_jsonb_balance('cooperative_members', 't-deb-1', 'savingsBalance', 900);
--   -- expect: f, 600, insufficient_funds   <-- the overdraft that used to go through
--
-- THE CONCURRENCY TEST — two SQL Editor tabs.
--
--   Tab A:  BEGIN;
--           SELECT * FROM debit_jsonb_balance('cooperative_members','t-deb-1','savingsBalance',400);
--           -- stop, do not commit
--
--   Tab B:  SELECT * FROM debit_jsonb_balance('cooperative_members','t-deb-1','savingsBalance',400);
--           -- EXPECT: Tab B blocks on the row lock
--
--   Tab A:  COMMIT;
--           -- Tab B then returns f, 200, insufficient_funds
--
--   Under the old read-check-write both would have succeeded, leaving -200.
--
--   DELETE FROM cooperative_members WHERE id = 't-deb-1';

-- ============================================================================
-- ROLLBACK
-- ============================================================================
--
-- DROP FUNCTION IF EXISTS debit_jsonb_balance(TEXT, TEXT, TEXT, NUMERIC, TEXT);


-- ============================================================================
-- 014 — 014_debit_nested_jsonb_balance.sql
-- extends 013 to nested paths — MUST come after 013
-- ============================================================================

-- Migration: 014_debit_nested_jsonb_balance.sql
--
-- Extends debit_jsonb_balance (013) to balances held at a NESTED path.
--
-- WHY
-- ---
-- 013 addressed `cooperative_members.savingsBalance` — a top-level key in
-- raw_data. WAVE earnings are not top-level:
--
--     serviceRegistrations.wave.waveEarningsBalance
--
-- and `_withdrawEarningsAction` debits it with the same defect, in a slightly
-- worse form: the sufficiency check happens BEFORE the transaction entirely
--
--     // PHASE 1: Balance Calculation (Snapshot)
--     if (earnings.data.paidAmount < amount) return "Insufficient available balance";
--     ...
--     transaction.update(userRef, {
--         'serviceRegistrations.wave.waveEarningsBalance': FieldValue.increment(-amount),
--     });
--
-- so the balance is read, released, and only then decremented. Two withdrawals
-- submitted at once both pass the check against the same snapshot and both
-- debit.
--
-- The `hasPendingWithdrawal` flag was intended to prevent exactly this, and is
-- itself a check-then-write inside the same lock-free transaction, so it does
-- not.
--
-- WHAT CHANGES
-- ------------
-- p_field is now treated as a dotted path and split on '.', so a single-segment
-- field behaves exactly as before. Existing callers are unaffected.
--
-- SAFE TO APPLY
--   Replaces one function. No table, column or row is touched. Backward
--   compatible: 'savingsBalance' still resolves to the same single-element path.

BEGIN;

CREATE OR REPLACE FUNCTION debit_jsonb_balance(
    p_table      TEXT,
    p_id         TEXT,
    p_field      TEXT,
    p_amount     NUMERIC,
    p_collection TEXT DEFAULT NULL
)
RETURNS TABLE (ok BOOLEAN, balance NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_balance NUMERIC;
    v_path    TEXT[];
    v_sql     TEXT;
    v_allowed TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'debit_jsonb_balance: table % is not allowed', p_table;
    END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'debit_jsonb_balance: amount must be positive, got %', p_amount;
    END IF;

    -- A dotted field becomes a JSONB path. A single segment yields a
    -- one-element array, which is what 013 used, so existing callers are
    -- unchanged.
    v_path := string_to_array(p_field, '.');

    -- Lock the row and read the balance under the lock.
    IF p_table = 'document_collections' THEN
        v_sql := format(
            'SELECT COALESCE((raw_data #>> %L::text[])::numeric, 0) FROM document_collections '
            'WHERE id = %L AND collection_name = %L FOR UPDATE',
            v_path, p_id, p_collection
        );
    ELSE
        v_sql := format(
            'SELECT COALESCE((raw_data #>> %L::text[])::numeric, 0) FROM %I WHERE id = %L FOR UPDATE',
            v_path, p_table, p_id
        );
    END IF;

    EXECUTE v_sql INTO v_balance;

    IF v_balance IS NULL THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, 'not_found'::TEXT;
        RETURN;
    END IF;

    IF v_balance < p_amount THEN
        RETURN QUERY SELECT FALSE, v_balance, 'insufficient_funds'::TEXT;
        RETURN;
    END IF;

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'UPDATE document_collections SET raw_data = jsonb_set(raw_data, %L::text[], to_jsonb(%L::numeric), true), '
            'updated_at = NOW() WHERE id = %L AND collection_name = %L',
            v_path, v_balance - p_amount, p_id, p_collection
        );
    ELSE
        v_sql := format(
            'UPDATE %I SET raw_data = jsonb_set(raw_data, %L::text[], to_jsonb(%L::numeric), true), '
            'updated_at = NOW() WHERE id = %L',
            p_table, v_path, v_balance - p_amount, p_id
        );
    END IF;

    EXECUTE v_sql;

    RETURN QUERY SELECT TRUE, v_balance - p_amount, NULL::TEXT;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging.
-- ============================================================================
--
-- Nested path:
--
--   INSERT INTO users (id, email, raw_data)
--   VALUES ('t-wave-1', 't-wave-1@example.com',
--           '{"serviceRegistrations":{"wave":{"waveEarningsBalance":10000}}}'::jsonb)
--   ON CONFLICT (id) DO UPDATE
--     SET raw_data = '{"serviceRegistrations":{"wave":{"waveEarningsBalance":10000}}}'::jsonb;
--
--   SELECT * FROM debit_jsonb_balance(
--       'users', 't-wave-1', 'serviceRegistrations.wave.waveEarningsBalance', 6000);
--   -- expect: t, 4000, NULL
--
--   SELECT * FROM debit_jsonb_balance(
--       'users', 't-wave-1', 'serviceRegistrations.wave.waveEarningsBalance', 6000);
--   -- expect: f, 4000, insufficient_funds   <-- the second withdrawal that used to go through
--
--   SELECT raw_data #> '{serviceRegistrations,wave}' FROM users WHERE id = 't-wave-1';
--   -- confirm only waveEarningsBalance changed; siblings intact
--
--   DELETE FROM users WHERE id = 't-wave-1';
--
-- Single-segment path still behaves as in 013:
--
--   SELECT * FROM debit_jsonb_balance('cooperative_members', '<id>', 'savingsBalance', 100);

-- ============================================================================
-- ROLLBACK — re-apply 013 to restore the single-segment version.
-- ============================================================================


-- ============================================================================
-- 015 — 015_bounded_counters.sql
-- bounded counters — MUST ship with the code that guards stock and capacity
-- ============================================================================

-- Migration: 015_bounded_counters.sql
--
-- Counters that may only move while they stay within a bound.
--
-- WHY THIS EXISTS
-- ---------------
-- Two places check a bound and then change a counter, with no lock between:
--
--   marketplace stock      if (currentQty >= item.quantity)
--                              availableQuantity += -item.quantity
--
--   training capacity      if (currentParticipants >= maxParticipants) throw
--                              currentParticipants += 1
--
-- Two buyers taking the last unit both pass; two registrations for the last
-- seat both pass. Stock goes negative and the session is oversold.
--
-- Migration 010 makes both WORSE rather than better — the fourth and fifth
-- places that is true. The increments used to lose one another, which hid the
-- overshoot; once they apply correctly, both land.
--
-- WHY NOT debit_jsonb_balance (013/014)
-- -------------------------------------
-- It does exactly this for a single field, and stock could use it — except an
-- order decrements SEVERAL products, and it must be all-or-nothing. Calling a
-- single-item function per product would leave the first items decremented when
-- the third is short, which is worse than today: the current queued-write
-- behaviour at least writes nothing when the loop throws.
--
-- So stock needs a multi-item version, and capacity needs a ceiling rather than
-- a floor. Both are here.

BEGIN;

-- ============================================================================
-- decrement_many_or_fail
--
-- Decrements several counters, or none of them.
--
-- p_items is a JSONB array of objects:
--   [{"collection": "products", "id": "abc", "field": "availableQuantity", "amount": 2}, ...]
--
-- Rows are locked in id order, which matters: two orders containing the same
-- two products in different sequences would otherwise deadlock.
--
-- All rows are locked and checked BEFORE any is written, so a shortfall on the
-- last item leaves the first untouched.
--
-- Returns:
--   ok         TRUE when every decrement was applied
--   failed_id  the item that was short, when ok is FALSE
--   reason     'insufficient' or 'not_found'
-- ============================================================================

CREATE OR REPLACE FUNCTION decrement_many_or_fail(p_items JSONB)
RETURNS TABLE (ok BOOLEAN, failed_id TEXT, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_item      JSONB;
    v_id        TEXT;
    v_coll      TEXT;
    v_field     TEXT;
    v_amount    NUMERIC;
    v_current   NUMERIC;
BEGIN
    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
        RAISE EXCEPTION 'decrement_many_or_fail: p_items must be a JSONB array';
    END IF;

    -- Pass 1 — lock every row, in id order, and check it can afford the change.
    FOR v_item IN
        SELECT value FROM jsonb_array_elements(p_items)
         ORDER BY value ->> 'id'
    LOOP
        v_id     := v_item ->> 'id';
        v_coll   := v_item ->> 'collection';
        v_field  := v_item ->> 'field';
        v_amount := (v_item ->> 'amount')::numeric;

        IF v_amount IS NULL OR v_amount <= 0 THEN
            RAISE EXCEPTION 'decrement_many_or_fail: amount must be positive for %', v_id;
        END IF;

        SELECT COALESCE((raw_data ->> v_field)::numeric, 0)
          INTO v_current
          FROM document_collections
         WHERE id = v_id AND collection_name = v_coll
           FOR UPDATE;

        IF NOT FOUND THEN
            RETURN QUERY SELECT FALSE, v_id, 'not_found'::TEXT;
            RETURN;
        END IF;

        IF v_current < v_amount THEN
            RETURN QUERY SELECT FALSE, v_id, 'insufficient'::TEXT;
            RETURN;
        END IF;
    END LOOP;

    -- Pass 2 — every row is locked and sufficient, so these cannot fail.
    FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
    LOOP
        v_id     := v_item ->> 'id';
        v_coll   := v_item ->> 'collection';
        v_field  := v_item ->> 'field';
        v_amount := (v_item ->> 'amount')::numeric;

        UPDATE document_collections
           SET raw_data = jsonb_set(
                   raw_data,
                   ARRAY[v_field],
                   to_jsonb(COALESCE((raw_data ->> v_field)::numeric, 0) - v_amount),
                   true
               ),
               updated_at = NOW()
         WHERE id = v_id AND collection_name = v_coll;
    END LOOP;

    RETURN QUERY SELECT TRUE, NULL::TEXT, NULL::TEXT;
END;
$$;

-- ============================================================================
-- increment_within_ceiling
--
-- Raises a counter only while it stays at or below a ceiling, where the ceiling
-- is held in another field on the same record.
--
-- For capacity: currentParticipants may rise only while it stays within
-- maxParticipants.
--
-- Returns:
--   ok       TRUE when the increment was applied
--   value    the counter after the call
--   reason   NULL, or 'at_capacity' / 'not_found'
-- ============================================================================

CREATE OR REPLACE FUNCTION increment_within_ceiling(
    p_collection    TEXT,
    p_id            TEXT,
    p_field         TEXT,
    p_amount        NUMERIC,
    p_ceiling_field TEXT
)
RETURNS TABLE (ok BOOLEAN, value NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_current NUMERIC;
    v_ceiling NUMERIC;
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'increment_within_ceiling: amount must be positive, got %', p_amount;
    END IF;

    SELECT COALESCE((raw_data ->> p_field)::numeric, 0),
           COALESCE((raw_data ->> p_ceiling_field)::numeric, NULL)
      INTO v_current, v_ceiling
      FROM document_collections
     WHERE id = p_id AND collection_name = p_collection
       FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, 'not_found'::TEXT;
        RETURN;
    END IF;

    -- No ceiling recorded means unbounded. Refusing here would break every
    -- event that simply has no cap set.
    IF v_ceiling IS NOT NULL AND v_current + p_amount > v_ceiling THEN
        RETURN QUERY SELECT FALSE, v_current, 'at_capacity'::TEXT;
        RETURN;
    END IF;

    UPDATE document_collections
       SET raw_data = jsonb_set(raw_data, ARRAY[p_field],
                                to_jsonb(v_current + p_amount), true),
           updated_at = NOW()
     WHERE id = p_id AND collection_name = p_collection;

    RETURN QUERY SELECT TRUE, v_current + p_amount, NULL::TEXT;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging.
-- ============================================================================
--
-- Capacity:
--
--   INSERT INTO document_collections (id, collection_name, raw_data)
--   VALUES ('t-evt-1', 'wave_training_events',
--           '{"currentParticipants": 9, "maxParticipants": 10}'::jsonb)
--   ON CONFLICT (id, collection_name) DO UPDATE SET raw_data = EXCLUDED.raw_data;
--
--   SELECT * FROM increment_within_ceiling('wave_training_events','t-evt-1',
--                                          'currentParticipants',1,'maxParticipants');
--   -- expect: t, 10, NULL
--   SELECT * FROM increment_within_ceiling('wave_training_events','t-evt-1',
--                                          'currentParticipants',1,'maxParticipants');
--   -- expect: f, 10, at_capacity   <-- the eleventh registration that used to succeed
--
-- Multi-item stock, all-or-nothing:
--
--   INSERT INTO document_collections (id, collection_name, raw_data) VALUES
--     ('t-prod-a','products','{"availableQuantity": 5}'::jsonb),
--     ('t-prod-b','products','{"availableQuantity": 1}'::jsonb)
--   ON CONFLICT (id, collection_name) DO UPDATE SET raw_data = EXCLUDED.raw_data;
--
--   SELECT * FROM decrement_many_or_fail('[
--     {"collection":"products","id":"t-prod-a","field":"availableQuantity","amount":2},
--     {"collection":"products","id":"t-prod-b","field":"availableQuantity","amount":3}
--   ]'::jsonb);
--   -- expect: f, t-prod-b, insufficient
--
--   SELECT id, raw_data ->> 'availableQuantity' FROM document_collections
--    WHERE id IN ('t-prod-a','t-prod-b');
--   -- expect 5 and 1 — t-prod-a must NOT have been decremented
--
--   DELETE FROM document_collections WHERE id LIKE 't-prod-%' OR id = 't-evt-1';

-- ============================================================================
-- ROLLBACK
-- ============================================================================
--
-- DROP FUNCTION IF EXISTS decrement_many_or_fail(JSONB);
-- DROP FUNCTION IF EXISTS increment_within_ceiling(TEXT, TEXT, TEXT, NUMERIC, TEXT);


-- ============================================================================
-- 016 — 016_atomic_array_ops.sql
-- atomic arrayUnion/arrayRemove — MUST ship with the adapter change that calls it
-- ============================================================================

-- Migration: 016_atomic_array_ops.sql
--
-- Makes FieldValue.arrayUnion and FieldValue.arrayRemove atomic.
--
-- WHY THIS EXISTS
-- ---------------
-- Migration 010 fixed FieldValue.increment by pulling it out of the JavaScript
-- write path and applying it in SQL. It fixed ONLY increment. `splitIncrements`
-- tests for exactly one sentinel type, so arrayUnion and arrayRemove still go
-- through `resolveFieldValue`, which is a read-modify-write:
--
--     case 'FieldValue.arrayUnion': {
--         const arr = Array.isArray(existing) ? [...existing] : [];
--         ...
--         return arr;                      // <-- computed from a stale read
--     }
--
-- Two concurrent writes read the same array, each appends its own element, and
-- the second write overwrites the first. One element is silently lost.
--
-- WHY IT MATTERS MORE THAN IT LOOKS
-- ---------------------------------
-- 33 of the ~38 call sites are the same line:
--
--     roles: FieldValue.arrayUnion("<some_role>")
--
-- on the users collection, and `roles` is what every module-access check reads.
-- A user who joins two modules at once — or a webhook and a server action
-- landing together, which this codebase does constantly — keeps one role and
-- loses the other. The user is a paid cooperative member with no cooperative
-- access, and nothing errored.
--
-- That is also why it presents as "a fix that keeps breaking": granting the
-- role again works, right up until the next concurrent write drops it.
--
-- THE DUAL-STORAGE TRAP
-- ---------------------
-- `roles` is BOTH a native TEXT[] column on `users` and a key inside raw_data.
-- Reads prefer raw_data; `.where()` filters use the column. Migrations 005/006
-- updated only the native column for wallet balances and the fix was invisible
-- to the application — that is what 011 had to correct.
--
-- So the native column here is derived FROM the new raw_data value rather than
-- computed separately. One expression, two destinations, no way for them to
-- disagree.

BEGIN;

-- ============================================================================
-- jsonb_array_union / jsonb_array_remove
--
-- Pure helpers, so the main function stays readable.
--
-- Element equality is JSONB equality, not string equality. This differs from
-- the JavaScript path, which compared JSON.stringify output: JSONB normalises
-- key order, so {"a":1,"b":2} and {"b":2,"a":1} are correctly treated as the
-- same element here and were treated as different before. That is a fix, not a
-- regression, but it is a behaviour change worth knowing about.
--
-- Order is preserved: existing elements keep their positions and new ones are
-- appended, matching the JavaScript behaviour callers may rely on.
-- ============================================================================

CREATE OR REPLACE FUNCTION jsonb_array_union(p_current JSONB, p_elements JSONB)
RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE
AS $$
DECLARE
    v_result JSONB;
    v_elem   JSONB;
BEGIN
    -- A field that does not exist yet, or holds a non-array, starts empty.
    -- Firestore's arrayUnion on a missing field creates one.
    v_result := CASE WHEN jsonb_typeof(p_current) = 'array' THEN p_current ELSE '[]'::jsonb END;

    IF jsonb_typeof(p_elements) <> 'array' THEN
        RETURN v_result;
    END IF;

    FOR v_elem IN SELECT value FROM jsonb_array_elements(p_elements)
    LOOP
        -- Checked against v_result, not p_current, so duplicates within the
        -- incoming batch are also collapsed.
        IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_result) x WHERE x = v_elem) THEN
            v_result := v_result || jsonb_build_array(v_elem);
        END IF;
    END LOOP;

    RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION jsonb_array_remove(p_current JSONB, p_elements JSONB)
RETURNS JSONB
LANGUAGE sql IMMUTABLE
AS $$
    SELECT CASE
        WHEN jsonb_typeof(p_current) <> 'array' THEN '[]'::jsonb
        WHEN jsonb_typeof(p_elements) <> 'array' THEN p_current
        ELSE COALESCE(
            (SELECT jsonb_agg(x ORDER BY o)
               FROM jsonb_array_elements(p_current) WITH ORDINALITY t(x, o)
              WHERE NOT EXISTS (
                  SELECT 1 FROM jsonb_array_elements(p_elements) e WHERE e = x
              )),
            '[]'::jsonb
        )
    END;
$$;

-- ============================================================================
-- apply_array_ops
--
-- Applies every array operation in one UPDATE, so concurrent writers serialise
-- on the row rather than racing on a value each read separately.
--
-- Shape deliberately mirrors apply_increments (010):
--
--   p_native  {"roles": {"union": ["seller"], "remove": []}}
--             fields that are ALSO native columns — written to both places
--   p_json    {"documents": {"union": [{...}]}, "a.b.c": {"remove": ["x"]}}
--             raw_data paths, dotted for nesting
--
-- Native array columns are TEXT[] in this schema, so their elements must be
-- JSON strings. An object element for a native field is a caller bug and is
-- rejected rather than silently stringified into the column.
-- ============================================================================

CREATE OR REPLACE FUNCTION apply_array_ops(
    p_table      TEXT,
    p_id         TEXT,
    p_collection TEXT DEFAULT NULL,        -- set for document_collections only
    p_native     JSONB DEFAULT '{}'::jsonb,
    p_json       JSONB DEFAULT '{}'::jsonb
)
RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_key      TEXT;
    v_ops      JSONB;
    v_sets     TEXT[] := ARRAY[]::TEXT[];
    v_raw      TEXT := 'raw_data';
    v_path     TEXT[];
    v_sql      TEXT;
    v_elem     JSONB;
    v_allowed  TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'apply_array_ops: table % is not allowed', p_table;
    END IF;

    IF p_id IS NULL OR TRIM(p_id) = '' THEN
        RAISE EXCEPTION 'apply_array_ops: id is required';
    END IF;

    -- raw_data paths first, so the accumulated expression already covers them
    -- if a native field is also touched below.
    FOR v_key, v_ops IN
        SELECT k, v FROM jsonb_each(COALESCE(p_json, '{}'::jsonb)) AS t(k, v)
    LOOP
        v_path := string_to_array(v_key, '.');

        IF v_ops ? 'union' THEN
            v_raw := format(
                'jsonb_set_deep(%1$s, %2$L::text[], jsonb_array_union(COALESCE(%1$s #> %2$L::text[], ''[]''::jsonb), %3$L::jsonb))',
                v_raw, v_path, v_ops -> 'union'
            );
        END IF;

        IF v_ops ? 'remove' THEN
            v_raw := format(
                'jsonb_set_deep(%1$s, %2$L::text[], jsonb_array_remove(COALESCE(%1$s #> %2$L::text[], ''[]''::jsonb), %3$L::jsonb))',
                v_raw, v_path, v_ops -> 'remove'
            );
        END IF;
    END LOOP;

    -- Native columns. The raw_data expression is extended the same way, then
    -- the column is derived from it — see the dual-storage note at the top.
    FOR v_key, v_ops IN
        SELECT k, v FROM jsonb_each(COALESCE(p_native, '{}'::jsonb)) AS t(k, v)
    LOOP
        -- A native TEXT[] column cannot hold an object.
        FOR v_elem IN
            SELECT value FROM jsonb_array_elements(COALESCE(v_ops -> 'union', '[]'::jsonb))
            UNION ALL
            SELECT value FROM jsonb_array_elements(COALESCE(v_ops -> 'remove', '[]'::jsonb))
        LOOP
            IF jsonb_typeof(v_elem) <> 'string' THEN
                RAISE EXCEPTION
                    'apply_array_ops: native column % takes text elements, got %',
                    v_key, jsonb_typeof(v_elem);
            END IF;
        END LOOP;

        IF v_ops ? 'union' THEN
            v_raw := format(
                'jsonb_set(%1$s, ARRAY[%2$L], jsonb_array_union(COALESCE(%1$s -> %2$L, to_jsonb(COALESCE(%3$I, ''{}''::text[])), ''[]''::jsonb), %4$L::jsonb), true)',
                v_raw, v_key, v_key, v_ops -> 'union'
            );
        END IF;

        IF v_ops ? 'remove' THEN
            v_raw := format(
                'jsonb_set(%1$s, ARRAY[%2$L], jsonb_array_remove(COALESCE(%1$s -> %2$L, to_jsonb(COALESCE(%3$I, ''{}''::text[])), ''[]''::jsonb), %4$L::jsonb), true)',
                v_raw, v_key, v_key, v_ops -> 'remove'
            );
        END IF;

        -- Derived from the same expression, so the two can never disagree.
        v_sets := v_sets || format(
            '%1$I = ARRAY(SELECT jsonb_array_elements_text(%2$s -> %3$L))',
            v_key, v_raw, v_key
        );
    END LOOP;

    IF v_raw <> 'raw_data' THEN
        v_sets := v_sets || format('raw_data = %s', v_raw);
    END IF;

    IF array_length(v_sets, 1) IS NULL THEN
        RETURN; -- nothing to do
    END IF;

    -- Cast required. An untyped literal makes Postgres resolve || as
    -- array-concat-array and try to parse the string as TEXT[], which fails
    -- with "malformed array literal". The format() appends above are typed
    -- TEXT and so were unaffected, which is why this went unnoticed: the
    -- function errored only once it had something to write.
    v_sets := v_sets || 'updated_at = NOW()'::TEXT;

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'UPDATE document_collections SET %s WHERE id = %L AND collection_name = %L',
            array_to_string(v_sets, ', '), p_id, p_collection
        );
    ELSE
        v_sql := format(
            'UPDATE %I SET %s WHERE id = %L',
            p_table, array_to_string(v_sets, ', '), p_id
        );
    END IF;

    EXECUTE v_sql;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging.
-- ============================================================================
--
-- 1. A role lands in BOTH raw_data and the native column.
--    Checking only one is how the wallet bug survived three separate reviews.
--
--   INSERT INTO users (id, email, roles, raw_data)
--   VALUES ('arr-check-1', 'arr-check-1@example.com', ARRAY['buyer'],
--           '{"id":"arr-check-1","roles":["buyer"]}'::jsonb)
--   ON CONFLICT (id) DO UPDATE SET roles = EXCLUDED.roles, raw_data = EXCLUDED.raw_data;
--
--   SELECT apply_array_ops('users', 'arr-check-1', NULL,
--                          '{"roles": {"union": ["seller"]}}'::jsonb);
--
--   SELECT roles, raw_data -> 'roles' FROM users WHERE id = 'arr-check-1';
--   -- expect: {buyer,seller}  and  ["buyer", "seller"]   -- BOTH, and equal
--
-- 2. No duplicate on a repeat.
--
--   SELECT apply_array_ops('users', 'arr-check-1', NULL,
--                          '{"roles": {"union": ["seller"]}}'::jsonb);
--   SELECT roles FROM users WHERE id = 'arr-check-1';
--   -- expect: {buyer,seller} — still two
--
-- 3. Removal.
--
--   SELECT apply_array_ops('users', 'arr-check-1', NULL,
--                          '{"roles": {"remove": ["buyer"]}}'::jsonb);
--   SELECT roles, raw_data -> 'roles' FROM users WHERE id = 'arr-check-1';
--   -- expect: {seller} and ["seller"]
--
-- 4. THE ONE THAT MATTERS — concurrency. Two sessions, interleaved:
--
--   -- session A                                  -- session B
--   BEGIN;                                        BEGIN;
--   SELECT apply_array_ops('users','arr-check-1',
--     NULL,'{"roles":{"union":["farmer"]}}');
--                                                 SELECT apply_array_ops('users','arr-check-1',
--                                                   NULL,'{"roles":{"union":["academy"]}}');
--                                                 -- B must BLOCK here
--   COMMIT;                                       -- B proceeds
--                                                 COMMIT;
--
--   SELECT roles FROM users WHERE id = 'arr-check-1';
--   -- expect BOTH farmer and academy. Before this migration one was lost.
--
-- 5. An object element for a native column is refused rather than mangled.
--
--   SELECT apply_array_ops('users','arr-check-1',NULL,
--                          '{"roles":{"union":[{"x":1}]}}'::jsonb);
--   -- expect: ERROR ... native column roles takes text elements, got object
--
--   DELETE FROM users WHERE id = 'arr-check-1';

-- ============================================================================
-- ROLLBACK
-- ============================================================================
--
-- The adapter falls back to the previous read-modify-write when this function
-- is absent, so dropping it degrades behaviour to what it was rather than
-- breaking writes.
--
-- DROP FUNCTION IF EXISTS apply_array_ops(TEXT, TEXT, TEXT, JSONB, JSONB);
-- DROP FUNCTION IF EXISTS jsonb_array_union(JSONB, JSONB);
-- DROP FUNCTION IF EXISTS jsonb_array_remove(JSONB, JSONB);


-- ============================================================================
-- 017 — 017_targeted_document_patch.sql
-- targeted patches — makes every write send only changed fields; also the first working FieldValue.delete
-- ============================================================================

-- Migration: 017_targeted_document_patch.sql
--
-- Lets a write send ONLY the fields it changes.
--
-- WHY THIS EXISTS
-- ---------------
-- `processWriteData(data, existing, true)` starts from `{ ...existingData }`, so
-- every update() sent the WHOLE document back — not just the changed fields:
--
--     await ref.update({ keep: 2 })
--     -- patch actually sent: {"id":"u1","keep":2,"doomed":"x", ...everything}
--
-- Two concurrent updates to completely unrelated fields therefore clobber one
-- another. Whoever writes second reverts the other's change, using a snapshot
-- taken moments earlier. Nothing errors.
--
-- This is not specific to money, arrays or counters. It applies to every field
-- in every collection, and it is the mechanism behind fixes that "keep
-- breaking": a value is corrected, and an unrelated concurrent write reverts it.
--
-- It was also silently undermining 010 and 016 until stripAtomicPaths was added,
-- because the stale copy of a counter or array rode along in that patch.
--
-- WHY THE WHOLE DOCUMENT WAS SENT
-- -------------------------------
-- merge_raw_data (002) does `raw_data || p_patch`, a SHALLOW merge. A nested
-- change like {"a.b.c": 1} therefore had to carry the whole `a` object or `a`'s
-- other keys would be dropped. Sending everything was the simplest way to be
-- correct, and it was correct — just not concurrent.
--
-- WHAT THIS DOES
-- --------------
-- Splits a write into the three shapes Firestore actually distinguishes, so the
-- patch can carry only what changed:
--
--   p_patch    top-level fields, shallow-merged.
--              update({a: {x: 1}}) REPLACES a — Firestore semantics.
--
--   p_paths    dotted paths, applied with jsonb_set.
--              update({"a.b": 1}) sets a.b and leaves a's siblings alone.
--
--   p_deletes  paths to remove, top-level or dotted.
--
-- FieldValue.delete WAS BROKEN
-- ----------------------------
-- Worth stating plainly, because it looked like it worked. Deleting a field
-- produced a patch with the key simply ABSENT, and `raw_data || patch` only
-- adds and replaces — it never removes. So FieldValue.delete() has been a no-op
-- on this path for as long as it has existed. p_deletes is what actually
-- removes the key.

BEGIN;

-- ============================================================================
-- apply_document_patch
--
-- Applies patch, then paths, then deletes, as ONE statement.
--
-- Order matters: an explicit delete must win over a value set in the same
-- write, and a dotted path must apply on top of the shallow merge rather than
-- being overwritten by it.
-- ============================================================================

CREATE OR REPLACE FUNCTION apply_document_patch(
    p_table      TEXT,
    p_id         TEXT,
    p_collection TEXT  DEFAULT NULL,        -- set for document_collections only
    p_patch      JSONB DEFAULT '{}'::jsonb, -- {"status": "paid"}
    p_paths      JSONB DEFAULT '{}'::jsonb, -- {"a.b.c": 1}
    p_deletes    JSONB DEFAULT '[]'::jsonb  -- ["tempField", "a.b"]
)
RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_key      TEXT;
    v_val      JSONB;
    v_raw      TEXT := 'raw_data';
    v_path     TEXT[];
    v_sql      TEXT;
    v_allowed  TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'apply_document_patch: table % is not allowed', p_table;
    END IF;

    IF p_id IS NULL OR TRIM(p_id) = '' THEN
        RAISE EXCEPTION 'apply_document_patch: id is required';
    END IF;

    -- 1. Shallow merge of top-level fields. Same semantics as merge_raw_data,
    --    which is what makes this a safe replacement for it.
    IF p_patch IS NOT NULL AND p_patch <> '{}'::jsonb THEN
        v_raw := format('(%s || %L::jsonb)', v_raw, p_patch);
    END IF;

    -- 2. Dotted paths. create_missing = true so a path whose parent does not
    --    exist yet is created rather than silently skipped.
    FOR v_key, v_val IN
        SELECT k, v FROM jsonb_each(COALESCE(p_paths, '{}'::jsonb)) AS t(k, v)
    LOOP
        v_path := string_to_array(v_key, '.');
        -- jsonb_set_deep, not jsonb_set: the parent may not exist yet, and
        -- jsonb_set would silently discard the write. See migration 018.
        v_raw := format('jsonb_set_deep(%s, %L::text[], %L::jsonb)', v_raw, v_path, v_val);
    END LOOP;

    -- 3. Deletes, last, so they win.
    FOR v_key IN
        SELECT value #>> '{}' FROM jsonb_array_elements(COALESCE(p_deletes, '[]'::jsonb))
    LOOP
        v_path := string_to_array(v_key, '.');
        IF array_length(v_path, 1) = 1 THEN
            v_raw := format('(%s - %L)', v_raw, v_key);
        ELSE
            v_raw := format('(%s #- %L::text[])', v_raw, v_path);
        END IF;
    END LOOP;

    IF v_raw = 'raw_data' THEN
        RETURN; -- nothing to do
    END IF;

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'UPDATE document_collections SET raw_data = %s, updated_at = NOW() '
            'WHERE id = %L AND collection_name = %L',
            v_raw, p_id, p_collection
        );
    ELSE
        v_sql := format(
            'UPDATE %I SET raw_data = %s, updated_at = NOW() WHERE id = %L',
            p_table, v_raw, p_id
        );
    END IF;

    EXECUTE v_sql;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging.
-- ============================================================================
--
--   INSERT INTO users (id, email, raw_data)
--   VALUES ('patch-check-1', 'patch-check-1@example.com',
--           '{"id":"patch-check-1","keep":1,"doomed":"x",
--             "profile":{"name":"Ada","city":"Jos"}}'::jsonb)
--   ON CONFLICT (id) DO UPDATE SET raw_data = EXCLUDED.raw_data;
--
-- 1. A top-level field changes and nothing else moves.
--
--   SELECT apply_document_patch('users','patch-check-1',NULL,'{"keep":2}'::jsonb);
--   SELECT raw_data FROM users WHERE id = 'patch-check-1';
--   -- expect keep = 2, doomed and profile untouched
--
-- 2. A dotted path keeps its siblings.
--
--   SELECT apply_document_patch('users','patch-check-1',NULL,'{}'::jsonb,
--                               '{"profile.city":"Abuja"}'::jsonb);
--   SELECT raw_data -> 'profile' FROM users WHERE id = 'patch-check-1';
--   -- expect {"name":"Ada","city":"Abuja"} — name MUST survive
--
-- 3. Delete actually deletes. This never worked before.
--
--   SELECT apply_document_patch('users','patch-check-1',NULL,'{}'::jsonb,
--                               '{}'::jsonb,'["doomed"]'::jsonb);
--   SELECT raw_data ? 'doomed' FROM users WHERE id = 'patch-check-1';
--   -- expect: f
--
-- 4. Nested delete.
--
--   SELECT apply_document_patch('users','patch-check-1',NULL,'{}'::jsonb,
--                               '{}'::jsonb,'["profile.city"]'::jsonb);
--   SELECT raw_data -> 'profile' FROM users WHERE id = 'patch-check-1';
--   -- expect {"name":"Ada"}
