-- ============================================================================
-- 019 — 019_claim_idempotency_key.sql
-- claim an idempotency key — platform.ts and export.ts throw without it
-- ============================================================================

-- Migration: 019_claim_idempotency_key.sql
--
-- An insert-if-absent claim for idempotency_keys, so a form submitted twice
-- cannot be acted on twice.
--
-- WHY THIS EXISTS
-- ---------------
-- Two actions take an idempotencyKey from the client and "check" it like this:
--
--     const doc = await idempotencyRef.get();
--     if (doc.exists) throw new Error("Duplicate transaction detected.");
--     ... do the work ...
--     idempotencyRef.set({ ... });          // the key is written LAST
--
-- That is the same check-then-write this codebase has been unpicking
-- everywhere else. The read takes no lock and the key is written after the
-- work, so two submissions carrying the SAME key both read "absent" and both
-- proceed. The key made the duplicate look impossible without preventing it.
--
-- The two callers:
--
--   platform.ts        submitWithdrawalRequest — locks a member's savings and
--                      creates a withdrawal request. A double submission
--                      locked the funds TWICE.
--   export.ts          _createExportWindowAction — creates an export window.
--                      No money, so a duplicate costs a stray record.
--
-- THE FIX
-- -------
-- INSERT ... ON CONFLICT DO NOTHING against the primary key, which is the same
-- mechanism claim_payment_once (009) uses for processed_payments. Exactly one
-- concurrent caller wins the insert, and Postgres decides it rather than the
-- application.
--
-- The claim is taken BEFORE the work, not after. A caller that claims and then
-- fails leaves the key held, so the action cannot be retried with that key —
-- deliberate, and the same trade-off claim_payment_once documents: for money, a
-- stuck request somebody investigates beats one that silently runs twice. The
-- client generates a fresh key per attempt, so a genuine retry is unaffected.
--
-- WHERE THE ROWS LIVE
--   `idempotency_keys` is not in schema.sql, so it falls through to the generic
--   `document_collections` table, keyed by (collection_name, id). The function
--   below writes there and takes the collection name as a parameter rather than
--   assuming it, so it keeps working if the collection is ever promoted to a
--   dedicated table.
--
-- SAFE TO APPLY
--   Adds one function. Creates no table, alters no column, changes no row.
--   Applying it has no effect until code calls it. Rollback is at the bottom.

BEGIN;

-- ============================================================================
-- claim_idempotency_key
--
-- Returns:
--   claimed  TRUE  when this call inserted the key and should do the work
--            FALSE when the key was already held (a duplicate submission)
--   held_at  when the winning caller claimed it, for logging a duplicate
-- ============================================================================

CREATE OR REPLACE FUNCTION claim_idempotency_key(
    p_key        TEXT,
    p_user_id    TEXT DEFAULT NULL,
    p_action     TEXT DEFAULT NULL,
    p_collection TEXT DEFAULT 'idempotency_keys'
)
RETURNS TABLE (claimed BOOLEAN, held_at TIMESTAMPTZ)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_rows    INT;
    v_held_at TIMESTAMPTZ;
BEGIN
    IF p_key IS NULL OR TRIM(p_key) = '' THEN
        RAISE EXCEPTION 'claim_idempotency_key: key is required';
    END IF;

    INSERT INTO document_collections (id, collection_name, raw_data)
    VALUES (
        p_key,
        p_collection,
        jsonb_build_object(
            'id',        p_key,
            'userId',    p_user_id,
            'action',    p_action,
            'createdAt', to_char(NOW() AT TIME ZONE 'UTC',
                                 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
        )
    )
    -- Matches the declared PRIMARY KEY (id, collection_name) in schema.sql,
    -- in that column order, so the conflict target resolves to the PK index.
    ON CONFLICT (id, collection_name) DO NOTHING;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows > 0 THEN
        RETURN QUERY SELECT TRUE, NOW();
        RETURN;
    END IF;

    SELECT d.created_at INTO v_held_at
      FROM document_collections d
     WHERE d.collection_name = p_collection
       AND d.id = p_key;

    RETURN QUERY SELECT FALSE, v_held_at;
END;
$$;

COMMIT;

-- ============================================================================
-- VERIFICATION — run on staging.
-- ============================================================================
--
-- First call claims, second does not:
--
--   SELECT * FROM claim_idempotency_key('test-key-1', 'user-1', 'unit_test');
--   -- expect claimed = true
--   SELECT * FROM claim_idempotency_key('test-key-1', 'user-1', 'unit_test');
--   -- expect claimed = false, held_at = the first call's timestamp
--
-- Clean up:
--   DELETE FROM document_collections
--    WHERE collection_name = 'idempotency_keys' AND id = 'test-key-1';
--
-- Concurrency — the property the unit tests cannot cover. In two sessions:
--   session A: BEGIN; SELECT * FROM claim_idempotency_key('race-1');
--   session B: SELECT * FROM claim_idempotency_key('race-1');   -- blocks
--   session A: COMMIT;
--   session B then returns claimed = false. Blocking is the fix working.
--
-- The ON CONFLICT target is (id, collection_name), matching the PRIMARY KEY
-- declared for document_collections in schema.sql. Confirm it is still that
-- before applying — if the key ever changes, the clause must follow it or the
-- insert will raise rather than claim:
--
--   SELECT conname, pg_get_constraintdef(oid)
--     FROM pg_constraint
--    WHERE conrelid = 'document_collections'::regclass AND contype IN ('p','u');
--   -- expect: PRIMARY KEY (id, collection_name)

-- ============================================================================
-- ROLLBACK
-- ============================================================================
--
-- DROP FUNCTION IF EXISTS claim_idempotency_key(TEXT, TEXT, TEXT, TEXT);


-- ============================================================================
-- 020 — 020_floored_debit_and_versioned_cas.sql
-- floored debit + versioned CAS — the withdrawal floor and every versionedUpdate caller
-- ============================================================================

-- Migration: 020_floored_debit_and_versioned_cas.sql
--
-- Two primitives, both recorded as open in docs/audit/atomic-money-migration.md
-- and neither expressible with the existing set.
--
-- 1. debit_jsonb_balance_with_floor
--
--    debit_jsonb_balance (013/014) checks `balance >= amount` and nothing more.
--    That is the right rule for "do not go negative", and it is what the
--    cooperative withdrawal and WAVE earnings paths needed. It is NOT enough for
--    a policy floor:
--
--        // platform.ts
--        const MIN_BALANCE = 5000;
--        if (currentBalance - amount < MIN_BALANCE) throw ...   // advisory
--        const debit = await debitJsonbBalance({ ... });         // floor-blind
--
--    The read is advisory and says so: two withdrawals that each leave 5,000
--    behind can together dip under it. The debit guarantees only that the
--    balance cannot go NEGATIVE. Closing the floor race needs the floor applied
--    under the same lock as the debit, which is this.
--
-- 2. claim_versioned_update
--
--    src/lib/optimistic-locking.ts reads _version inside runTransaction,
--    compares it, and writes:
--
--        const snap = await transaction.get(ref);
--        if (currentVersion !== expectedVersion) throw new Error("STALE_DATA...");
--        transaction.update(ref, { ...data, _version: currentVersion + 1 });
--
--    runTransaction takes no lock, so two callers read the same version, both
--    pass, and both write — the exact failure optimistic locking exists to
--    prevent. loan-actions.ts already dropped versionedUpdate from its approval
--    path for this reason; vendor-settings.ts (4 sites), admin.ts and
--    cooperative/_actions.ts `_updateMembershipAction` still use it.
--
--    This is the same compare-and-swap shape as claim_status_transition (007),
--    on a numeric version rather than a status string.
--
-- SAFETY
--   Adds two functions. No table, column or row is altered, and neither does
--   anything until code calls it. Inert on apply.

BEGIN;

-- ---------------------------------------------------------------------------
-- debit_jsonb_balance_with_floor
--
-- Deliberately a SEPARATE function rather than a floor parameter added to
-- debit_jsonb_balance. Adding a DEFAULTed parameter to an existing function
-- creates a NEW signature and leaves the old one resolvable — the precise trap
-- docs/audit/atomic-money-migration.md records under "proname alone proves
-- nothing about version". A distinct name cannot be ambiguous.
--
-- Returns
--   ok       TRUE when the debit was applied
--   balance  the balance AFTER a successful debit; the current balance on
--            refusal, so the caller can report the real number rather than a
--            stale pre-read
--   reason   'insufficient_funds' | 'below_floor' | 'not_found'
--
-- 'below_floor' is distinct from 'insufficient_funds' on purpose: the member has
-- the money, they are just not allowed to take it all. Telling them "insufficient
-- funds" would be false.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION debit_jsonb_balance_with_floor(
    p_table      TEXT,
    p_id         TEXT,
    p_field      TEXT,
    p_amount     NUMERIC,
    p_floor      NUMERIC,
    p_collection TEXT DEFAULT NULL
)
RETURNS TABLE (ok BOOLEAN, balance NUMERIC, reason TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_balance NUMERIC;
    v_path    TEXT[];
    v_sql     TEXT;
    v_allowed TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'debit_jsonb_balance_with_floor: table % is not allowed', p_table;
    END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'debit_jsonb_balance_with_floor: amount must be positive, got %', p_amount;
    END IF;
    IF p_floor IS NULL OR p_floor < 0 THEN
        RAISE EXCEPTION 'debit_jsonb_balance_with_floor: floor must be >= 0, got %', p_floor;
    END IF;

    v_path := string_to_array(p_field, '.');

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'SELECT COALESCE((raw_data #>> %L::text[])::numeric, 0) FROM document_collections '
            'WHERE id = %L AND collection_name = %L FOR UPDATE',
            v_path, p_id, p_collection
        );
    ELSE
        v_sql := format(
            'SELECT COALESCE((raw_data #>> %L::text[])::numeric, 0) FROM %I WHERE id = %L FOR UPDATE',
            v_path, p_table, p_id
        );
    END IF;

    EXECUTE v_sql INTO v_balance;

    IF v_balance IS NULL THEN
        RETURN QUERY SELECT FALSE, 0::NUMERIC, 'not_found'::TEXT;
        RETURN;
    END IF;

    -- Order matters. A member with 200 who asks for 5,000 against a floor of
    -- 5,000 has insufficient funds, not a floor problem; reporting the floor
    -- first would tell them to keep a balance they never had.
    IF v_balance < p_amount THEN
        RETURN QUERY SELECT FALSE, v_balance, 'insufficient_funds'::TEXT;
        RETURN;
    END IF;

    IF v_balance - p_amount < p_floor THEN
        RETURN QUERY SELECT FALSE, v_balance, 'below_floor'::TEXT;
        RETURN;
    END IF;

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'UPDATE document_collections SET raw_data = jsonb_set(raw_data, %L::text[], to_jsonb(%L::numeric), true), '
            'updated_at = NOW() WHERE id = %L AND collection_name = %L',
            v_path, v_balance - p_amount, p_id, p_collection
        );
    ELSE
        v_sql := format(
            'UPDATE %I SET raw_data = jsonb_set(raw_data, %L::text[], to_jsonb(%L::numeric), true), '
            'updated_at = NOW() WHERE id = %L',
            p_table, v_path, v_balance - p_amount, p_id
        );
    END IF;

    EXECUTE v_sql;

    RETURN QUERY SELECT TRUE, v_balance - p_amount, NULL::TEXT;
END;
$$;

-- ---------------------------------------------------------------------------
-- claim_versioned_update
--
-- Compare-and-swap on _version. A single conditional UPDATE locks the row and
-- re-reads it under the lock, so exactly one of two concurrent callers matches
-- the WHERE and the other is told the version moved.
--
-- Returns
--   claimed  TRUE when this caller made the change
--   version  the version now on the row: the NEW one on success, the CURRENT
--            one on a lost claim, NULL when the record does not exist
--
-- version IS NULL means "no such record", which is a different failure from a
-- lost claim — the same distinction claim_status_transition draws with
-- status IS NULL. Confusing the two turns a missing record into a spurious
-- "someone else edited this".
--
-- NOTE: the patch is applied as JSONB and FieldValue sentinels are NOT resolved,
-- exactly as in claim_status_transition (007). An increment placed in the patch
-- is stored as an object rather than applied. Issue those as a separate update
-- after a successful claim.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION claim_versioned_update(
    p_table      TEXT,
    p_id         TEXT,
    p_expected   NUMERIC,
    p_patch      JSONB DEFAULT '{}'::jsonb,
    p_collection TEXT DEFAULT NULL
)
RETURNS TABLE (claimed BOOLEAN, version NUMERIC)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_current NUMERIC;
    v_sql     TEXT;
    v_allowed TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'claim_versioned_update: table % is not allowed', p_table;
    END IF;

    -- Lock the row and read the version under that lock. A missing _version is
    -- 0, matching optimistic-locking.ts's backfill behaviour — records written
    -- before versioning existed must remain updatable.
    IF p_table = 'document_collections' THEN
        v_sql := format(
            'SELECT COALESCE((raw_data ->> ''_version'')::numeric, 0) FROM document_collections '
            'WHERE id = %L AND collection_name = %L FOR UPDATE',
            p_id, p_collection
        );
    ELSE
        v_sql := format(
            'SELECT COALESCE((raw_data ->> ''_version'')::numeric, 0) FROM %I WHERE id = %L FOR UPDATE',
            p_table, p_id
        );
    END IF;

    EXECUTE v_sql INTO v_current;

    IF v_current IS NULL THEN
        RETURN QUERY SELECT FALSE, NULL::NUMERIC;
        RETURN;
    END IF;

    -- A NULL expectation means "I am not asserting a version", which
    -- optimistic-locking.ts already permitted for initialisation. It still takes
    -- the lock, so two such callers serialise rather than racing.
    IF p_expected IS NOT NULL AND v_current <> p_expected THEN
        RETURN QUERY SELECT FALSE, v_current;
        RETURN;
    END IF;

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'UPDATE document_collections SET raw_data = raw_data || %L::jsonb || '
            'jsonb_build_object(''_version'', %L::numeric), updated_at = NOW() '
            'WHERE id = %L AND collection_name = %L',
            COALESCE(p_patch, '{}'::jsonb), v_current + 1, p_id, p_collection
        );
    ELSE
        v_sql := format(
            'UPDATE %I SET raw_data = raw_data || %L::jsonb || '
            'jsonb_build_object(''_version'', %L::numeric), updated_at = NOW() '
            'WHERE id = %L',
            p_table, COALESCE(p_patch, '{}'::jsonb), v_current + 1, p_id
        );
    END IF;

    EXECUTE v_sql;

    RETURN QUERY SELECT TRUE, v_current + 1;
END;
$$;

COMMIT;

-- ---------------------------------------------------------------------------
-- Verify after applying
--
--   SELECT proname, pg_get_function_identity_arguments(oid)
--     FROM pg_proc
--    WHERE proname IN ('debit_jsonb_balance_with_floor', 'claim_versioned_update');
--
-- Floor behaviour:
--   INSERT INTO cooperative_members (id, raw_data)
--     VALUES ('t-flr-1', '{"savingsBalance": 10000}')
--     ON CONFLICT (id) DO UPDATE SET raw_data = '{"savingsBalance": 10000}';
--
--   SELECT * FROM debit_jsonb_balance_with_floor(
--     'cooperative_members', 't-flr-1', 'savingsBalance', 6000, 5000);
--   -- expect ok = false, reason = 'below_floor', balance = 10000 (unchanged)
--
--   SELECT * FROM debit_jsonb_balance_with_floor(
--     'cooperative_members', 't-flr-1', 'savingsBalance', 5000, 5000);
--   -- expect ok = true, balance = 5000
--
--   SELECT * FROM debit_jsonb_balance_with_floor(
--     'cooperative_members', 't-flr-1', 'savingsBalance', 99999, 5000);
--   -- expect ok = false, reason = 'insufficient_funds' (NOT below_floor)
--
-- Concurrency — the property the unit tests cannot cover:
--   Tab A:  BEGIN;
--           SELECT * FROM debit_jsonb_balance_with_floor(
--             'cooperative_members', 't-flr-1', 'savingsBalance', 1000, 0);
--           -- leave open
--   Tab B:  SELECT * FROM debit_jsonb_balance_with_floor(
--             'cooperative_members', 't-flr-1', 'savingsBalance', 1000, 0);
--           -- expect B to BLOCK until A commits. Blocking is the fix working.
--   Tab A:  COMMIT;
--
-- Versioned CAS:
--   SELECT * FROM claim_versioned_update('cooperative_members', 't-flr-1', 0,
--                                        '{"note":"first"}'::jsonb);
--   -- expect claimed = true, version = 1
--   SELECT * FROM claim_versioned_update('cooperative_members', 't-flr-1', 0,
--                                        '{"note":"second"}'::jsonb);
--   -- expect claimed = false, version = 1, and note still 'first'
--   SELECT * FROM claim_versioned_update('cooperative_members', 'nope', 0);
--   -- expect claimed = false, version IS NULL
--
--   DELETE FROM cooperative_members WHERE id = 't-flr-1';
--
-- Rollback
--   DROP FUNCTION IF EXISTS debit_jsonb_balance_with_floor(TEXT,TEXT,TEXT,NUMERIC,NUMERIC,TEXT);
--   DROP FUNCTION IF EXISTS claim_versioned_update(TEXT,TEXT,NUMERIC,JSONB,TEXT);
-- ---------------------------------------------------------------------------


-- ============================================================================
-- 021 — 021_single_open_loan_application.sql
-- one open loan application per borrower (advisory lock)
-- ============================================================================

-- Migration: 021_single_open_loan_application.sql
--
-- One open loan application per borrower, enforced where it can actually hold.
--
-- THE DEFECT
--
-- Two actions refuse a borrower who already has an open application:
--
--   cooperative/_actions.ts  _applyForLoanAction   -> writes COOPERATIVE_LOANS
--   loan-actions.ts          submitLoanApplication -> writes LOAN_APPLICATIONS
--
-- Both read BOTH collections, filter to the open statuses, and refuse if either
-- is non-empty. Neither read takes a lock, so two applications submitted
-- together both see an empty result and both insert. docs/audit/
-- atomic-money-migration.md records this twice and declines to patch it, for a
-- good reason: "Closing it needs a uniqueness constraint on a borrower's open
-- applications, not a wrapper."
--
-- WHY NOT A UNIQUE INDEX
--
-- A partial unique index is the obvious answer and does not fit:
--
--   * The rule spans TWO tables — cooperative_loans (dedicated) and
--     document_collections filtered to collection_name = 'loan_applications'.
--     No single index can span both.
--   * CREATE UNIQUE INDEX fails outright if the existing data already violates
--     it, and the very defect being fixed is what would have produced the
--     duplicates. A migration that cannot be applied until production data is
--     cleaned is a migration that does not get applied.
--
-- WHY AN ADVISORY LOCK WORKS
--
-- The problem is a phantom: there is no row to lock, because the thing being
-- guarded is the ABSENCE of rows. Locking a row cannot help; the check and the
-- insert have to be inseparable.
--
-- pg_advisory_xact_lock, taken on a key derived from the borrower, serialises
-- every caller for that borrower for the rest of the transaction. Because the
-- check AND the insert both happen inside this function, and a function call is
-- its own transaction, the lock is held across both. A second caller for the
-- same borrower blocks until the first commits, then sees the row it wrote.
--
-- The lock is per-borrower, so applications from different borrowers do not
-- contend at all. It is released automatically at transaction end, including on
-- error — there is no leak path, which is why xact and not session.
--
-- SAFETY
--   Adds one function. No table, column, row or index is altered, and it does
--   nothing until code calls it. Inert on apply, and it imposes no precondition
--   on existing data: a borrower who already has duplicates simply cannot add
--   a third.

BEGIN;

-- ---------------------------------------------------------------------------
-- claim_single_open_loan_application
--
-- Inserts p_row as a new loan application, but only if the borrower has no open
-- application in EITHER collection.
--
-- p_target_table       'cooperative_loans' or 'document_collections'
-- p_target_collection  NULL for a dedicated table; 'loan_applications' for the
--                      generic one
--
-- Returns
--   claimed      TRUE when the row was inserted
--   existing_id  the id of the open application that blocked it, when not
--
-- Note the two different user fields. COOPERATIVE_LOANS keys the borrower as
-- `memberId` and LOAN_APPLICATIONS as `userId`; the actions already query them
-- that way. Getting this wrong would make the guard silently match nothing,
-- which is indistinguishable from working.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION claim_single_open_loan_application(
    p_user_id           TEXT,
    p_id                TEXT,
    p_target_table      TEXT,
    p_row               JSONB,
    p_target_collection TEXT DEFAULT NULL
)
RETURNS TABLE (claimed BOOLEAN, existing_id TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_open    TEXT[] := ARRAY['pending', 'reviewing', 'approved', 'partially_approved', 'disbursed'];
    v_found   TEXT;
BEGIN
    IF p_user_id IS NULL OR p_user_id = '' THEN
        RAISE EXCEPTION 'claim_single_open_loan_application: user id is required';
    END IF;
    IF p_target_table NOT IN ('cooperative_loans', 'document_collections') THEN
        RAISE EXCEPTION 'claim_single_open_loan_application: table % is not allowed', p_target_table;
    END IF;
    IF p_target_table = 'document_collections' AND COALESCE(p_target_collection, '') = '' THEN
        RAISE EXCEPTION 'claim_single_open_loan_application: collection is required for document_collections';
    END IF;

    -- Serialise every application for THIS borrower. Held to the end of the
    -- implicit transaction around this function, so it covers the checks below
    -- and the insert together — which is the whole point, since the thing being
    -- guarded is the absence of a row and there is nothing to lock with
    -- FOR UPDATE.
    PERFORM pg_advisory_xact_lock(hashtext('loan_application:' || p_user_id));

    -- Open cooperative loan? Borrower is `memberId` here.
    SELECT id INTO v_found
      FROM cooperative_loans
     WHERE raw_data ->> 'memberId' = p_user_id
       AND raw_data ->> 'status' = ANY(v_open)
     LIMIT 1;

    IF v_found IS NOT NULL THEN
        RETURN QUERY SELECT FALSE, v_found;
        RETURN;
    END IF;

    -- Open general loan application? Borrower is `userId` here.
    SELECT id INTO v_found
      FROM document_collections
     WHERE collection_name = 'loan_applications'
       AND raw_data ->> 'userId' = p_user_id
       AND raw_data ->> 'status' = ANY(v_open)
     LIMIT 1;

    IF v_found IS NOT NULL THEN
        RETURN QUERY SELECT FALSE, v_found;
        RETURN;
    END IF;

    IF p_target_table = 'cooperative_loans' THEN
        -- Native columns are DERIVED from p_row, not passed separately.
        --
        -- cooperative_loans carries native `status` and `amount` columns, and
        -- the adapter routes .where('status', ...) to the COLUMN rather than to
        -- raw_data (NATIVE_COLUMNS in supabase-db.ts). An insert that filled
        -- only raw_data would leave both NULL, so a loan created here would be
        -- invisible to the admin approval queue: the row exists, the member is
        -- told they applied, and nobody ever sees it. That is the dual-storage
        -- trap docs/audit/atomic-money-migration.md records for `roles`.
        --
        -- Deriving them from the same JSONB the row is built from means there is
        -- one expression and two destinations, with no way for them to disagree
        -- — the approach apply_array_ops uses for exactly this reason.
        --
        -- user_id is deliberately NOT set: these rows key the borrower as
        -- `memberId`, and FIELD_TO_COLUMN maps only `userId` to user_id. It was
        -- NULL on this path before this migration existed, and making it
        -- non-NULL here would be a behaviour change smuggled into a lock fix.
        INSERT INTO cooperative_loans (id, raw_data, status, amount, created_at, updated_at)
        VALUES (
            p_id,
            p_row,
            p_row ->> 'status',
            (p_row ->> 'amount')::numeric,
            NOW(),
            NOW()
        );
    ELSE
        INSERT INTO document_collections (id, collection_name, raw_data, created_at, updated_at)
        VALUES (p_id, p_target_collection, p_row, NOW(), NOW());
    END IF;

    RETURN QUERY SELECT TRUE, NULL::TEXT;
END;
$$;

COMMIT;

-- ---------------------------------------------------------------------------
-- Verify after applying
--
--   SELECT proname, pg_get_function_identity_arguments(oid)
--     FROM pg_proc WHERE proname = 'claim_single_open_loan_application';
--
-- Basic behaviour:
--   SELECT * FROM claim_single_open_loan_application(
--     't-usr-1', 't-loan-1', 'cooperative_loans',
--     '{"memberId":"t-usr-1","status":"pending","amount":1000}'::jsonb);
--   -- expect claimed = true
--
--   SELECT * FROM claim_single_open_loan_application(
--     't-usr-1', 't-loan-2', 'document_collections',
--     '{"userId":"t-usr-1","status":"pending","amount":1000}'::jsonb,
--     'loan_applications');
--   -- expect claimed = false, existing_id = 't-loan-1'
--   -- CROSS-COLLECTION: the cooperative loan blocks the general application.
--
-- Concurrency — the property the unit tests cannot cover:
--   Tab A:  BEGIN;
--           SELECT * FROM claim_single_open_loan_application(
--             't-usr-2', 't-loan-3', 'cooperative_loans',
--             '{"memberId":"t-usr-2","status":"pending"}'::jsonb);
--           -- leave open
--   Tab B:  SELECT * FROM claim_single_open_loan_application(
--             't-usr-2', 't-loan-4', 'cooperative_loans',
--             '{"memberId":"t-usr-2","status":"pending"}'::jsonb);
--           -- expect B to BLOCK. Blocking is the fix working: under the old
--           -- code both read an empty result and both inserted.
--   Tab A:  COMMIT;
--           -- B then returns claimed = false, existing_id = 't-loan-3'
--
-- Native columns must be populated, not just raw_data:
--   SELECT id, status, amount, raw_data->>'status' AS raw_status
--     FROM cooperative_loans WHERE id = 't-loan-1';
--   -- expect status = 'pending' and amount = 1000 in the COLUMNS, matching
--   -- raw_data. If the columns are NULL the loan is invisible to
--   -- .where('status', ...), which routes to the column.
--
--   DELETE FROM cooperative_loans WHERE id IN ('t-loan-1','t-loan-3','t-loan-4');
--   DELETE FROM document_collections WHERE id = 't-loan-2';
--
-- Rollback
--   DROP FUNCTION IF EXISTS claim_single_open_loan_application(TEXT,TEXT,TEXT,JSONB,TEXT);
-- ---------------------------------------------------------------------------


-- ============================================================================
-- 023 — 023_academy_resolved_user_id_backfill.sql
-- repairs the academy rows autoEnrollPaidUser wrote as `resolvedUserId` — a DATA migration, not a function. Order does not matter against the others; it is here rather than excluded because the rows it fixes are invisible to every reader until it runs, and the code fix in #148 stops the damage without repairing what is already stored.
-- ============================================================================

-- ============================================================================
-- 023 — Repair the rows autoEnrollPaidUser wrote under the wrong field name
-- ============================================================================
--
-- WHAT HAPPENED
-- -------------
-- autoEnrollPaidUser was changed to take the caller from the session, and its
-- local was renamed userId -> resolvedUserId. The rename was applied inside the
-- query string literals and the written field names as well:
--
--     .where("resolvedUserId", "==", resolvedUserId)
--     await progressRef.set({ resolvedUserId, courseId, ... })
--
-- Nothing else in the codebase writes a field called `resolvedUserId`;
-- course-actions.ts, the real enrolment path, writes `userId`. So the rows this
-- function created carry a key no reader looks at, and its own dedup queries
-- matched nothing, every time.
--
-- The code fix (#148) stops the damage and makes that one function read both
-- names. It does NOT make the existing rows visible to everything else — the
-- learner's course list, the dashboard and the certificate check all query
-- `userId` alone. That is what this migration is for.
--
-- WHAT THIS DOES, AND DELIBERATELY DOES NOT
-- -----------------------------------------
--   Part 1  renames the key on affected rows. Safe and idempotent.
--
--   Part 2  restores the course progress the bug zeroed, recomputed from the
--           per-lesson records it never touched.
--
--           It restores the PERCENTAGE ONLY. It does not restore `completed` or
--           `completedAt`, because generateCourseCertificate reads exactly
--           those, and a migration that guesses a learner finished a course
--           mints a credential the platform then vouches for publicly. Getting
--           that wrong is worse than a learner re-completing a course, so
--           completion is left to completeCourse, which verifies every lesson.
--
--   Part 3  reports duplicate enrolments. It deletes NOTHING. The bug added a
--           second enrolment row for learners who had already enrolled
--           properly; which of a pair to keep is a judgement about live data,
--           not something a migration should decide silently.
--
-- WHY A GLOBAL WHERE IS SAFE HERE
-- ------------------------------
-- Part 1 does not name the affected collections. `resolvedUserId` is written by
-- nothing in this codebase except the defect — verified by grep across src —
-- so any row carrying it came from this bug, whichever collection it landed in.
-- That matters because the function wrote to three places: course_progress,
-- course_enrollments, and the user_progress/<uid>/courses subcollection.
-- Enumerating them risks missing one; the key itself is the reliable marker.
--
-- RUN THE PREFLIGHT FIRST
-- -----------------------
-- Every statement below is idempotent and safe to re-run, but run the SELECTs
-- in Part 0 before the UPDATEs and keep the numbers. Part 2 cannot be undone by
-- re-running it, and the counts are the only record of what it touched.
-- ============================================================================


-- ─── PART 0 — PREFLIGHT. Read-only. Run this first and keep the output. ─────

-- How many rows carry the wrong key, and where?
--
--   SELECT collection_name, COUNT(*) AS rows_to_rename
--   FROM document_collections
--   WHERE raw_data ? 'resolvedUserId'
--   GROUP BY collection_name
--   ORDER BY 2 DESC;

-- How many course_progress rows look zeroed while the learner has real lesson
-- progress? This is the population Part 2 restores.
--
--   WITH lesson_rollup AS (
--       SELECT raw_data->>'userId' AS user_id,
--              raw_data->>'courseId' AS course_id,
--              AVG((raw_data->>'progressPercent')::numeric) AS avg_pct
--       FROM document_collections
--       WHERE collection_name = 'lesson_video_progress'
--         AND raw_data ? 'userId' AND raw_data ? 'courseId'
--         AND (raw_data->>'progressPercent') ~ '^[0-9]+(\.[0-9]+)?$'
--       GROUP BY 1, 2
--   )
--   SELECT COUNT(*) AS rows_to_restore
--   FROM document_collections cp
--   JOIN lesson_rollup lr
--     ON cp.raw_data->>'userId' = lr.user_id
--    AND cp.raw_data->>'courseId' = lr.course_id
--   WHERE cp.collection_name = 'course_progress'
--     AND COALESCE(NULLIF(cp.raw_data->>'progressPercent', '')::numeric, 0) = 0
--     AND lr.avg_pct > 0;


-- ─── PART 1 — Rename the key ────────────────────────────────────────────────

-- 1a. Rows carrying only the wrong key: move the value across.
UPDATE document_collections
SET raw_data = (raw_data - 'resolvedUserId')
               || jsonb_build_object('userId', raw_data->'resolvedUserId')
WHERE raw_data ? 'resolvedUserId'
  AND NOT (raw_data ? 'userId');

-- 1b. Rows carrying both: keep `userId`, drop the stray.
--
-- These should not exist — the defect wrote one or the other — but a row that
-- was later patched by a correct writer would have both, and leaving the stray
-- key in place would keep this migration reporting work forever.
UPDATE document_collections
SET raw_data = raw_data - 'resolvedUserId'
WHERE raw_data ? 'resolvedUserId'
  AND raw_data ? 'userId';


-- ─── PART 2 — Restore the progress the bug zeroed ───────────────────────────
--
-- The bug merged progressPercent: 0 over course_progress at
-- `<userId>_<courseId>`. It never touched lesson_video_progress, which holds one
-- row per lesson with its own progressPercent — written by updateLessonProgress,
-- the path with the watch-rate guard. So the course figure is recomputable from
-- records the defect could not reach.
--
-- The reconstruction is the mean of the learner's lesson percentages for that
-- course. That is an approximation: it averages only the lessons they have
-- actually started, so a learner who finished 2 of 10 lessons is restored to
-- 100% rather than 20%. It is deliberately generous in the direction that costs
-- nothing — the figure drives a progress bar, and completion is decided
-- elsewhere by counting every lesson of the course.
--
-- Only rows sitting at zero are touched, so a learner who has made progress
-- since is left alone.
WITH lesson_rollup AS (
    SELECT
        raw_data->>'userId'   AS user_id,
        raw_data->>'courseId' AS course_id,
        AVG((raw_data->>'progressPercent')::numeric) AS avg_pct
    FROM document_collections
    WHERE collection_name = 'lesson_video_progress'
      AND raw_data ? 'userId'
      AND raw_data ? 'courseId'
      -- Guard the cast: a non-numeric value would abort the whole migration.
      AND (raw_data->>'progressPercent') ~ '^[0-9]+(\.[0-9]+)?$'
    GROUP BY 1, 2
)
UPDATE document_collections cp
SET raw_data = cp.raw_data || jsonb_build_object(
        'progressPercent',      LEAST(100, ROUND(lr.avg_pct))::int,
        'completionPercentage', LEAST(100, ROUND(lr.avg_pct))::int,
        -- An audit trail on the row itself. Nothing reads this; it exists so
        -- that "why is this 47?" has an answer in six months.
        'restoredFromLessonsAt', to_char(NOW() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    )
FROM lesson_rollup lr
WHERE cp.collection_name = 'course_progress'
  AND cp.raw_data->>'userId'   = lr.user_id
  AND cp.raw_data->>'courseId' = lr.course_id
  AND COALESCE(NULLIF(cp.raw_data->>'progressPercent', '')::numeric, 0) = 0
  AND lr.avg_pct > 0;


-- ─── PART 3 — Duplicate enrolments: REPORT ONLY ─────────────────────────────
--
-- The bug added a second course_enrollments row for learners who had already
-- enrolled through enrollInCourse. After Part 1 both rows carry `userId`, so
-- they are now findable.
--
-- Nothing is deleted here on purpose. Both rows are real records with real
-- timestamps, readers use `.docs[0]`, and choosing which to keep is a judgement
-- about live data. Run this, look at the result, and decide:
--
--   SELECT raw_data->>'userId'   AS user_id,
--          raw_data->>'courseId' AS course_id,
--          COUNT(*)              AS enrolment_rows,
--          MIN(created_at)       AS first_seen,
--          MAX(created_at)       AS last_seen
--   FROM document_collections
--   WHERE collection_name = 'course_enrollments'
--     AND raw_data ? 'userId' AND raw_data ? 'courseId'
--   GROUP BY 1, 2
--   HAVING COUNT(*) > 1
--   ORDER BY 3 DESC;
--
-- If you decide to collapse them, the oldest row is the genuine enrolment —
-- the duplicate was written later, by a dashboard load. Keeping MIN(created_at)
-- per (userId, courseId) is the conservative choice, and it should be a
-- separate migration that says so in its own header.


-- ============================================================================
-- 024 — 024_wave_date_of_birth_backfill.sql
-- backfills the date of birth WAVE validated onto the user record — a DATA migration, like 023. Independent of the others; it is here rather than excluded because until it runs, forensics.ts cannot age-check any participant who enrolled before #157.
-- ============================================================================

-- ============================================================================
-- 024 — Put the date of birth WAVE validated onto the user record
-- ============================================================================
--
-- WHY
-- ---
-- The WAVE application computes an age from a declared date of birth, refuses
-- anyone under 18, and cross-checks that date against a separately declared
-- age. Until #157 the date went onto the wave_applications row and nowhere
-- else, so the user document had none — and forensics.ts, which sweeps WAVE
-- participants for under-age enrolment, had nothing to read. #156 made that
-- sweep say "could not age-check" instead of passing them silently.
--
-- #157 fixed it going forward. This is the population that enrolled before it.
--
-- WHAT THIS DOES, AND DELIBERATELY DOES NOT
-- -----------------------------------------
--   Part 1  copies the date from the application onto the user, ONLY where the
--           user has none and ONLY where every application for that user
--           declares the same date.
--
--   Part 2  reports the users whose applications disagree. It changes nothing
--           for them. Two records declaring different dates of birth for one
--           person is a finding, not a merge conflict to resolve by picking the
--           newest — and picking one would erase exactly the signal the
--           forensic sweep exists to surface. It is the same choice #157 makes
--           at write time and #149 Part 3 makes for duplicate enrolments.
--
--   It does NOT touch anyone who already has a date on record. Set-once is the
--   rule in the application code (#155, #157) and a migration is not the place
--   to make an exception to it.
--
--   It does NOT backfill from kyc.dateOfBirth. The forensic already falls back
--   to that field, so those users are checkable; copying it up would duplicate
--   a value with no reader asking for it.
--
-- SHAPE OF THE DATA
-- -----------------
-- `users` is a dedicated table and dateOfBirth is not one of its columns, so it
-- lives in raw_data. wave_applications is not a dedicated table, so its rows are
-- in document_collections under that collection_name, fields in raw_data.
--
-- RUN THE PREFLIGHT FIRST
-- -----------------------
-- Every statement is idempotent and safe to re-run, but Part 1 cannot be undone
-- by re-running it. Run the Part 0 SELECTs, keep the numbers, and read Part 2's
-- output before deciding whether the conflicts need attention.
-- ============================================================================


-- ─── PART 0 — PREFLIGHT. Read-only. Run first and keep the output. ──────────

-- How many users have a WAVE application carrying a usable date, and how does
-- that split between "will be backfilled", "already has one", and "conflicting"?
--
--   WITH app_dob AS (
--       SELECT raw_data->>'userId'                        AS user_id,
--              COUNT(DISTINCT raw_data->>'dateOfBirth')   AS distinct_dobs,
--              MIN(raw_data->>'dateOfBirth')              AS dob
--       FROM document_collections
--       WHERE collection_name = 'wave_applications'
--         AND COALESCE(raw_data->>'userId', '') <> ''
--         AND raw_data->>'dateOfBirth' ~ '^\d{4}-\d{2}-\d{2}$'
--       GROUP BY 1
--   )
--   SELECT
--       COUNT(*) FILTER (WHERE a.distinct_dobs > 1)                        AS conflicting,
--       COUNT(*) FILTER (WHERE a.distinct_dobs = 1
--                          AND COALESCE(u.raw_data->>'dateOfBirth','') <> '') AS already_set,
--       COUNT(*) FILTER (WHERE a.distinct_dobs = 1
--                          AND COALESCE(u.raw_data->>'dateOfBirth','') = '')  AS will_backfill
--   FROM app_dob a
--   JOIN users u ON u.id = a.user_id;

-- And how many WAVE participants will STILL have no date afterwards — no
-- application row, or one with no usable date on it? Those stay unchecked, and
-- the sweep will keep saying so, which is correct.
--
--   SELECT COUNT(*)
--   FROM users u
--   WHERE 'wave_participant' = ANY(u.roles)
--     AND COALESCE(u.raw_data->>'dateOfBirth', '') = ''
--     AND COALESCE(u.raw_data#>>'{kyc,dateOfBirth}', '') = ''
--     AND NOT EXISTS (
--         SELECT 1 FROM document_collections d
--         WHERE d.collection_name = 'wave_applications'
--           AND d.raw_data->>'userId' = u.id
--           AND d.raw_data->>'dateOfBirth' ~ '^\d{4}-\d{2}-\d{2}$'
--     );


-- ─── PART 1 — Backfill, where unambiguous and absent ────────────────────────
--
-- The date is required to look like YYYY-MM-DD and to fall in a sane range.
-- forensics.ts does `new Date(dob)` and an unparseable value yields NaN, whose
-- comparisons are all false — so a malformed date would pass the under-18 test
-- exactly the way a missing one used to. Copying rubbish across would recreate
-- the defect this migration exists to close, while making it look fixed.
--
-- The year bound is deliberately wide. It is here to catch a typo or a
-- placeholder, not to judge how old a participant may be.
WITH app_dob AS (
    SELECT
        raw_data->>'userId'                      AS user_id,
        COUNT(DISTINCT raw_data->>'dateOfBirth') AS distinct_dobs,
        MIN(raw_data->>'dateOfBirth')            AS dob
    FROM document_collections
    WHERE collection_name = 'wave_applications'
      AND COALESCE(raw_data->>'userId', '') <> ''
      AND raw_data->>'dateOfBirth' ~ '^\d{4}-\d{2}-\d{2}$'
      AND (raw_data->>'dateOfBirth')::date BETWEEN DATE '1900-01-01' AND CURRENT_DATE
    GROUP BY 1
)
UPDATE users u
SET raw_data = u.raw_data || jsonb_build_object(
        'dateOfBirth', a.dob,
        -- Provenance on the row itself. Nothing reads this; it exists so that
        -- "where did this date come from?" has an answer in six months, and so
        -- a later reconciliation can tell a backfilled value from a declared
        -- one. Same reasoning as restoredFromLessonsAt in 023.
        'dateOfBirthSource', 'wave_application_backfill_024'
    )
FROM app_dob a
WHERE u.id = a.user_id
  AND a.distinct_dobs = 1
  AND COALESCE(NULLIF(u.raw_data->>'dateOfBirth', ''), '') = '';


-- ─── PART 2 — Conflicting declarations: REPORT ONLY ─────────────────────────
--
-- A user whose applications declare more than one date of birth is left
-- untouched. Picking the newest, or the one on the approved application, would
-- resolve a discrepancy that somebody should look at — and the whole reason
-- #156 and #157 exist is that these records were never being looked at.
--
-- Run this and read it:
--
--   SELECT raw_data->>'userId' AS user_id,
--          ARRAY_AGG(DISTINCT raw_data->>'dateOfBirth' ORDER BY raw_data->>'dateOfBirth') AS declared_dates,
--          COUNT(*) AS applications
--   FROM document_collections
--   WHERE collection_name = 'wave_applications'
--     AND COALESCE(raw_data->>'userId', '') <> ''
--     AND raw_data->>'dateOfBirth' ~ '^\d{4}-\d{2}-\d{2}$'
--   GROUP BY 1
--   HAVING COUNT(DISTINCT raw_data->>'dateOfBirth') > 1
--   ORDER BY 3 DESC;
--
-- If one of the dates would put the applicant under 18 at the time they
-- applied, that is the case worth reading first.


-- ============================================================================
-- 025 — 025_status_transition_dedicated_tables.sql
-- claim_status_transition_in — the CAS that can reach the eight DEDICATED tables. MUST ship with the code that calls it: status-transition.ts routes marketplaceOrders and cooperative_loans through it, and without this function every order transition returns claimed=false, which the callers report as a conflict rather than as a missing function.
-- ============================================================================

-- Migration: 025_status_transition_dedicated_tables.sql
--
-- Lets claim_status_transition reach the eight DEDICATED TABLES.
--
-- WHAT WAS WRONG
-- --------------
-- 007 wrote the compare-and-swap against document_collections and nothing else:
--
--     UPDATE document_collections
--      WHERE id = p_id AND collection_name = p_collection
--        AND raw_data->>'status' = p_from;
--
-- Eight collections do not live there. DEDICATED_TABLE_MAP in supabase-db.ts
-- routes users, cooperative_members, cooperative_loans, transactions,
-- processed_payments, marketplace_orders, wallets and academy_applications to
-- their own tables. For any of those the UPDATE matched zero rows, the
-- follow-up SELECT found nothing, and the function returned
-- (claimed=false, status=NULL) — indistinguishable from losing a race.
--
-- Two such collections are passed to it today:
--
--   COLLECTIONS.COOPERATIVE_LOANS  = "cooperative_loans"  → dedicated
--   COLLECTIONS.MARKETPLACE_ORDERS = "marketplaceOrders"  → dedicated
--
-- MARKETPLACE_ORDERS is the serious one: four call sites drive the order state
-- machine through this function, so no order transition taken through the
-- claimed path has ever succeeded. Callers read claimed=false as "someone else
-- already did it" and returned a conflict, which is why this looked like
-- ordinary contention rather than a function that could not see the row.
--
-- Confirmed by measurement, not inference:
-- __tests__/db-integration/status-transition-dedicated-tables.test.ts writes a
-- row to marketplace_orders and to cooperative_loans and asks the real RPC to
-- advance it. Against 007 the document_collections control passes and both
-- dedicated cases return claimed=false.
--
-- WHY A NEW FUNCTION RATHER THAN AN EDIT
-- --------------------------------------
-- claim_status_transition keeps its exact signature and behaviour. Callers that
-- pass a generic collection are unaffected, and the rollout cannot change what
-- an existing call does. The new function takes the table explicitly, and
-- status-transition.ts resolves it the same way the adapter does, so there is
-- one mapping rather than two.
--
-- THE STATUS LIVES IN TWO PLACES ON A DEDICATED TABLE
-- --------------------------------------------------
-- These tables carry a native `status` column AND raw_data->>'status'. Reads
-- prefer raw_data, so the JSONB copy is authoritative and is what the CAS
-- predicate tests — matching apply_increments (010), which sets both for the
-- same reason. Both are written, so a native-column reader does not see a
-- stale value. Tables without a status column (wallets) are handled: the
-- column write is conditional on the column existing.
--
-- SAFE TO APPLY
--   Adds one function. No table, column or row is touched. Inert until called.

BEGIN;

-- ============================================================================
-- claim_status_transition_in
--
-- Same contract as claim_status_transition, but names the table.
--
--   p_table       one of the allow-listed tables, or 'document_collections'
--   p_collection  required ONLY for document_collections; ignored otherwise
--
-- Returns:
--   claimed  TRUE  when this call made the transition
--            FALSE when the row was not in p_from — or does not exist
--   status   the row's status after the call, or NULL when the row is missing.
--            The caller distinguishes "lost the race" from "no such row" by
--            testing status IS NULL, exactly as with the original.
-- ============================================================================
CREATE OR REPLACE FUNCTION claim_status_transition_in(
    p_table      TEXT,
    p_id         TEXT,
    p_from       TEXT,
    p_to         TEXT,
    p_collection TEXT  DEFAULT NULL,
    p_patch      JSONB DEFAULT '{}'::jsonb
)
RETURNS TABLE (claimed BOOLEAN, status TEXT)
LANGUAGE plpgsql SECURITY DEFINER
AS $$
DECLARE
    v_rows      INT;
    v_current   TEXT;
    v_sql       TEXT;
    v_has_status BOOLEAN;
    v_allowed   TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'claim_status_transition_in: table % is not allowed', p_table;
    END IF;

    IF p_from IS NULL OR p_to IS NULL THEN
        RAISE EXCEPTION 'claim_status_transition_in: from and to are required';
    END IF;

    IF p_id IS NULL OR TRIM(p_id) = '' THEN
        RAISE EXCEPTION 'claim_status_transition_in: id is required';
    END IF;

    -- document_collections is keyed by (id, collection_name); a claim without
    -- the collection could match a same-id row in a different collection.
    IF p_table = 'document_collections' AND (p_collection IS NULL OR TRIM(p_collection) = '') THEN
        RAISE EXCEPTION 'claim_status_transition_in: collection is required for document_collections';
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = p_table AND column_name = 'status'
    ) INTO v_has_status;

    -- The whole mechanism, unchanged from 007: two concurrent callers cannot
    -- both match this WHERE clause, because the UPDATE locks the row and
    -- re-evaluates the predicate under the lock.
    v_sql := format(
        'UPDATE %1$I
            SET raw_data = raw_data
                           || COALESCE($1, ''{}''::jsonb)
                           || jsonb_build_object(
                                ''status'', $2,
                                ''updatedAt'', to_char(NOW() AT TIME ZONE ''UTC'',
                                                       ''YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'')
                              )%2$s,
                updated_at = NOW()
          WHERE id = $3
            AND raw_data->>''status'' = $4%3$s',
        p_table,
        CASE WHEN v_has_status THEN ', status = $2' ELSE '' END,
        CASE WHEN p_table = 'document_collections' THEN ' AND collection_name = $5' ELSE '' END
    );

    IF p_table = 'document_collections' THEN
        EXECUTE v_sql USING COALESCE(p_patch, '{}'::jsonb), p_to, p_id, p_from, p_collection;
    ELSE
        EXECUTE v_sql USING COALESCE(p_patch, '{}'::jsonb), p_to, p_id, p_from;
    END IF;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows > 0 THEN
        RETURN QUERY SELECT TRUE, p_to;
        RETURN;
    END IF;

    -- Lost the race, or the row is not there. Report which.
    IF p_table = 'document_collections' THEN
        EXECUTE format('SELECT raw_data->>''status'' FROM %I WHERE id = $1 AND collection_name = $2', p_table)
            INTO v_current USING p_id, p_collection;
    ELSE
        EXECUTE format('SELECT raw_data->>''status'' FROM %I WHERE id = $1', p_table)
            INTO v_current USING p_id;
    END IF;

    RETURN QUERY SELECT FALSE, v_current;
END;
$$;

COMMIT;

