-- VERIFICATION — run on staging, or let the db-integration suite do it.
-- ============================================================================
--
--   INSERT INTO marketplace_orders (id, user_id, status, raw_data)
--   VALUES ('t-cas-1', 't-user', 'pending', '{"status":"pending"}'::jsonb);
--
--   SELECT * FROM claim_status_transition_in('marketplace_orders', 't-cas-1', 'pending', 'paid');
--   -- expect: t, paid
--   SELECT * FROM claim_status_transition_in('marketplace_orders', 't-cas-1', 'pending', 'paid');
--   -- expect: f, paid   (the second caller must lose)
--
--   SELECT status, raw_data->>'status' FROM marketplace_orders WHERE id = 't-cas-1';
--   -- expect: paid, paid   (both copies moved)
--
--   DELETE FROM marketplace_orders WHERE id = 't-cas-1';


-- ============================================================================
-- 026 — 026_document_patch_mirrors_native_columns.sql
-- apply_document_patch mirroring the native typed columns — MUST come after 017, which it REPLACES. Applied in the other order, the mirroring disappears and a .where() list disagrees with the document it links to.
-- ============================================================================

-- Migration: 026_document_patch_mirrors_native_columns.sql
--
-- apply_document_patch was the one patch RPC that did not keep the native
-- typed columns in step with raw_data, so a list query and the document it
-- links to could disagree.
--
-- THE DUAL STORAGE THIS IS ABOUT
-- ------------------------------
-- Eight collections live in their own tables rather than in
-- document_collections, and those tables store the same value TWICE: once in
-- `raw_data` and once in a typed column. lib/supabase-db.ts sends reads down
-- whichever of the two suits the query —
--
--     doc.data()                      →  raw_data, always
--     .where("status", "==", "paid")   →  the `status` COLUMN
--                                        (applyFilter: FIELD_TO_COLUMN, then
--                                         NATIVE_COLUMNS, then raw_data)
--
-- so the two copies disagreeing is not a tidiness problem. It means an admin
-- queue built from `.where("status", ...)` lists an order whose own page shows a
-- different status, or omits one that has moved on. That is the exact shape of
-- "we fix it and it breaks again": the fix lands in raw_data, the list keeps
-- reading the column.
--
-- Three of the four write RPCs already knew this. apply_increments (010) and
-- apply_array_ops (016) both write the column AND raw_data in a single UPDATE,
-- and both derive the column from raw_data — their comments say so in as many
-- words:
--
--     -- Written in BOTH places, and both derived from the raw_data value,
--     -- because reads prefer raw_data and the native column is only a
--     -- fallback. Updating the column alone would be invisible to the
--     -- application.
--
-- claim_status_transition_in (007/025) does the same: `SET raw_data = …,
-- status = $2` in one statement.
--
-- WHAT apply_document_patch DID INSTEAD
-- -------------------------------------
-- It updated raw_data only, and the mirroring was left to a SECOND statement
-- issued from JavaScript afterwards (supabasePartialUpdate's nativeOverrides).
-- Three consequences, in increasing order of how much they matter:
--
-- 1. NOT ATOMIC. Two statements, no transaction around them. If the second
--    fails — a dropped connection, a PostgREST timeout, a statement timeout —
--    raw_data has moved and the column has not. The caller sees an error and
--    reasonably assumes nothing was written. The row stays divergent for good;
--    nothing ever re-derives it.
--
-- 2. TWO CONCURRENT PATCHES INTERLEAVE. A writes raw_data, B writes raw_data,
--    B writes the column, A writes the column. raw_data now says B and the
--    column says A, and every list query reads A. Each statement individually
--    succeeded, so nothing is logged and nothing errors.
--
-- 3. A DELETION NEVER REACHED THE COLUMN. nativeOverrides is derived from the
--    patch's keys, and a FieldValue.delete() is not a patch key — it travels in
--    p_deletes. So deleting a mapped field removed it from raw_data and left the
--    column holding the old value, permanently. (No call site deletes a mapped
--    field today — checked, all fourteen FieldValue.delete() sites target
--    unmapped fields — so this one is latent rather than live. It is closed here
--    because the next one will not be.)
--
-- THE FIX
-- -------
-- Mirror inside the same UPDATE, exactly as the three sibling functions do, and
-- derive each column from the FINAL raw_data expression so the two cannot
-- differ. The JavaScript second statement becomes redundant; it is left in
-- place deliberately, because it is also the only mirror on a database that has
-- not had this migration applied yet, and re-asserting a value that is already
-- correct changes nothing.
--
-- ONLY THE COLUMNS THIS CALL ACTUALLY TOUCHES
-- -------------------------------------------
-- A column is re-derived only when the patch, a dotted path, or a deletion
-- names its source field. Re-deriving every mapped column on every patch would
-- be simpler, and wrong: a legacy row whose raw_data never had `status` but
-- whose column does would have that column nulled by the next unrelated write,
-- and vanish from the queue it currently appears in.
--
-- SIGNATURE UNCHANGED
-- -------------------
-- No new parameter, so there is no second overload. Postgres resolves
-- overloads by arity, and this codebase already has one function
-- (credit_wallet_once) existing as two overloads that differ by a single
-- trailing argument — a six-argument call silently picks the shorter one. One
-- definition of this function is worth more than a tidier parameter list.

-- ─── casts that cannot fail ──────────────────────────────────────────────────
--
-- A mapped column is typed and raw_data is not, so the value being mirrored may
-- not fit. Erroring would abort a write whose raw_data half is perfectly valid,
-- so an unconvertible value mirrors as NULL — the same answer the column gives
-- for a field that is absent.

CREATE OR REPLACE FUNCTION jsonb_numeric_or_null(p_value JSONB)
RETURNS NUMERIC
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
    IF p_value IS NULL OR jsonb_typeof(p_value) = 'null' THEN
        RETURN NULL;
    END IF;
    IF jsonb_typeof(p_value) = 'number' THEN
        RETURN (p_value #>> '{}')::numeric;
    END IF;
    IF jsonb_typeof(p_value) = 'string' THEN
        BEGIN
            RETURN (p_value #>> '{}')::numeric;
        EXCEPTION WHEN others THEN
            RETURN NULL;
        END;
    END IF;
    RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION jsonb_text_array_or_null(p_value JSONB)
RETURNS TEXT[]
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_out TEXT[];
BEGIN
    IF p_value IS NULL OR jsonb_typeof(p_value) <> 'array' THEN
        RETURN NULL;
    END IF;
    SELECT array_agg(elem #>> '{}' ORDER BY ord)
      INTO v_out
      FROM jsonb_array_elements(p_value) WITH ORDINALITY AS t(elem, ord)
     WHERE jsonb_typeof(elem) = 'string';
    RETURN COALESCE(v_out, ARRAY[]::TEXT[]);
END;
$$;

-- ─── the mapping, in one place ───────────────────────────────────────────────
--
-- The same pairs as FIELD_TO_COLUMN in lib/supabase-db.ts, in the same order,
-- because that order decides which source field wins when two map to one column
-- (cooperative_members maps both `membershipStatus` and `status` onto `status`,
-- and the JavaScript loop lets the later one win). Kinds: 't' text, 'n'
-- numeric, 'a' text[].
--
-- src/__tests__/pg/native-column-mirror.test.ts asserts this list against
-- FIELD_TO_COLUMN, so the two cannot drift apart silently.

CREATE OR REPLACE FUNCTION native_column_map(p_table TEXT)
RETURNS JSONB
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT CASE p_table
        WHEN 'users' THEN '[
            ["email","email","t"],
            ["roles","roles","a"]
        ]'::jsonb
        WHEN 'cooperative_members' THEN '[
            ["userId","user_id","t"],
            ["membershipStatus","status","t"],
            ["status","status","t"]
        ]'::jsonb
        WHEN 'cooperative_loans' THEN '[
            ["userId","user_id","t"],
            ["status","status","t"],
            ["amount","amount","n"]
        ]'::jsonb
        WHEN 'transactions' THEN '[
            ["userId","user_id","t"],
            ["type","type","t"],
            ["status","status","t"],
            ["amount","amount","n"]
        ]'::jsonb
        WHEN 'processed_payments' THEN '[
            ["userId","user_id","t"],
            ["reference","reference","t"],
            ["amount","amount","n"]
        ]'::jsonb
        WHEN 'marketplace_orders' THEN '[
            ["userId","user_id","t"],
            ["status","status","t"],
            ["totalAmount","total_amount","n"]
        ]'::jsonb
        WHEN 'wallets' THEN '[
            ["balance","balance","n"]
        ]'::jsonb
        WHEN 'academy_applications' THEN '[
            ["userId","user_id","t"],
            ["status","status","t"]
        ]'::jsonb
        ELSE '[]'::jsonb
    END;
$$;

CREATE OR REPLACE FUNCTION apply_document_patch(
    p_table      TEXT,
    p_id         TEXT,
    -- The defaults are 017's, kept verbatim. Dropping them is not a cosmetic
    -- change: CREATE OR REPLACE refuses to remove parameter defaults from an
    -- existing function ("cannot remove parameter defaults"), and dropping the
    -- function first to get around that would leave a window in which any
    -- concurrent write fails.
    p_collection TEXT  DEFAULT NULL,        -- set for document_collections only
    p_patch      JSONB DEFAULT '{}'::jsonb, -- {"status": "paid"}
    p_paths      JSONB DEFAULT '{}'::jsonb, -- {"a.b.c": 1}
    p_deletes    JSONB DEFAULT '[]'::jsonb  -- ["tempField", "a.b"]
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_key      TEXT;
    v_val      JSONB;
    v_raw      TEXT := 'raw_data';
    v_path     TEXT[];
    v_sql      TEXT;
    v_touched  JSONB := '{}'::jsonb;   -- json field name -> true
    v_chosen   JSONB := '{}'::jsonb;   -- column -> [source field, kind]
    v_pair     JSONB;
    v_sets     TEXT[] := ARRAY[]::TEXT[];
    v_field    TEXT;
    v_column   TEXT;
    v_kind     TEXT;
    v_allowed  TEXT[] := ARRAY[
        'users', 'cooperative_members', 'cooperative_loans', 'transactions',
        'processed_payments', 'marketplace_orders', 'wallets',
        'academy_applications', 'document_collections'
    ];
BEGIN
    IF NOT (p_table = ANY(v_allowed)) THEN
        RAISE EXCEPTION 'apply_document_patch: table % is not allowed', p_table;
    END IF;

    IF p_id IS NULL OR TRIM(p_id) = '' THEN
        RAISE EXCEPTION 'apply_document_patch: id is required';
    END IF;

    -- 1. Shallow merge of top-level fields. Same semantics as merge_raw_data,
    --    which is what makes this a safe replacement for it.
    IF p_patch IS NOT NULL AND p_patch <> '{}'::jsonb THEN
        v_raw := format('(%s || %L::jsonb)', v_raw, p_patch);
        FOR v_key IN SELECT k FROM jsonb_each(p_patch) AS t(k, v) LOOP
            v_touched := v_touched || jsonb_build_object(v_key, true);
        END LOOP;
    END IF;

    -- 2. Dotted paths. create_missing = true so a path whose parent does not
    --    exist yet is created rather than silently skipped.
    FOR v_key, v_val IN
        SELECT k, v FROM jsonb_each(COALESCE(p_paths, '{}'::jsonb)) AS t(k, v)
    LOOP
        v_path := string_to_array(v_key, '.');
        -- jsonb_set_deep, not jsonb_set: the parent may not exist yet, and
        -- jsonb_set would silently discard the write. See migration 018.
        v_raw := format('jsonb_set_deep(%s, %L::text[], %L::jsonb)', v_raw, v_path, v_val);
        -- The ROOT segment is what a native column mirrors, so `a.b` touches `a`.
        v_touched := v_touched || jsonb_build_object(v_path[1], true);
    END LOOP;

    -- 3. Deletes, last, so they win.
    FOR v_key IN
        SELECT value #>> '{}' FROM jsonb_array_elements(COALESCE(p_deletes, '[]'::jsonb))
    LOOP
        v_path := string_to_array(v_key, '.');
        IF array_length(v_path, 1) = 1 THEN
            v_raw := format('(%s - %L)', v_raw, v_key);
        ELSE
            v_raw := format('(%s #- %L::text[])', v_raw, v_path);
        END IF;
        v_touched := v_touched || jsonb_build_object(v_path[1], true);
    END LOOP;

    IF v_raw = 'raw_data' THEN
        RETURN; -- nothing to do
    END IF;

    v_sets := ARRAY[format('raw_data = %s', v_raw)];

    -- 4. The native typed columns, in the SAME statement, each derived from the
    --    final raw_data expression above. Only the columns whose source field
    --    this call actually touched — see the migration header.
    --
    --    Deduplicated on the COLUMN, last pair winning, because two source
    --    fields can map onto one column and assigning a column twice in one
    --    UPDATE is an error rather than a last-wins.
    IF p_table <> 'document_collections' THEN
        FOR v_pair IN SELECT value FROM jsonb_array_elements(native_column_map(p_table))
        LOOP
            v_field := v_pair ->> 0;
            IF v_touched ? v_field THEN
                v_chosen := v_chosen || jsonb_build_object(
                    v_pair ->> 1, jsonb_build_array(v_field, v_pair ->> 2));
            END IF;
        END LOOP;

        FOR v_column, v_val IN SELECT k, v FROM jsonb_each(v_chosen) AS t(k, v)
        LOOP
            v_field := v_val ->> 0;
            v_kind := v_val ->> 1;
            IF v_kind = 'n' THEN
                v_sets := v_sets || format(
                    '%1$I = jsonb_numeric_or_null((%2$s) -> %3$L)', v_column, v_raw, v_field);
            ELSIF v_kind = 'a' THEN
                v_sets := v_sets || format(
                    '%1$I = jsonb_text_array_or_null((%2$s) -> %3$L)', v_column, v_raw, v_field);
            ELSE
                v_sets := v_sets || format(
                    '%1$I = (%2$s) ->> %3$L', v_column, v_raw, v_field);
            END IF;
        END LOOP;
    END IF;

    v_sets := v_sets || 'updated_at = NOW()'::TEXT;

    IF p_table = 'document_collections' THEN
        v_sql := format(
            'UPDATE document_collections SET %s WHERE id = %L AND collection_name = %L',
            array_to_string(v_sets, ', '), p_id, p_collection
        );
    ELSE
        v_sql := format(
            'UPDATE %I SET %s WHERE id = %L',
            p_table, array_to_string(v_sets, ', '), p_id
        );
    END IF;

    EXECUTE v_sql;
END;
$$;

COMMENT ON FUNCTION apply_document_patch(TEXT, TEXT, TEXT, JSONB, JSONB, JSONB) IS
    'Targeted JSONB patch. Mirrors the mapped native typed columns in the same '
    'UPDATE (migration 026), because reads take .where() to the column and '
    'doc.data() to raw_data, so the two disagreeing shows up as a list that '
    'contradicts the document it links to.';


-- ============================================================================
-- 027 — 027_dedicated_table_created_at_indexes.sql
-- the created_at indexes the eight DEDICATED tables were promoted without. Order does not matter against the others — they are indexes, not functions — but it belongs IN this file rather than beside it. Its first draft used CREATE INDEX CONCURRENTLY, which cannot run in a transaction, so it could not be applied by the SQL Editor this header says is the only route available here, and it sat unapplied. It is now the plain form under a lock_timeout: ShareLock, reads unaffected, 718 ms of blocked writes on 50,009 rows. See #469 in its header.
-- ============================================================================

-- ============================================================================
-- #467  THE TABLES PROMOTED FOR SPEED LOST THE INDEX THE SLOW ONE KEPT.
-- #469  AND THE FIRST DRAFT OF THIS FILE COULD NOT BE APPLIED BY THE ONLY
--       ROUTE THIS PROJECT HAS.
-- ============================================================================
--
-- The owner reported the admin and user screens loading slowly. Measured, not
-- guessed, against a real PostgreSQL 16 with 50,009 users carrying a document
-- each — the exact query /admin/users issues through useAdminData:
--
--     select id, raw_data from users order by created_at desc limit 20;
--
--   BEFORE                                            26.496 ms
--     Limit  (cost=8081.81..8081.86 rows=20)
--       ->  Sort  (cost=8081.81..8206.83 rows=50009)
--             Sort Key: created_at DESC
--
--   AFTER  create index on users (created_at desc)     0.061 ms
--     Limit  (cost=0.29..3.16 rows=20)
--       ->  Index Scan using idx_users_created_at
--
-- 430x. The whole table was being sorted to find twenty rows, on every page
-- load, and the cost grows with the user base for as long as it keeps growing.
--
-- ============================================================================
-- #469  WHY THESE ARE NOT `CONCURRENTLY`, WHICH IS WHAT THIS FILE SAID FIRST
-- ============================================================================
--
-- The first draft used CREATE INDEX CONCURRENTLY and told the operator to "run
-- this file on its own". They ran it on its own, in the Supabase SQL Editor,
-- and got:
--
--     ERROR: 25001: CREATE INDEX CONCURRENTLY cannot run inside a transaction
--     block
--
-- The SQL Editor wraps every submission in a transaction. There is no setting
-- for that. So "on its own" was never a route that existed here — and
-- scripts/build-deploy-sql.mjs says why, in its own header: this project applies
-- migrations by pasting into the SQL Editor "because neither psql nor the
-- Supabase CLI is installed". The file was written for a tool the operator does
-- not have, and the 430x fix sat unapplied while three separate places in this
-- repository recorded the instruction that could not be followed.
--
-- WHAT THE FIRST DRAFT CLAIMED THE ALTERNATIVE COSTS, AND WHAT IT ACTUALLY
-- COSTS. It said a plain CREATE INDEX "takes an ACCESS EXCLUSIVE lock and blocks
-- every read and write to the table". That is wrong, and it is the reason the
-- cheap route looked unacceptable. Asked directly, on the table in question:
--
--     BEGIN;
--     CREATE INDEX idx_probe ON public.users (created_at DESC);
--     SELECT mode FROM pg_locks ... WHERE pid = pg_backend_pid();
--     -> ShareLock
--
-- ShareLock, not AccessExclusiveLock. SELECTs take ACCESS SHARE, which does not
-- conflict with it: READS KEEP WORKING FOR THE WHOLE BUILD — verified by reading
-- 50,009 rows out of the table while an index build held it. What blocks is
-- WRITES, for as long as the build runs:
--
--     CREATE INDEX on users, 50,009 rows      718 ms   cold cache
--                                              28 ms   warm, repeated
--
-- Under a second of blocked INSERTs on the largest table here, once. Against
-- 26.496 ms of wasted sort on every admin page load, for as long as nobody can
-- apply the file.
--
-- AND THE ONE REAL RISK IS HANDLED, NOT ACCEPTED. The danger of a plain build is
-- not its own duration — it is that a ShareLock request QUEUES behind any open
-- transaction already holding the table, and every writer arriving afterwards
-- queues behind the request. One long-running transaction turns a 718 ms build
-- into a stall. `SET lock_timeout` below removes that: if the lock is not
-- granted within 5 seconds the statement ABORTS instead of queueing. Measured
-- against a held ROW EXCLUSIVE lock: waited 3.035 s at a 3 s setting, then
-- `ERROR: canceling statement due to lock timeout`, with reads unaffected
-- throughout.
--
-- A timed-out run leaves nothing behind and nothing half-built — every statement
-- is IF NOT EXISTS, so re-running it picks up where it stopped. If it times out
-- twice, something is holding a long transaction on that table and THAT is worth
-- finding before forcing an index in beside it.
--
-- IF A TABLE HERE EVER GROWS LARGE ENOUGH that a sub-second write pause is not
-- acceptable, the CONCURRENTLY form is still correct — it just needs a
-- connection that does not wrap statements in a transaction (psql, or the
-- Supabase CLI's `db execute`, neither of which is installed here):
--
--     CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_users_created_at
--         ON public.users (created_at DESC);
--
-- and then, because a failed CONCURRENTLY build leaves an INVALID index behind
-- that the planner ignores and every write still maintains:
--
--     SELECT indexrelid::regclass, indisvalid FROM pg_index WHERE NOT indisvalid;
--
-- dropping anything listed with DROP INDEX CONCURRENTLY before re-running.
--
-- ============================================================================
-- WHY THIS IS THE SHAPE THAT DESERVES AN INDEX, WHERE 022'S WAS NOT
-- ============================================================================
-- Migration 022 is marked DO NOT APPLY on its own measurements: those indexes
-- served `raw_data->>'membershipStatus' = 'active'`, a filter matching 96% of
-- its table, where an index scan is slower than the seq scan it replaces. Its
-- header states the trigger for revisiting it:
--
--     "Apply this only when the EXPLAIN ANALYZE in the header shows a seq scan
--      over a LARGE table returning a SMALL fraction of it."
--
-- ORDER BY created_at DESC LIMIT 20 over 50,009 rows returns 0.04% of the
-- table. That is the case 022 describes, and the plans above are the EXPLAIN
-- ANALYZE it asks for.
--
-- AND THE PROOF THAT THIS IS AN OVERSIGHT RATHER THAN A JUDGEMENT
-- ---------------------------------------------------------------
-- document_collections — the untyped catch-all everything USED to live in —
-- already carries exactly this:
--
--     idx_doc_collections_created_at ON document_collections (collection_name, created_at DESC)
--
-- Every table since PROMOTED out of it into a dedicated table, for performance,
-- was created without one. The optimisation left its own fast path behind. The
-- eight below are every dedicated table that has a created_at column and no
-- index on it, and there are 107 `orderBy("createdAt")` call sites in the
-- application reading them.
--
-- COST OF KEEPING THEM
-- --------------------
-- One btree per table on a column written once at insert and never updated.
-- That is the cheapest index there is to maintain: no update churn, no
-- expression to evaluate, and append-ordered inserts keep the tree balanced.
--
-- HOW TO APPLY
-- ------------
-- Paste this whole file into the Supabase SQL Editor and run it. That works —
-- it is what the file is now written for, and the pg suite proves it by
-- applying this exact file inside BEGIN/COMMIT. It is also included in the
-- consolidated deploy that scripts/build-deploy-sql.mjs generates, so a fresh
-- deployment gets these indexes without anyone remembering this file exists.
--
-- Safe to re-run: every statement is IF NOT EXISTS.
-- ============================================================================

-- Do not queue behind an open transaction and take every writer down with us.
-- See #469 above: this converts the one real risk into a clean, re-runnable
-- failure.
SET lock_timeout = '5s';

CREATE INDEX IF NOT EXISTS idx_users_created_at
    ON public.users (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_marketplace_orders_created_at
    ON public.marketplace_orders (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_processed_payments_created_at
    ON public.processed_payments (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_transactions_created_at
    ON public.transactions (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_cooperative_members_created_at
    ON public.cooperative_members (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_cooperative_loans_created_at
    ON public.cooperative_loans (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_academy_applications_created_at
    ON public.academy_applications (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_wallets_created_at
    ON public.wallets (created_at DESC);

RESET lock_timeout;


-- ============================================================================
-- 028 — 028_users_roles_index.sql
-- the GIN index on users.roles. Order does not matter against the others; it is here because without it EVERY one of the 27 places that filters users by role is a full scan of the users table, and one of them — the Farm Nation forensic — hit the statement timeout in production and reported a whole check as unrunnable. Plain CREATE INDEX under a lock_timeout, per #469.
-- ============================================================================

-- ============================================================================
-- #471  EVERY SCREEN THAT LISTS USERS BY ROLE READ THE WHOLE TABLE.
-- ============================================================================
--
-- The owner's forensics run came back with a check that could not finish at all:
--
--     Farm Nation / Verification Scan
--     Could not complete this scan: [supabase-db] query users:
--     canceling statement due to statement timeout
--
-- That check asks one question:
--
--     SELECT id, raw_data FROM users
--      WHERE roles @> ARRAY['farmer']
--        AND raw_data->>'isVerified' = 'true'
--      LIMIT 50;
--
-- `roles` is a native TEXT[] column and it had NO INDEX. Neither did the JSONB
-- path. So the query is a sequential scan, and — this is the part that turns it
-- from slow into fatal — THE `LIMIT 50` NEVER RESCUES IT. A LIMIT lets a scan
-- stop early only when it FINDS that many rows. There are two or three verified
-- farmers on this platform, so the scan can never fill the limit and must read
-- every row in the table, detoasting each document to evaluate the JSONB path.
--
-- MEASURED against a real PostgreSQL 16 with 50,009 users, with the verified
-- farmers reduced to 3 so the LIMIT cannot be satisfied — production's shape:
--
--   BEFORE                                          21.972 ms   12,571 buffers
--     Seq Scan on users
--       Filter: (roles @> '{farmer}' AND (raw_data->>'isVerified') = 'true')
--       Rows Removed by Filter: 50006
--
--   AFTER  create index using gin (roles)            0.314 ms       67 buffers
--     Bitmap Heap Scan on users
--       Recheck Cond: (roles @> '{farmer}')
--       ->  Bitmap Index Scan on idx_users_roles  (rows=512)
--
-- 70x on time and 188x on blocks touched. THE BLOCK COUNT IS THE NUMBER THAT
-- MATTERS HERE. Locally every one of those 12,571 buffers was a cache hit, which
-- is why 50,009 rows still took only 22 ms. In production they are not: raw_data
-- is a TOASTed JSONB column, so the discarded 50,006 rows are read from disk to
-- be thrown away.
--
-- ============================================================================
-- #472  WHAT THAT 70x IS, AND WHAT IT IS NOT — READ THIS BEFORE QUOTING IT
-- ============================================================================
--
-- The figures above are the QUERY PLAN. They were then checked END TO END,
-- through the adapter the application actually calls, over HTTP, through real
-- PostgREST, to real PostgreSQL:
--
--     50,009 rows    without the index  27 ms      with it   5 ms
--    150,009 rows                       25 ms                4 ms
--    450,009 rows                       45 ms                4 ms
--
-- FIVE TO ELEVEN TIMES END TO END, NOT SEVENTY. A fixed round trip of about
-- 4 ms dominates once the query stops being the slow part. Both numbers are
-- real; they measure different things, and quoting the plan figure as though it
-- were a page-load figure overstates this fix by an order of magnitude.
--
-- AND THE PRODUCTION TIMEOUT WAS NOT REPRODUCED. This migration exists because
-- a forensic check reported
--
--     canceling statement due to statement timeout
--
-- At 450,009 rows on the development machine the UNINDEXED call still answers in
-- 45 ms. Nothing reachable here comes near a multi-second limit, so whatever
-- makes that query exceed it in production — cold cache against network storage,
-- a small shared instance, a shorter timeout than assumed — has NOT been
-- demonstrated, and this index is not proven to clear it. What IS proven, and
-- asserted deterministically in
-- src/__tests__/pg/the-role-scan-reads-the-whole-table-without-the-index.test.ts:
--
--     * without the index the query reads essentially the whole table
--     * with it, at least twenty times fewer blocks
--     * the adapter returns the SAME ROWS either way
--
-- If the check still times out after this is applied, the next step is to
-- measure it THERE rather than to assume more indexes.
-- ============================================================================
--
-- AND IT IS NOT ONE FORENSIC CHECK. `roles` is filtered in 27 places:
--
--   /admin/users                  the role filter and its count query
--   /admin/marketplace            buyers and sellers
--   messages.ts                   every admin, twice, on the notification path
--   wallet.ts                     the notifiable-roles fan-out
--   sms-broadcast.ts              buyers, academy participants, export members
--   in-app-broadcast.ts           buyers
--   communications.service.ts     sellers
--   academy catalogue             instructors
--   forensics.ts                  wave participants, cooperative members, farmers
--
-- Every one of them was a full scan of the users table, on a page load. This is
-- the shape of "the dashboards are slow" that measuring one query at a time
-- kept missing: not one slow page, one missing index under twenty of them.
--
-- WHY THIS IS THE SHAPE THAT DESERVES AN INDEX, WHERE 022'S WAS NOT
-- -----------------------------------------------------------------
-- Migration 022 is marked DO NOT APPLY on its own measurements: its indexes
-- served a filter matching 96% of its table, where an index scan is slower than
-- the seq scan it replaces. Its header sets the test:
--
--     "Apply this only when the EXPLAIN ANALYZE in the header shows a seq scan
--      over a LARGE table returning a SMALL fraction of it."
--
-- 512 farmers of 50,009 rows is 1%. And the planner was asked the other half of
-- 022's question directly — what does it do when a role matches EVERYTHING?
--
--     EXPLAIN ANALYZE SELECT id FROM users WHERE roles @> ARRAY['user'];
--     ->  Seq Scan on users  (rows=50009)
--
-- It ignores the index, correctly. So this index helps the selective roles and
-- costs nothing on the unselective ones. That discrimination is exactly what
-- 022's expression indexes could not make.
--
-- COST, MEASURED RATHER THAN ASSUMED
-- ----------------------------------
--   write   2,000 inserts without the index   14.284 ms
--           2,000 inserts with it             19.029 ms
--           = ~2.4 microseconds per row
--
--   size    176 kB, against a 98 MB table — 0.18%
--
-- GIN rather than btree because the operators are @> (array-contains) and &&
-- (array-contains-any), which btree cannot serve at all. Both are measured
-- above; `&&` becomes a Bitmap Index Scan too.
--
-- HOW TO APPLY
-- ------------
-- Paste this file into the Supabase SQL Editor and run it, or let it arrive in
-- the consolidated deploy. Plain CREATE INDEX under a lock_timeout, for the
-- reason #469 records in 027's header: CONCURRENTLY cannot run in a transaction
-- and the SQL Editor always opens one, so a CONCURRENTLY migration here is a
-- migration that never gets applied. The build takes a ShareLock — reads are
-- unaffected, writes pause for the duration — and the lock_timeout turns
-- queueing behind an open transaction into a clean, re-runnable abort.
--
-- Safe to re-run: IF NOT EXISTS.
-- ============================================================================

SET lock_timeout = '5s';

CREATE INDEX IF NOT EXISTS idx_users_roles
    ON public.users USING GIN (roles);

RESET lock_timeout;


-- ============================================================================
-- 029 — 029_user_segment_counts.sql
-- user_segment / count_user_segments — the four admin dashboard counters. MUST ship with the code that calls them: analytics.service.ts asks for the RPC first and falls back to reading the WHOLE users table when it is missing, which is #473 itself (4.6 MB and 51 simultaneous requests per cold /admin load). Without this file the deploy is slow rather than broken, and says so in the logs.
-- ============================================================================

-- ============================================================================
-- #473  THE ADMIN DASHBOARD DOWNLOADED THE ENTIRE USERS TABLE TO COUNT FOUR
--       NUMBERS.
-- ============================================================================
--
-- analytics.service.ts calculateUserSegments():
--
--     const totalPages = Math.ceil(count / pageSize);   // 50,009 / 1000 = 51
--     for (let page = 0; page < totalPages; page++) {
--         promises.push(supabaseAdmin.from("users").select(...).range(...));
--     }
--     await Promise.all(promises);
--
-- Every row of the users table, fetched over HTTP, to classify each user in
-- JavaScript and report four totals: active, pending, stalled, ghost.
--
-- MEASURED, not guessed — a real browser logged in as admin against a real
-- PostgREST and a real PostgreSQL with 50,009 users, every database round trip
-- recorded with its HTTP method and payload size:
--
--     /admin, cold load        96 round trips
--       count-only (HEAD)      29 calls, 1,415 ms      — correct, and cheap
--       returning rows         67 calls, 8,795 ms, 4.6 MB transferred
--
-- Over fifty of those 67 are this one loop, at 92 kB a page. The four counters
-- are its entire output.
--
-- AND IT FIRES ALL FIFTY-ONE AT ONCE. Promise.all on every page means the
-- connection pool is saturated by one dashboard widget. Everything else the
-- page needs — and anything another request needs at that moment — queues behind
-- it. The Farm Nation forensic reporting `canceling statement due to statement
-- timeout` while this was in flight is consistent with that, though not proven
-- to be caused by it.
--
-- On Railway the cost is per container: every restart, every deploy, every new
-- instance, and every cache expiry pays it again.
--
-- WHY A FUNCTION RATHER THAN FILTERS
-- ----------------------------------
-- getModuleRegistrationStats() a few hundred lines below does this correctly
-- with `head: true` counts and `or=` filters, and that is the pattern to copy
-- where it fits. It does not fit here. The classification iterates the KEYS of
-- serviceRegistrations — `Object.values(regs).some(...)` — and PostgREST has no
-- way to express "any value in this object has a status of X". jsonb_each does,
-- so the rule moves into SQL rather than being approximated by a filter that
-- would silently disagree.
--
-- THE RULE IS COPIED EXACTLY, INCLUDING ITS ODDITIES
-- --------------------------------------------------
-- These four counters appear on the admin dashboard. If this function and the
-- JavaScript disagree, the numbers change without anyone noticing, which is a
-- worse defect than the slowness. So the asymmetries in the original are
-- REPRODUCED, not tidied:
--
--   * verificationProfile.bankDetails.bankName excludes the literal "N/A".
--     bankDetails.bankName does NOT. Same for address.state. That is what
--     broadcast-logic.ts:30-31 says, and both branches are kept as written.
--
--   * "suspended" is in neither the approved list nor the pending list, so a
--     suspended registration falls through to `hasStartedAny` and counts as
--     STALLED. Deliberately preserved.
--
--   * precedence is active > pending > stalled > ghost, first match wins.
--
-- jsonb_truthy() exists because `r.status && ...` is JavaScript truthiness, not
-- "is present". null, false, 0 and "" are all falsy there, and `->>` would
-- render false and 0 as the non-empty strings 'false' and '0'. Anything else —
-- objects and arrays included, which are truthy in JavaScript — is truthy here.
--
-- ONE BEHAVIOUR IS DELIBERATELY NOT COPIED, BECAUSE IT IS A CRASH.
-- `Object.values(regs).some((r: any) => r.status === ...)` throws TypeError if
-- any registration value is null, and calculateUserSegments has no try around
-- the loop — so ONE malformed user record blanks all four counters for
-- everybody. jsonb_each simply yields a null value with no status, which is the
-- answer the JavaScript would give if it survived to give one.
--
-- HOW TO APPLY
-- ------------
-- Paste into the Supabase SQL Editor, or let it arrive in the consolidated
-- deploy. Plain CREATE OR REPLACE, transaction-safe, per #469.
--
-- The application FALLS BACK to the old paging loop if this function is absent,
-- and says so loudly in the logs, so deploying the code before applying this is
-- slow rather than broken.
-- ============================================================================

-- JavaScript truthiness for a jsonb value.
--
-- Absent (SQL NULL), JSON null, false, 0 and "" are falsy. Everything else,
-- including objects and arrays, is truthy — which is what `if (x)` does.
CREATE OR REPLACE FUNCTION jsonb_truthy(v jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
    SELECT v IS NOT NULL
       AND jsonb_typeof(v) <> 'null'
       AND v <> 'false'::jsonb
       AND v <> '0'::jsonb
       AND v <> '""'::jsonb;
$$;

-- Which segment one user's document falls into.
--
-- Mirrors categorizeUser() in src/lib/broadcast-logic.ts. The two are held
-- together by src/__tests__/pg/the-sql-segments-agree-with-the-javascript.test.ts,
-- which classifies the same users both ways and fails on any single
-- disagreement.
CREATE OR REPLACE FUNCTION user_segment(doc jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
    SELECT CASE
        WHEN jsonb_path_exists(doc,
            '$.serviceRegistrations.*.status ? (@ == "approved" || @ == "active" || @ == "paid" || @ == "completed")')
        THEN 'active'

        WHEN jsonb_path_exists(doc,
            '$.serviceRegistrations.*.status ? (@ == "pending" || @ == "submitted" || @ == "under_review" || @ == "briefing")')
        THEN 'pending'

        -- hasStartedAny: `r.status && r.status !== "not_started"`.
        --
        -- The type tests are not defensive padding — they are the rule. JSONPath
        -- comparison BETWEEN DIFFERENT TYPES yields Unknown, not false, so a
        -- plain `@ != false` silently discards every string status and the whole
        -- predicate collapses. Each JavaScript-falsy value is therefore excluded
        -- within its own type, and objects and arrays are admitted because
        -- `if (x)` admits them.
        WHEN jsonb_path_exists(doc,
            '$.serviceRegistrations.*.status ? ((@.type() == "string" && @ != "" && @ != "not_started") || (@.type() == "number" && @ != 0) || (@.type() == "boolean" && @ == true) || @.type() == "object" || @.type() == "array")')
          -- hasBank: the verificationProfile branch excludes "N/A"; the
          -- top-level branch does not. broadcast-logic.ts:30, as written.
          OR (jsonb_truthy(doc->'verificationProfile'->'bankDetails'->'bankName')
              AND doc->'verificationProfile'->'bankDetails'->>'bankName' IS DISTINCT FROM 'N/A')
          OR jsonb_truthy(doc->'bankDetails'->'bankName')
          -- hasAddress: same asymmetry. broadcast-logic.ts:31.
          OR (jsonb_truthy(doc->'verificationProfile'->'address'->'state')
              AND doc->'verificationProfile'->'address'->>'state' IS DISTINCT FROM 'N/A')
          OR jsonb_truthy(doc->'address'->'state')
        THEN 'stalled'

        ELSE 'ghost'
    END;
$$;

-- ============================================================================
-- WHY THIS SHAPE, AND WHAT THE TWO REJECTED ONES COST — ALL THREE MEASURED
-- ============================================================================
--
-- Counting 50,009 users:
--
--   CTE + three EXISTS over jsonb_each      2,640 ms
--   one pass, three bool_or aggregates      2,811 ms
--   jsonb_path_exists, as above                35 ms
--
-- The obvious translation of `Object.values(regs).some(...)` is jsonb_each, and
-- BOTH jsonb_each versions are ~80x slower — not because expanding the object
-- is expensive (done set-based inline it takes 182 ms) but because a SQL
-- function containing a FROM clause CANNOT BE INLINED. Postgres calls it once
-- per row, 50,009 times. jsonb_path_exists is a scalar expression, so the whole
-- function inlines into the surrounding query and the per-call cost disappears.
--
-- THE FIRST VERSION WAS SHIPPED-SHAPED AND WRONG ANYWAY. It cut /admin from
-- 4.6 MB to 1 kB and 51 whole-table requests to 0 — and made the page SLOWER,
-- 2.3 s to 6.0 s, because a 2.6 s function had replaced the transfer. Fewer
-- round trips is not the same thing as a faster page, and the only way to know
-- which one happened is to load the page and look.
-- ============================================================================

-- The four counters, in ONE round trip, with no rows leaving the database.
--
-- Returns every segment even when its count is zero, so a caller never has to
-- tell "no such segment" from "none this time".
CREATE OR REPLACE FUNCTION count_user_segments()
RETURNS TABLE (active bigint, pending bigint, stalled bigint, ghost bigint)
LANGUAGE sql
STABLE
AS $$
    SELECT
        count(*) FILTER (WHERE seg = 'active')::bigint,
        count(*) FILTER (WHERE seg = 'pending')::bigint,
        count(*) FILTER (WHERE seg = 'stalled')::bigint,
        count(*) FILTER (WHERE seg = 'ghost')::bigint
    FROM (SELECT user_segment(raw_data) AS seg FROM public.users) s;
$$;

-- Grant to the PostgREST roles, IF THEY EXIST.
--
-- Postgres gives functions EXECUTE to PUBLIC by default, so these are belt and
-- braces against a database that has revoked it — no other migration here
-- grants at all, which is why they all work.
--
-- The guard is not decoration: scripts/test-migrations.sh applies every
-- migration to a THROWAWAY cluster that has no Supabase roles, and an
-- unguarded GRANT failed there with `role "anon" does not exist`. That harness
-- is the only automatic check that these files apply in order, so a migration
-- it cannot run is a migration nothing verifies.
DO $$
DECLARE
    r text;
BEGIN
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('GRANT EXECUTE ON FUNCTION jsonb_truthy(jsonb) TO %I', r);
            EXECUTE format('GRANT EXECUTE ON FUNCTION user_segment(jsonb) TO %I', r);
            EXECUTE format('GRANT EXECUTE ON FUNCTION count_user_segments() TO %I', r);
        END IF;
    END LOOP;
END $$;

-- ============================================================================
-- AND TELL PostgREST THE FUNCTION EXISTS.
-- ============================================================================
--
-- Creating a function is not enough to make it callable over the REST API.
-- PostgREST serves RPC from a CACHED schema, and until that cache is reloaded
-- the call fails with
--
--     Could not find the function public.count_user_segments without
--     parameters in the schema cache
--
-- This was not reasoned about — it was MEASURED. The application change was
-- made, the migration applied, the admin page loaded in a real browser, and the
-- page still made all 51 whole-table requests: the RPC had failed and the
-- fallback had quietly carried it. A fix that silently degrades to the thing it
-- replaced looks exactly like a fix that works, which is why the before/after
-- was taken from the page rather than from the migration applying cleanly.
--
-- Supabase installs an event trigger that usually issues this itself after DDL.
-- "Usually" is not a guarantee worth resting the fix on, and the notify is free
-- and idempotent.
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- 030 — 030_find_users_by_normalised_email.sql
-- find_users_by_normalised_email + the index it needs. MUST ship with the code that calls it: lib/auth.ts falls back to it when the exact email match finds nothing, and WITHOUT it a profile stored with different case or surrounding space stays invisible and login auto-provisions a blank profile over the top — #476, which is the owner's 'account not found / missing details even when fully registered'.
-- ============================================================================

-- ============================================================================
-- #476  A PROFILE STORED WITH DIFFERENT CASE OR SURROUNDING SPACE IS INVISIBLE
--       TO LOGIN, AND LOGIN THEN CREATES A BLANK ONE OVER THE TOP.
-- ============================================================================
--
-- lib/auth.ts finds the caller's profile with
--
--     db.collection(USERS).where('email', '==', email.toLowerCase())
--
-- The INPUT is lowercased. The STORED VALUE is not normalised at all. Proven
-- against a real PostgreSQL, with a row stored exactly as legacy data is:
--
--     stored:  [  Ada@Example.COM ]   roles: wave_participant, academy_participant
--
--     where email = 'ada@example.com'                    ->  0 rows
--     where lower(btrim(email)) = 'ada@example.com'      ->  1 row
--
-- WHAT HAPPENS TO THAT PERSON. Supabase Auth verifies them — they typed the
-- right password, they are who they say. The profile query returns empty, and
-- auth.ts takes the branch immediately below it:
--
--     logger.info("... no profile found in database. Auto-provisioning ...")
--     const defaultProfile = {
--         roles: ['general_user'],
--         fullName: email.split('@')[0],
--         profileComplete: false,
--         ...
--     };
--     await db.collection(USERS).doc(newUid).set(defaultProfile, { merge: true });
--
-- They log in and their name, their roles and their approved registrations are
-- gone. That is the owner's report, in the owner's words: "account not found or
-- missing details even when they are fully registered", "missing details after
-- they got enrolled successfully".
--
-- AND IT COMPOUNDS. The auto-provision writes a SECOND row, under the auth id,
-- while the real profile stays under its legacy id. Both now match the email
-- query, neither identifies with the auth account by the first two rules, and
-- every later login falls to auth.ts's last resort — `?? userSnap.docs[0]` —
-- which picks whichever row comes back first. One person, two profiles, and
-- which one they get is arbitrary.
--
-- THIS REPOSITORY ALREADY KNEW. #465's authAccountsWithProfiles normalises BOTH
-- sides — `email.trim().toLowerCase()` — and its test asserts that
-- '  Ada@Example.COM ' matches 'ada@example.com'. The forensic scan was taught
-- this and the LOGIN was not. Fifth time in this audit that a fix reached some
-- of the doors, and this door is the front one.
--
-- WHY A FUNCTION AND NOT `ilike`
-- ------------------------------
-- The obvious patch is a case-insensitive match, and it is wrong twice over.
-- Measured against the real PostgREST:
--
--     email=ilike.ada@example.com      ->  []          (the spaces defeat it)
--     email=ilike.*ada@example.com*    ->  the row     (and much else)
--
-- Only the WILDCARD form finds it, and a wildcard on an identity lookup is a
-- security defect: `*ada@example.com*` also matches `xada@example.com.attacker`
-- — a different account, containing this address as a substring. A login must
-- not resolve identity by substring. `lower(btrim(...))` is an exact match on a
-- normalised value, which is what was meant all along.
--
-- NOTHING IS REWRITTEN. The stored emails are left exactly as they are. This
-- adds a way to FIND them, not a migration that edits identity data on a live
-- table — the owner's standing instruction, and the right call regardless:
-- rewriting the email column is a change to how every other row is matched, and
-- it is not needed to fix this.
--
-- THE INDEX IS WHAT KEEPS IT HONEST. Without it this is a sequential scan of
-- 42,141 users on every login that reaches the fallback. With it, an index scan.
-- Same shape as #471, and the same test 022 asks for: a large table returning
-- one row.
--
-- HOW TO APPLY
-- ------------
-- Paste into the Supabase SQL Editor, or let it arrive in the consolidated
-- deploy. Transaction-safe, per #469.
-- ============================================================================

-- Exact match on the normalised value, indexed.
CREATE INDEX IF NOT EXISTS idx_users_email_normalised
    ON public.users (lower(btrim(email)));

/**
 * Every profile whose email matches, ignoring case and surrounding space.
 *
 * Returns rows, not ids, so the caller does not need a second round trip — the
 * login path is latency-sensitive and this only runs when the exact match has
 * already failed.
 */
CREATE OR REPLACE FUNCTION find_users_by_normalised_email(p_email text)
RETURNS TABLE (id text, raw_data jsonb)
LANGUAGE sql
STABLE
AS $$
    SELECT u.id, u.raw_data
      FROM public.users u
     WHERE lower(btrim(u.email)) = lower(btrim(p_email))
     -- Bounded. A caller resolving ONE identity does not need an unbounded
     -- list, and an email matching hundreds of rows is a finding of its own
     -- rather than something to page through during a login.
     LIMIT 50;
$$;

-- Grant to the PostgREST roles, IF THEY EXIST — see 029 for why this is
-- guarded: scripts/test-migrations.sh applies every migration to a throwaway
-- cluster that has no Supabase roles.
DO $$
DECLARE
    r text;
BEGIN
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('GRANT EXECUTE ON FUNCTION find_users_by_normalised_email(text) TO %I', r);
        END IF;
    END LOOP;
END $$;

-- PostgREST serves RPC from a cached schema and will not see this function
-- until told. #473 measured what skipping this costs: the migration applies
-- cleanly, the code is correct, and the call fails with "could not find the
-- function ... in the schema cache" while the fallback quietly carries it.
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- 031 — 031_find_users_by_normalised_emails_batch.sql
-- find_users_by_normalised_emails — the BATCH form, for the ghost scan and the orphan repair. MUST ship with lib/auth-profile-link.ts: without it people whose profile is stored with odd case or spacing are reported as orphaned AND the repair may write them a duplicate (#478).
-- ============================================================================

-- ============================================================================
-- #478  THE GHOST SCAN AND THE ORPHAN REPAIR HAD #476'S DEFECT TOO — AND THE
--       REPAIR IS THE HALF THAT WRITES.
-- ============================================================================
--
-- #476 fixed the LOGIN's profile lookup: it compared a lowercased input against
-- a stored column that is not normalised, so a row held as
--
--     [  Ada@Example.COM ]
--
-- was invisible to `where email = 'ada@example.com'`.
--
-- lib/auth-profile-link.ts has the same shape, one line down:
--
--     db.collection(USERS).where('email', 'in', chunk).get()
--     ...
--     const uid = uidByEmail.get(key(d.data()?.email));   // key() normalises
--
-- It normalises the stored value AFTER fetching — and never fetches the row,
-- because the `in` filter compares the raw column. So the normalisation reads
-- as though the case is handled, and it is not.
--
-- WHY THAT MATTERS MORE HERE THAN IT DID AT THE LOGIN. Three callers share this
-- resolution, and #466 is the finding that put them together:
--
--   forensics.ts            reports these people as "ghosts" — auth account,
--                           no profile — when they have one all along.
--
--   detectOrphanedUsers     lists them on /admin/orphaned-users.
--
--   repairOrphanedUser      guards on it and then CREATES A PROFILE. For
--                           somebody whose profile is merely stored with odd
--                           spacing, that guard passes and the repair writes a
--                           SECOND row — which is exactly the duplicate
--                           condition #477 exists to survive, manufactured by
--                           the button meant to fix it.
--
-- #466 closed this door for MIGRATED profiles. It is the same door, and the
-- badly-stored-email case walks straight through it. Sixth
-- fix-reaches-one-of-N in this audit.
--
-- WHY A BATCH FUNCTION. The scan resolves up to 100 accounts at a time and
-- already chunks its queries; calling the single-email function from #476 once
-- per outstanding account would turn one round trip into a hundred, on a scan
-- that #465 had to make cheaper because it was TIMING OUT. This takes the whole
-- outstanding list at once.
--
-- IT RETURNS THE EMAIL as well as the id, because the caller has to map the row
-- back to the auth account it was looking for, and the stored value is exactly
-- what it cannot assume.
--
-- The index from 030 — users (lower(btrim(email))) — serves this too.
--
-- Transaction-safe, per #469.
-- ============================================================================

CREATE OR REPLACE FUNCTION find_users_by_normalised_emails(p_emails text[])
RETURNS TABLE (id text, email text, raw_data jsonb)
LANGUAGE sql
STABLE
AS $$
    SELECT u.id, u.email, u.raw_data
      FROM public.users u
     WHERE lower(btrim(u.email)) = ANY (
               SELECT lower(btrim(e)) FROM unnest(p_emails) AS e
           )
     -- Bounded, like the single-email version. A scan resolving 100 accounts
     -- does not need an unbounded result, and an email on hundreds of rows is a
     -- finding rather than something to page through.
     LIMIT 500;
$$;

-- Guarded, per 029: scripts/test-migrations.sh applies every migration to a
-- throwaway cluster that has no Supabase roles.
DO $$
DECLARE
    r text;
BEGIN
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('GRANT EXECUTE ON FUNCTION find_users_by_normalised_emails(text[]) TO %I', r);
        END IF;
    END LOOP;
END $$;

-- PostgREST serves RPC from a cached schema. #473 measured what skipping this
-- costs: the migration applies, the code is right, and the call fails while a
-- fallback silently carries it.
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- 032 — 032_users_email_normalised_column.sql
-- users.email_normalised, the generated column every email filter is routed to. MUST ship with the adapter change in supabase-db.ts — the two are one fix. Applied WITHOUT the code, nothing changes; the code WITHOUT this sends email_normalised=eq.… to a column that does not exist and every email lookup fails, so keep them together and apply this first.
-- ============================================================================

-- ============================================================================
-- #478  EVERY EMAIL LOOKUP ON users COMPARES A NORMALISED VALUE, ONCE.
-- ============================================================================
--
-- #476 found the LOGIN missing a profile stored as '  Ada@Example.COM ':
--
--     where email = 'ada@example.com'                ->  0 rows
--     where lower(btrim(email)) = 'ada@example.com'  ->  1 row
--
-- and the branch below it then wrote a BLANK profile over the top, losing the
-- person's roles and registrations. #477 found the same shape in the ghost scan
-- and the orphan repair — where the repair CREATES profiles — and #478 found a
-- third copy in preValidateLoginAction, the one that decides which profile the
-- JIT migration copies FROM.
--
-- A grep then found twenty-four more: session-guard.ts, password-reset.ts,
-- module-access-check.ts, six cooperative lookups, the briefing flow, the admin
-- search. Patching them one at a time is precisely how this reached three
-- copies without anybody noticing, so it is fixed at the one place they all
-- pass through — the adapter — and this column is what lets the adapter do it.
--
-- WHY A GENERATED COLUMN AND NOT AN EXPRESSION INDEX ALONE. 030 already adds
-- `users (lower(btrim(email)))`, and Postgres will use it — but PostgREST can
-- only filter on COLUMNS, so the adapter has nothing to send. A stored
-- generated column gives it one, and the index below makes the lookup a single
-- index scan.
--
-- MEASURED on 50,017 rows: the ALTER rewrites the table in 762 ms, and the
-- lookup afterwards is
--
--     Index Scan using idx_users_email_normalised_col  (rows=1)  0.019 ms
--
-- Under a lock_timeout, for #469's reason: the rewrite takes an ACCESS
-- EXCLUSIVE lock — genuinely, unlike a plain CREATE INDEX — so it must not
-- queue behind an open transaction and take every reader down with it. A
-- timed-out run changes nothing and can simply be run again.
--
-- NOTHING IS REWRITTEN IN THE EMAIL COLUMN ITSELF. The stored values are left
-- exactly as they are; this adds a normalised VIEW of them beside the original.
-- The raw address is still what the platform displays and sends mail to.
--
-- AND IT IS NOT ADDED TO NATIVE_COLUMNS in the adapter, deliberately: that list
-- drives the WRITE path, and a generated column cannot be written. It is a
-- read-side routing target only.
-- ============================================================================

SET lock_timeout = '5s';

ALTER TABLE public.users
    ADD COLUMN IF NOT EXISTS email_normalised text
    GENERATED ALWAYS AS (lower(btrim(email))) STORED;

CREATE INDEX IF NOT EXISTS idx_users_email_normalised_col
    ON public.users (email_normalised);

RESET lock_timeout;

-- PostgREST must learn the new column before it can filter on it. Without this
-- the adapter sends `email_normalised=eq.…` and PostgREST answers "column does
-- not exist" — #473's lesson, and this time it would break every email lookup
-- rather than degrade one counter.
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- 033 — 033_find_users_by_supabase_auth_id.sql
-- idx_users_supabase_auth_id and find_users_by_supabase_auth_ids — the fourth and only email-free route from an auth account to its profile. Without it, a profile carrying no email address (49 of them, minted by two admin approvals before #489) cannot be linked to its owner: the forensic scan reports those people as ghosts and the repair beside it may write each of them a duplicate profile. Measured 23.608 ms -> 0.298 ms on the batch of 100 the scan issues.
-- ============================================================================

-- ============================================================================
-- #489  A PROFILE WITH NO EMAIL CAN ONLY BE FOUND BY A POINTER, AND THE
--       POINTER HAD NO INDEX.
-- ============================================================================
--
-- authAccountsWithProfiles joins an auth account to its profile three ways:
-- by document id, by `email`, and by normalised email (migration 031). Every
-- one of those needs either the right key or an address.
--
-- A profile with NO email answers to none of them. Forty-nine of those exist,
-- minted by two admin approvals that wrote `email: ""` — see
-- lib/profile-email-resolution.ts. Where such a profile is ALSO not keyed by
-- the auth id (a migrated account: user-migration.ts leaves the profile under
-- its original Firebase-era id), the person is unreachable by every route the
-- platform has, and the forensic scan reports them as a GHOST.
--
-- That is the link between the owner's two standing findings. They are one
-- defect seen from two sides.
--
-- THE FOURTH ROUTE IS THE POINTER MIGRATION ALREADY WRITES.
-- user-migration.ts sets `supabaseAuthId` on the legacy profile, and
-- profile-choice.ts and password-reset.ts both read it. It is the strongest
-- link of the four — an explicit statement that this profile belongs to that
-- auth account — and it is the only one that works without an email.
--
-- WHY IT WAS NOT USED. auth-profile-link.ts records the reason plainly:
--
--     "deliberately not by `supabaseAuthId`: that field lives inside raw_data
--      with no index, and #465 measured what querying it costs —
--      `canceling statement due to statement timeout`."
--
-- The reason was the missing index, not the field. This adds it.
--
-- ============================================================================
-- MEASURED, on a real PostgreSQL 16: 50,017 users, 5,000 carrying the pointer
-- ============================================================================
--
-- The query the scan actually issues is a BATCH of up to 100 ids, not one:
--
--   SELECT id, raw_data->>'supabaseAuthId' FROM users
--   WHERE raw_data->>'supabaseAuthId' = ANY($1);
--
--   BEFORE                          23.608 ms   Seq Scan, 49,917 rows removed
--   AFTER   3 runs                   0.298 ms   Index Scan
--                                    0.254 ms
--                                    0.289 ms
--
-- ~80x, and the shape matters more than the ratio: the seq scan's cost grows
-- with the whole user table on every scan, while the index scan's grows with
-- the 100 ids asked about. A single-id lookup goes 19.019 ms -> 0.046 ms.
--
-- A btree on an EXPRESSION, not a GIN over raw_data: this is an equality test
-- on one extracted text value, which is exactly what a btree serves.
--
-- COST OF KEEPING IT. 480 kB, over a value written once at migration and never
-- updated. A btree does not index NULLs, so it covers only the rows that carry
-- the pointer — 5,000 here, not all 50,017.
--
-- ============================================================================
-- HOW TO APPLY  (#469)
-- ============================================================================
-- Paste this whole file into the Supabase SQL Editor and run it. The Editor
-- always opens a transaction, so nothing here uses CONCURRENTLY; a plain
-- CREATE INDEX takes a ShareLock, which blocks WRITES to `users` for the build
-- and leaves reads working throughout. `SET lock_timeout` below turns the one
-- real risk — queueing behind an open transaction — into a clean, re-runnable
-- failure.
--
-- Safe to re-run: every statement is IF NOT EXISTS or CREATE OR REPLACE.
-- ============================================================================

SET lock_timeout = '5s';

CREATE INDEX IF NOT EXISTS idx_users_supabase_auth_id
    ON public.users ((raw_data->>'supabaseAuthId'));

RESET lock_timeout;

-- ============================================================================
-- The batch lookup the scan calls.
-- ============================================================================
--
-- BATCH, like migration 031 and for the same reason: the ghost scan resolves
-- up to 100 auth accounts at a time, and 100 round trips is what #465 measured
-- as a timeout. One call, one index scan per id.
--
-- Returns the pointer alongside the profile id so the caller can map a row back
-- to the account that asked for it without a second pass.
CREATE OR REPLACE FUNCTION find_users_by_supabase_auth_ids(p_auth_ids text[])
RETURNS TABLE (id text, supabase_auth_id text)
LANGUAGE sql
STABLE
AS $$
    SELECT u.id::text, (u.raw_data->>'supabaseAuthId')::text
    FROM public.users u
    WHERE u.raw_data->>'supabaseAuthId' = ANY(p_auth_ids);
$$;

-- Guarded like migration 029's: `anon` and `authenticated` do not exist in the
-- bare PostgreSQL the migration suite runs against, and an unguarded GRANT
-- fails the whole file there.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
        GRANT EXECUTE ON FUNCTION find_users_by_supabase_auth_ids(text[]) TO anon;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
        GRANT EXECUTE ON FUNCTION find_users_by_supabase_auth_ids(text[]) TO authenticated;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
        GRANT EXECUTE ON FUNCTION find_users_by_supabase_auth_ids(text[]) TO service_role;
    END IF;
END
$$;

-- #473: PostgREST caches its schema, and a new function is invisible until it
-- reloads. Without this the RPC fails with "could not find the function ... in
-- the schema cache", the caller falls back, and the page looks fixed while
-- nothing has changed.
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- 034 — 034_user_segment_counts_widened.sql
-- user_segment, WIDENED — #536. The four dashboard counters read two spellings of address and two of bank while the platform's own writers use seven and four, so a member carrying stateOfOrigin and a verified bankAccountNumber was counted under 'minimal data'. MUST ship with the matching change to categorizeUser in lib/broadcast-logic.ts: the two are one rule and a parity suite fails on a single disagreement. Applied without the code the dashboard and the broadcast segments disagree; the code without this leaves the dashboard exactly as it was, because it reads the RPC. CREATE OR REPLACE over 029, transaction-safe.
-- ============================================================================

-- ============================================================================
-- #536  THE GHOST BUCKET READ TWO SPELLINGS OF ADDRESS AND TWO OF BANK.
--       THE PLATFORM WRITES SEVEN AND FOUR.
-- ============================================================================
--
-- Reported by the owner, who opened /admin and saw
--
--     Ghost   19,853 (47.1%)   Incomplete registrations / minimal data
--
-- and asked whether the data had fallen out of sync with the database. It had
-- not. user_segment() and categorizeUser() agree exactly — 029 and its parity
-- test made sure of that — and BOTH read a narrower set of keys than the
-- platform's own writers use:
--
--   _wv_applications writes onto the USER row  stateOfOrigin, residentialState,
--                                              lga, residentialAddress
--   admin/_legacy (the importer)               stateOfOrigin, lga,
--                                              residentialAddress, address.state
--   bank-account.ts                            bankAccountNumber, bankName,
--                                              bankCode, bankAccountName, and
--                                              the nested bankDetails block
--
-- So a member carrying `stateOfOrigin: "Kano"` and a verified
-- `bankAccountNumber` — everything a payout needs — was counted under "minimal
-- data" because the two keys this function read were not the two the writer
-- used.
--
-- WHY A NEW FILE RATHER THAN AN EDIT TO 029
-- -----------------------------------------
-- 029 has been applied. Editing an applied migration means the file on disk and
-- the function in the database disagree for every cluster that already ran it,
-- and the only way to tell is to read the catalog. CREATE OR REPLACE in a new
-- file is the whole change and it is transaction-safe, per #469.
--
-- THE ODDITY 029 PRESERVED IS NOW GONE, DELIBERATELY
-- --------------------------------------------------
-- 029 reproduced an asymmetry it called load-bearing: the verificationProfile
-- branches excluded the literal 'N/A' and the top-level ones did not. That was
-- the right call THEN — the rule was being moved, not changed, and reproducing
-- it exactly is what made the move safe.
--
-- It is being changed now, on purpose, because widening the reads without
-- widening the placeholder rule would count 'N/A' as an address. The importer
-- writes that string. jsonb_present() below applies one rule to all of them and
-- mirrors present() in broadcast-logic.ts.
--
-- WHAT DID NOT CHANGE: precedence is still active > pending > stalled > ghost,
-- first match wins; "suspended" still falls through to hasStartedAny and counts
-- as STALLED; JavaScript truthiness is still what jsonb_truthy models. Phone and
-- name are still not counted as data — the segments feed broadcast targeting,
-- where Ghost means "zero activity", and a phone number is not activity.
--
-- HELD TO THE JAVASCRIPT by
-- src/__tests__/pg/the-sql-segments-agree-with-the-javascript.test.ts, which
-- classifies the same documents both ways and fails on a single disagreement.
-- That suite needs a local cluster and SKIPS LOUDLY without one, so on a machine
-- with no PostgreSQL this file is checked by review and by the JavaScript half
-- alone. Saying so is part of the change.
-- ============================================================================

-- Is there a real value here? Placeholders and whitespace are not.
--
-- Mirrors present() in src/lib/broadcast-logic.ts. Non-strings fall back to
-- JavaScript truthiness, which is what jsonb_truthy already models.
CREATE OR REPLACE FUNCTION jsonb_present(v jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
    SELECT CASE
        WHEN v IS NULL OR jsonb_typeof(v) = 'null' THEN false
        WHEN jsonb_typeof(v) = 'string' THEN
            lower(btrim(v #>> '{}')) NOT IN ('', 'n/a', 'na', 'none', 'null', 'undefined', '-')
        ELSE jsonb_truthy(v)
    END;
$$;

-- Which segment one user's document falls into — #536's widened reads.
CREATE OR REPLACE FUNCTION user_segment(doc jsonb)
RETURNS text
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
    SELECT CASE
        WHEN jsonb_path_exists(doc,
            '$.serviceRegistrations.*.status ? (@ == "approved" || @ == "active" || @ == "paid" || @ == "completed")')
        THEN 'active'

        WHEN jsonb_path_exists(doc,
            '$.serviceRegistrations.*.status ? (@ == "pending" || @ == "submitted" || @ == "under_review" || @ == "briefing")')
        THEN 'pending'

        -- hasStartedAny: `r.status && r.status !== "not_started"`. Unchanged
        -- from 029 — see that file for why each JavaScript-falsy value is
        -- excluded within its own type.
        WHEN jsonb_path_exists(doc,
            '$.serviceRegistrations.*.status ? ((@.type() == "string" && @ != "" && @ != "not_started") || (@.type() == "number" && @ != 0) || (@.type() == "boolean" && @ == true) || @.type() == "object" || @.type() == "array")')

          -- hasBank: every spelling bank-account.ts and the importer write.
          OR jsonb_present(doc->'verificationProfile'->'bankDetails'->'bankName')
          OR jsonb_present(doc->'bankDetails'->'bankName')
          OR jsonb_present(doc->'bankDetails'->'accountNumber')
          OR jsonb_present(doc->'bankAccountNumber')
          OR jsonb_present(doc->'bankName')

          -- hasAddress: every spelling the WAVE application and the importer
          -- write onto the user row.
          OR jsonb_present(doc->'verificationProfile'->'address'->'state')
          OR jsonb_present(doc->'address'->'state')
          OR jsonb_present(doc->'state')
          OR jsonb_present(doc->'stateOfOrigin')
          OR jsonb_present(doc->'residentialState')
          OR jsonb_present(doc->'residentialAddress')
          OR jsonb_present(doc->'lga')
        THEN 'stalled'

        ELSE 'ghost'
    END;
$$;

-- Grants, guarded exactly as 029 guards them: scripts/test-migrations.sh runs
-- every migration against a throwaway cluster with no Supabase roles, and an
-- unguarded GRANT fails there with `role "anon" does not exist`.
DO $$
DECLARE
    r text;
BEGIN
    FOREACH r IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            EXECUTE format('GRANT EXECUTE ON FUNCTION jsonb_present(jsonb) TO %I', r);
            EXECUTE format('GRANT EXECUTE ON FUNCTION user_segment(jsonb) TO %I', r);
        END IF;
    END LOOP;
END $$;

-- count_user_segments() is unchanged and still calls user_segment(), so it picks
-- the new rule up without being redefined. The notify is still needed: PostgREST
-- serves RPC from a cached schema, and 029's own note records a fix that
-- silently fell back to the slow path because the cache had not been reloaded.
NOTIFY pgrst, 'reload schema';


-- ============================================================================
-- 035 — 035_decrement_many_or_fail_aggregates_duplicates.sql
-- decrement_many_or_fail, AGGREGATING DUPLICATES — #652. The guard against overselling oversold: pass 1 compared each LINE against the undecremented value, so two lines of 3 against a stock of 5 both passed and pass 2 subtracted 3 twice — ok: true, stock -1, measured against a real PostgreSQL. Every caller maps order lines to decrement items one for one and nothing between the cart and the function merges them. Amounts are summed per row before anything is locked; the id-order locking that stops concurrent orders deadlocking is unchanged. CREATE OR REPLACE over 015, transaction-safe, and it takes effect the moment it is applied — the code needs no change to benefit, though marketplace-cart.ts aggregates too so a member is refused before Paystack rather than after.
-- ============================================================================

-- 035 — THE GUARD AGAINST OVERSELLING OVERSOLD.
--
--   #652. `decrement_many_or_fail` (migration 015) is the single thing standing
--   between two buyers and the last unit of stock. Every purchase door in the
--   marketplace reserves through it, and so do the export catalogue and
--   actions/orders.ts. Its own call sites explain why it exists:
--
--       "runTransaction in this codebase takes no lock — it replays queued
--        writes after the callback returns. So two buyers ordering the last
--        unit both read availableQuantity 1, both pass the check, and both
--        write 0. Two orders, one unit: overselling."
--
--   IT DID THAT ITSELF WHENEVER ONE CALL NAMED THE SAME ROW TWICE.
--
--   Pass 1 locked each row and compared its CURRENT value against that line's
--   amount. Nothing had been decremented yet, so two lines of 3 against a stock
--   of 5 both passed — 3 ≤ 5, twice — and pass 2 then subtracted 3 twice.
--
--       stock 5, two lines of 3  ->  ok: true, stock: -1
--
--   Measured against a real PostgreSQL 16 with this schema, not reasoned about.
--   Six units taken from a stock of five, reported as success, so the order
--   completes, escrow is written and the seller is credited for goods they
--   cannot ship. The negative figure then leaks into everything downstream: the
--   card's "Only N left", the `availableQuantity === 0` tests, and the next
--   buyer's reservation, which succeeds against a number that is already a lie.
--
-- HOW A CALL COMES TO NAME ONE ROW TWICE
-- -------------------------------------
--   Every caller maps its order lines to decrement items ONE FOR ONE —
--   _payment_orders.ts in three places, _payment_verify.ts, export-payment.ts
--   and orders.ts — and nothing between the cart and here merges lines. The
--   checkout screen happens to merge on ADD, but the cart itself is localStorage
--   JSON and the action is a reachable endpoint that takes the array it is
--   given; negative-price-cart.test.ts already exercises a two-line cart for one
--   product, so the shape is not hypothetical.
--
-- THE FIX, AND WHY IT IS HERE RATHER THAN IN THE CALLERS
-- -----------------------------------------------------
--   The amounts are summed PER ROW before anything is locked, so one row is
--   locked once, compared once against the total it is being asked for, and
--   written once. A caller that sends the same product on five lines now gets
--   the same answer as one that sends it on one.
--
--   Fixing it in the callers would mean fixing it in six places and remembering
--   it in the seventh. This function's contract is "all of it or none of it, and
--   never below zero"; a contract that holds only for callers who deduplicate
--   first is not the contract its call sites believe they have.
--
-- WHAT IS UNCHANGED
-- -----------------
--   Rows are still locked in id order, so two orders naming the same products in
--   different sequences cannot deadlock. A shortfall still refuses ALL of it and
--   writes nothing. A missing field still reads as zero — an unrecorded stock is
--   not an unlimited one, and #582 records what happens when it is treated as
--   one. A non-positive amount is still an exception, raised now before any row
--   is locked rather than part-way through the walk.

CREATE OR REPLACE FUNCTION public.decrement_many_or_fail(p_items jsonb)
 RETURNS TABLE(ok boolean, failed_id text, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_row       RECORD;
    v_current   NUMERIC;
BEGIN
    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
        RAISE EXCEPTION 'decrement_many_or_fail: p_items must be a JSONB array';
    END IF;

    -- Every amount is checked BEFORE anything is locked. A bad line part-way
    -- through the array used to raise after earlier rows were already held.
    FOR v_row IN SELECT value FROM jsonb_array_elements(p_items) LOOP
        IF (v_row.value ->> 'amount')::numeric IS NULL
           OR (v_row.value ->> 'amount')::numeric <= 0 THEN
            RAISE EXCEPTION 'decrement_many_or_fail: amount must be positive for %',
                v_row.value ->> 'id';
        END IF;
    END LOOP;

    -- Pass 1 — lock every DISTINCT row, in id order, and check it can afford
    -- the TOTAL being asked of it. The GROUP BY is the fix: without it, two
    -- lines naming one row were each compared against the undecremented value.
    FOR v_row IN
        SELECT value ->> 'collection'                AS coll,
               value ->> 'id'                        AS id,
               value ->> 'field'                     AS field,
               SUM((value ->> 'amount')::numeric)    AS amount
          FROM jsonb_array_elements(p_items)
         GROUP BY 1, 2, 3
         ORDER BY 2
    LOOP
        SELECT COALESCE((raw_data ->> v_row.field)::numeric, 0)
          INTO v_current
          FROM document_collections
         WHERE id = v_row.id AND collection_name = v_row.coll
           FOR UPDATE;

        IF NOT FOUND THEN
            RETURN QUERY SELECT FALSE, v_row.id, 'not_found'::TEXT;
            RETURN;
        END IF;

        IF v_current < v_row.amount THEN
            RETURN QUERY SELECT FALSE, v_row.id, 'insufficient'::TEXT;
            RETURN;
        END IF;
    END LOOP;

    -- Pass 2 — every row is locked and sufficient, so these cannot fail. One
    -- write per row rather than one per line.
    FOR v_row IN
        SELECT value ->> 'collection'                AS coll,
               value ->> 'id'                        AS id,
               value ->> 'field'                     AS field,
               SUM((value ->> 'amount')::numeric)    AS amount
          FROM jsonb_array_elements(p_items)
         GROUP BY 1, 2, 3
    LOOP
        UPDATE document_collections
           SET raw_data = jsonb_set(
                   raw_data,
                   ARRAY[v_row.field],
                   to_jsonb(COALESCE((raw_data ->> v_row.field)::numeric, 0) - v_row.amount),
                   true
               ),
               updated_at = NOW()
         WHERE id = v_row.id AND collection_name = v_row.coll;
    END LOOP;

    RETURN QUERY SELECT TRUE, NULL::TEXT, NULL::TEXT;
END;
$function$;


-- ============================================================================
-- 004 — 004_enable_row_level_security.sql
-- row-level security — LAST, and in a low-traffic window
-- ============================================================================

-- Migration: 004_enable_row_level_security.sql
--
-- ⚠️  READ THE NOTES BELOW BEFORE APPLYING. Apply STEP 1 only.
--     The code side is ready; the rollout is not tested anywhere yet.
--
-- WHY THIS EXISTS
-- ---------------
-- schema.sql creates nine tables and never enables row-level security, and
-- there is not a single CREATE POLICY anywhere in the repository. The browser
-- authenticates to Supabase with the anon key (src/lib/supabase.ts), which is
-- public by design — it ships inside the JavaScript bundle.
--
-- With RLS disabled, that key can read and write EVERY row of EVERY table
-- directly against the Supabase REST endpoint: users, wallets, transactions,
-- processed_payments. The application's own permission checks are irrelevant,
-- because an attacker does not have to go through the application.
--
-- WHAT THIS MIGRATION ASSUMES
-- ---------------------------
-- 1. All server-side access uses the SERVICE ROLE key (supabaseAdmin in
--    src/lib/supabase.ts). The service role bypasses RLS entirely, so server
--    actions, API routes and cron jobs are unaffected by these policies.
--
-- 2. Client-side access uses the ANON key and is limited to what
--    src/lib/supabase-client-db.ts reads today:
--      - users            : own row only          (Sidebar, DashboardNav, dashboard)
--      - document_collections:
--          notifications  : own rows              (dashboard, notifications page)
--          conversations  : rows the user is a participant in (unread badges)
--      - wallets          : own row only          (dashboard balance)
--    Everything else the browser touches should move to a Server Action.
--
-- 3. The application authenticates users with NextAuth, NOT Supabase Auth
--    sessions. auth.uid() is therefore NULL for browser requests, so the
--    per-user policies in STEP 2 would deny everything and must stay
--    commented out. That is fine — see below.
--
-- WHICH OPTION THIS FILE IS NOW SET UP FOR
-- ----------------------------------------
-- OPTION A, and the code side of it is COMPLETE. Nothing in the browser
-- queries the database any more: the client components moved to Server
-- Actions first, and the three polling hooks that were missed in that pass
-- (useMembershipStatus, usePendingApplicationStatus, useUnreadNotifications)
-- followed. src/app/actions/my-data.ts holds the replacements.
--
-- So STEP 1 alone is what you apply. RLS on, no policies, anon key locked out
-- entirely. STEP 2 stays commented out unless someone later chooses Option B
-- (issue a Supabase session alongside the NextAuth one, and accept two session
-- lifetimes to keep in sync).
--
-- Confirm the precondition still holds before applying — this comment ages,
-- the grep does not:
--
--   grep -rn "from ['\"]@/lib/supabase['\"]" src/
--
-- Expect only supabaseAdmin (the service role, server-side). Any hit importing
-- the plain `supabase` client from a component or hook is a browser reader,
-- and applying this migration will silently break it.
--
-- HOW TO TEST
--   1. Restore a production backup into a staging Supabase project.
--
--      NOTE: no staging project exists today. .env.staging defines no Supabase
--      variables, and .env.local and .env.production.local point at the SAME
--      project. Until that changes, production is the first place this runs.
--
--   2. Apply this migration there.
--   3. Exercise: sign in, dashboard, notification bell, unread message badge,
--      wallet balance, cooperative pages, admin portal.
--   4. Confirm with the anon key that a signed-out client can read nothing:
--        curl "$SUPABASE_URL/rest/v1/users?select=*" -H "apikey: $ANON_KEY"
--      Expect an empty array, not rows.
--   5. Only then schedule production, during a low-traffic window.
--
-- WHAT FAILURE LOOKS LIKE
--   Not an error. With RLS on and no policy, Postgres returns ZERO ROWS to the
--   anon key rather than raising. If a browser reader was missed, it shows up
--   as members reported as non-members, empty dashboards and notification
--   counts stuck at zero — with nothing in the logs. Watch the app directly
--   after applying, and keep the rollback at the bottom of this file to hand.
--
-- ROLLBACK
--   Each ENABLE has a matching DISABLE at the bottom of this file, commented
--   out. Disabling RLS restores the current (insecure) behaviour immediately.

BEGIN;

-- ============================================================================
-- STEP 1 — Enable RLS on every table.
-- With RLS on and no policy attached, the anon key can do nothing. The service
-- role key still has full access, so the application keeps working.
-- ============================================================================

ALTER TABLE users                  ENABLE ROW LEVEL SECURITY;
ALTER TABLE cooperative_members    ENABLE ROW LEVEL SECURITY;
ALTER TABLE cooperative_loans      ENABLE ROW LEVEL SECURITY;
ALTER TABLE transactions           ENABLE ROW LEVEL SECURITY;
ALTER TABLE processed_payments     ENABLE ROW LEVEL SECURITY;
ALTER TABLE marketplace_orders     ENABLE ROW LEVEL SECURITY;
ALTER TABLE wallets                ENABLE ROW LEVEL SECURITY;
ALTER TABLE academy_applications   ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_collections   ENABLE ROW LEVEL SECURITY;

-- ============================================================================
-- STEP 2 — Per-user read policies.
--
-- APPLY THESE ONLY IF YOU CHOSE OPTION B (browser holds a Supabase session).
-- Under Option A, leave this whole section commented out: no policy means no
-- anon access, which is what you want.
--
-- Note every policy is SELECT only. The browser has never needed to write
-- directly, and it should not be able to.
-- ============================================================================

-- CREATE POLICY users_select_own ON users
--     FOR SELECT TO anon, authenticated
--     USING (id = auth.uid()::text);

-- CREATE POLICY wallets_select_own ON wallets
--     FOR SELECT TO anon, authenticated
--     USING (id = auth.uid()::text);

-- -- Notifications: rows in document_collections belonging to the caller.
-- CREATE POLICY doc_notifications_select_own ON document_collections
--     FOR SELECT TO anon, authenticated
--     USING (
--         collection_name = 'notifications'
--         AND raw_data->>'userId' = auth.uid()::text
--     );

-- -- Conversations: rows where the caller is listed as a participant.
-- -- This is the query that currently returns EVERY conversation on the
-- -- platform to EVERY signed-in browser, because the client adapter silently
-- -- dropped the array-contains filter (fixed separately in the adapter).
-- CREATE POLICY doc_conversations_select_participant ON document_collections
--     FOR SELECT TO anon, authenticated
--     USING (
--         collection_name = 'conversations'
--         AND raw_data->'participants' ? (auth.uid()::text)
--     );

COMMIT;

-- ============================================================================
-- VERIFICATION — run after applying.
-- ============================================================================
--
-- Every table should report rowsecurity = true:
--
--   SELECT tablename, rowsecurity
--     FROM pg_tables
--    WHERE schemaname = 'public'
--    ORDER BY tablename;
--
-- List whatever policies ended up attached:
--
--   SELECT tablename, policyname, cmd, roles
--     FROM pg_policies
--    WHERE schemaname = 'public'
--    ORDER BY tablename, policyname;

-- ============================================================================
-- ROLLBACK — uncomment and run to restore current behaviour.
-- ============================================================================
--
-- ALTER TABLE users                DISABLE ROW LEVEL SECURITY;
-- ALTER TABLE cooperative_members  DISABLE ROW LEVEL SECURITY;
-- ALTER TABLE cooperative_loans    DISABLE ROW LEVEL SECURITY;
-- ALTER TABLE transactions         DISABLE ROW LEVEL SECURITY;
-- ALTER TABLE processed_payments   DISABLE ROW LEVEL SECURITY;
-- ALTER TABLE marketplace_orders   DISABLE ROW LEVEL SECURITY;
-- ALTER TABLE wallets              DISABLE ROW LEVEL SECURITY;
-- ALTER TABLE academy_applications DISABLE ROW LEVEL SECURITY;
-- ALTER TABLE document_collections DISABLE ROW LEVEL SECURITY;


-- ============================================================================
-- VERIFICATION — run this after the statements above.
-- ============================================================================

-- 1. Every function should be listed. Expect 33 rows.
--
--    THIS LIST AND THIS COUNT ARE GENERATED from the migrations above, not
--    typed. Both drifted before: the count said 9 over a list of 16, then 19
--    over a list of 20, and the list was twice missing functions the deployed
--    code calls — everything from 019 onward, and later
--    claim_status_transition_in, whose absence makes every marketplace order
--    transition report a conflict instead of an error. A verification step that
--    can pass on a database missing the functions is not a verification step.
SELECT proname
  FROM pg_proc
 WHERE proname IN (
    'apply_array_ops',
    'apply_document_patch',
    'apply_increments',
    'atomic_profile_sync',
    'claim_idempotency_key',
    'claim_payment_once',
    'claim_single_open_loan_application',
    'claim_status_transition',
    'claim_status_transition_in',
    'claim_versioned_update',
    'count_user_segments',
    'credit_wallet_once',
    'debit_jsonb_balance',
    'debit_jsonb_balance_with_floor',
    'debit_wallet_locked',
    'debit_wallet_once',
    'decrement_many_or_fail',
    'enforce_member_active_on_paid',
    'find_users_by_normalised_email',
    'find_users_by_normalised_emails',
    'find_users_by_supabase_auth_ids',
    'increment_within_ceiling',
    'jsonb_array_remove',
    'jsonb_array_union',
    'jsonb_numeric_or_null',
    'jsonb_present',
    'jsonb_set_deep',
    'jsonb_text_array_or_null',
    'jsonb_truthy',
    'merge_raw_data',
    'native_column_map',
    'platform_revenue_totals',
    'user_segment'
 )
 ORDER BY proname;

-- 1b. And nothing above should be MISSING. This returns the shortfall
--     directly, so you do not have to count the rows yourself.
SELECT unnest(ARRAY[
    'apply_array_ops',
    'apply_document_patch',
    'apply_increments',
    'atomic_profile_sync',
    'claim_idempotency_key',
    'claim_payment_once',
    'claim_single_open_loan_application',
    'claim_status_transition',
    'claim_status_transition_in',
    'claim_versioned_update',
    'count_user_segments',
    'credit_wallet_once',
    'debit_jsonb_balance',
    'debit_jsonb_balance_with_floor',
    'debit_wallet_locked',
    'debit_wallet_once',
    'decrement_many_or_fail',
    'enforce_member_active_on_paid',
    'find_users_by_normalised_email',
    'find_users_by_normalised_emails',
    'find_users_by_supabase_auth_ids',
    'increment_within_ceiling',
    'jsonb_array_remove',
    'jsonb_array_union',
    'jsonb_numeric_or_null',
    'jsonb_present',
    'jsonb_set_deep',
    'jsonb_text_array_or_null',
    'jsonb_truthy',
    'merge_raw_data',
    'native_column_map',
    'platform_revenue_totals',
    'user_segment'
 ]) AS expected_function
EXCEPT
SELECT proname FROM pg_proc;
--     Expect ZERO rows. Any row is a function the application calls and this
--     database does not have.

-- 2. debit_jsonb_balance must be the NESTED-path version from 014.
--    Expect: t, 4000  — if this errors or returns the wrong balance, 013 was
--    applied after 014 and the nested-path support was reverted.
--
--   INSERT INTO users (id, email, raw_data)
--   VALUES ('deploy-check-1', 'deploy-check-1@example.com',
--           '{"serviceRegistrations":{"wave":{"waveEarningsBalance":10000}}}'::jsonb)
--   ON CONFLICT (id) DO UPDATE SET raw_data = EXCLUDED.raw_data;
--
--   SELECT * FROM debit_jsonb_balance(
--       'users', 'deploy-check-1', 'serviceRegistrations.wave.waveEarningsBalance', 6000);
--
--   DELETE FROM users WHERE id = 'deploy-check-1';

-- 3. Wallet functions must move BOTH copies of the balance (011).
--    Expect both columns equal. If native_col moves and shown_to_user does not,
--    011 was not applied and wallet credits are invisible to the application.
--
--   INSERT INTO wallets (id, balance, raw_data)
--   VALUES ('deploy-check-2', 100, '{"id":"deploy-check-2","balance":100}'::jsonb)
--   ON CONFLICT (id) DO UPDATE SET balance = 100, raw_data = EXCLUDED.raw_data;
--
--   SELECT * FROM credit_wallet_once('deploy-check-ref', 'deploy-check-2', 50);
--
--   SELECT balance AS native_col, (raw_data->>'balance')::numeric AS shown_to_user
--     FROM wallets WHERE id = 'deploy-check-2';
--
--   DELETE FROM processed_payments WHERE id = 'deploy-check-ref';
--   DELETE FROM wallets WHERE id = 'deploy-check-2';

-- 4. RLS: every table on, no policies (Option A).
SELECT tablename, rowsecurity
  FROM pg_tables
 WHERE schemaname = 'public'
 ORDER BY tablename;

SELECT count(*) AS policies_attached
  FROM pg_policies
 WHERE schemaname = 'public';

-- 5. The check the SQL Editor CANNOT make: it runs as service_role, which
--    bypasses RLS. Run this in a terminal with the ANON key. Expect [].
--
--   curl "$SUPABASE_URL/rest/v1/users?select=*" -H "apikey: $ANON_KEY"
